window.LIB_LAZY=window.LIB_LAZY||{};window.LIB_LAZY["tanakh-genesis-comentatori-ionatan"]={"chapters":[{"num":1,"title":"Capitolul 1","verses":[{"v":1,"t":"De la început a creat Domnul cerurile și pământul."},{"v":2,"t":"Iar pământul era pustiu și gol, lipsit de oameni și gol de orice vită; și întunericul era peste fața adâncului, și un duh de îndurare dinaintea Domnului sufla peste fața apelor."},{"v":3,"t":"Și Domnul a zis: „Să fie lumină, ca să lumineze sus!” Și îndată a fost lumină.","notes":["„ca să lumineze sus” (le-anhara ʿilaʾah): așa în ediția sursă; alte ediții au ʿalma, „ca să lumineze lumea”."]},{"v":4,"t":"Și Domnul a văzut lumina, că este bună; și Domnul a despărțit între lumină și întuneric."},{"v":5,"t":"Și Domnul a numit lumina „zi” și a făcut-o ca să lucreze în ea locuitorii lumii; iar întunericul l-a numit „noapte” și l-a făcut ca să se odihnească în ea făpturile. Și a fost seară și a fost dimineață: ziua întâi."},{"v":6,"t":"Și Domnul a zis: „Să fie un firmament în mijlocul apelor și să despartă între apele de sus și apele de jos.”"},{"v":7,"t":"Și Domnul a făcut firmamentul – grosimea lui este de trei degete – între marginile cerurilor și apele Oceanului; și a despărțit între apele care sunt sub firmament și apele care sunt deasupra, în bolta firmamentului. Și a fost așa."},{"v":8,"t":"Și Domnul a numit firmamentul „ceruri”. Și a fost seară și a fost dimineață: ziua a doua."},{"v":9,"t":"Și Domnul a zis: „Să se adune apele de jos, care au rămas sub ceruri, într-un singur loc, și să se usuce pământul, ca să se vadă uscatul.” Și a fost așa."},{"v":10,"t":"Și Domnul a numit uscatul „pământ”, iar locul de adunare al apelor l-a numit „mări”. Și Domnul a văzut că este bine."},{"v":11,"t":"Și Domnul a zis: „Să facă pământul să crească verdeață, iarbă a cărei sămânță se seamănă, și pomi roditori care fac rod după soiul lor, a căror sămânță este în ei, pe pământ.” Și a fost așa."},{"v":12,"t":"Și pământul a scos verdeață, iarbă a cărei sămânță se seamănă, și pomi care fac rod după soiul lor. Și Domnul a văzut că este bine."},{"v":13,"t":"Și a fost seară și a fost dimineață: ziua a treia."},{"v":14,"t":"Și Domnul a zis: „Să fie luminători în firmamentul cerurilor, ca să despartă între zi și noapte; și să fie ca semne și pentru vremile sărbătorilor, și ca să se numere prin ei socoteala zilelor, și ca să se sfințească începuturile lunilor și începuturile anilor, intercalările lunilor și intercalările anilor, solstițiile soarelui, nașterea lunii și ciclurile.”"},{"v":15,"t":"„Și să fie luminători în firmamentul cerurilor, ca să lumineze pământul.” Și a fost așa."},{"v":16,"t":"Și Domnul a făcut cei doi luminători mari; și au fost egali în slava lor douăzeci și una de ore, mai puțin șase sute șaptezeci și două de părți dintr-o oră. Și după aceea luna a vorbit împotriva soarelui cu limbă clevetitoare (lișan telitai) și a fost micșorată; și l-a rânduit pe soare, care era luminătorul mare, ca să stăpânească ziua, și pe lună, care era luminătorul mic, ca să stăpânească noaptea, și stelele.","notes":["lișan telitai: literal „limba a treia”, adică clevetirea (care îi lovește pe trei: pe cel care vorbește, pe cel care ascultă și pe cel despre care se vorbește; Arakhin 15b). O oră are aici 1080 de părți (ḥalaqim)."]},{"v":17,"t":"Și Domnul i-a rânduit după rânduielile lor în firmamentul cerurilor, ca să lumineze pământul,"},{"v":18,"t":"și ca să slujească ziua și noaptea și să despartă între lumina zilei și întunericul nopții. Și Domnul a văzut că este bine."},{"v":19,"t":"Și a fost seară și a fost dimineață: ziua a patra."},{"v":20,"t":"Și Domnul a zis: „Să mișune bălțile apelor de vietăți care se mișcă, cu suflet viu, și păsări care zboară, al căror cuib este pe pământ și calea zborului lor pe văzduhul firmamentului cerurilor.”","notes":["„al căror cuib” (ve-șarkhafteh): sensul cuvântului este nesigur; redat după interpretarea obișnuită."]},{"v":21,"t":"Și Domnul a creat monștrii cei mari, pe Leviatan și pe perechea lui, care sunt pregătiți pentru ziua mângâierii, și orice suflet viu care se mișcă, pe care apele limpezi le-au făcut să mișune, după soiurile lor, soiuri curate și soiuri necurate, și orice pasăre care zboară cu aripi, după soiurile ei, soiuri curate și soiuri necurate. Și Domnul a văzut că este bine."},{"v":22,"t":"Și Domnul i-a binecuvântat, zicând: „Fiți roditori și înmulțiți-vă și umpleți apele din mări, iar păsările să se înmulțească pe pământ.”"},{"v":23,"t":"Și a fost seară și a fost dimineață: ziua a cincea."},{"v":24,"t":"Și Domnul a zis: „Să scoată țărâna pământului suflet de făpturi după soiul lor, soiuri curate și soiuri necurate: vite, târâtoare și făpturi ale pământului, după soiul lor.” Și a fost așa."},{"v":25,"t":"Și Domnul a făcut animalele (sau „fiarele sălbatice”) pământului după soiul lor, soiuri curate și soiuri necurate, și vitele după soiul lor, și toate târâtoarele pământului după soiul lor, soiuri curate și soiuri necurate. Și Domnul a văzut că este bine."},{"v":26,"t":"Și Domnul a zis îngerilor care slujesc înaintea Lui, care fuseseră creați în ziua a doua a creării lumii: „Să facem om după chipul nostru, după asemănarea noastră; și să stăpânească peste peștii mării și peste păsările văzduhului cerurilor, peste vite și peste tot pământul și peste toate târâtoarele care se târăsc pe pământ.”"},{"v":27,"t":"Și Domnul l-a creat pe om după asemănarea Lui; după chipul Domnului l-a creat, cu două sute patruzeci și opt de mădulare, cu trei sute șaizeci și cinci de vine; și a întins peste ele pielea și l-a umplut cu carne și sânge. Parte bărbătească și parte femeiască în trupul lor i-a creat."},{"v":28,"t":"Și Domnul i-a binecuvântat, și Domnul le-a zis: „Fiți roditori și înmulțiți-vă și umpleți pământul cu fii și fiice, și întăriți-vă asupra lui cu averi, și stăpâniți peste peștii mării și peste păsările cerurilor și peste toate târâtoarele vii care se târăsc pe pământ.”"},{"v":29,"t":"Și Domnul a zis: „Iată, v-am dat toată iarba a cărei sămânță se seamănă, care este pe fața întregului pământ, și toți copacii fără rod, pentru nevoia construcției și pentru foc, și pe cei care au rod în ei, pomii a căror sămânță se seamănă: vouă să vă fie de mâncare."},{"v":30,"t":"Iar tuturor animalelor (sau „fiarelor sălbatice”) pământului, tuturor păsărilor cerurilor și tuturor celor ce se târăsc pe pământ, în care este suflet viu, toată verdeața ierburilor.” Și a fost așa."},{"v":31,"t":"Și Domnul a văzut tot ce făcuse, și era foarte bine. Și a fost seară și a fost dimineață: ziua a șasea."}]},{"num":2,"title":"Capitolul 2","verses":[{"v":1,"t":"Și s-au desăvârșit făpturile cerurilor și ale pământului și toate oștirile lor."},{"v":2,"t":"Și Domnul a desăvârșit în ziua a șaptea lucrarea Lui, pe care o făcuse, și cele zece lucruri pe care le-a creat în amurg; și S-a odihnit în ziua a șaptea de toată lucrarea Lui, pe care o făcuse.","notes":["„cele zece lucruri… create în amurg” (bein ha-șmașot, în ajunul primului Șabat): vezi Mișna Avot 5:6."]},{"v":3,"t":"Și Domnul a binecuvântat ziua a șaptea mai mult decât toate zilele săptămânii și a sfințit-o, căci în ea S-a odihnit de toată lucrarea Lui, pe care Domnul o crease și pe care avea s-o facă."},{"v":4,"t":"Acestea sunt istorisirile cerurilor și ale pământului, când au fost create, în ziua în care Domnul Dumnezeu a făcut pământul și cerurile."},{"v":5,"t":"Și niciun copac al câmpului nu era încă pe pământ, și nicio iarbă a câmpului nu încolțise încă, pentru că Domnul Dumnezeu nu dăduse ploaie pe pământ, și om nu era ca să lucreze pământul."},{"v":6,"t":"Și norul slavei cobora de sub tronul slavei și se umplea de apă din Ocean; și apoi urca de pe pământ și făcea să coboare ploaia și uda toată fața pământului."},{"v":7,"t":"Și Domnul Dumnezeu l-a creat pe om cu două porniri (yeṣarin); și a luat țărână din locul Casei Sanctuarului și din cele patru vânturi ale lumii, și a amestecat-o cu toate apele lumii, și l-a creat roșu, negru și alb; și a suflat în nările lui suflarea vieții, și suflarea a devenit în trupul omului un duh vorbitor, ca să lumineze ochii și să facă urechile să audă.","notes":["„două porniri” (yeṣarin): pornirea spre bine și pornirea spre rău (yeṣer ha-ṭov și yeṣer ha-raʿ), după dublul yod din wa-yyiṣer. „Casa Sanctuarului” = Templul."]},{"v":8,"t":"Și a fost sădită, prin Cuvântul Domnului Dumnezeu, o grădină din Eden pentru cei drepți, înainte de crearea lumii; și l-a așezat acolo pe om, când l-a creat.","notes":["„prin Cuvântul” (be-memra): expresia prin care Targumul vorbește despre lucrarea lui Dumnezeu."]},{"v":9,"t":"Și Domnul Dumnezeu a făcut să crească din pământ orice copac plăcut la vedere și bun de mâncat, și pomul vieții în mijlocul grădinii – înălțimea lui, cale de cinci sute de ani – și pomul din ale cărui roade cei care mănâncă cunosc deosebirea dintre bine și rău."},{"v":10,"t":"Și un râu ieșea din Eden ca să ude grădina, și de acolo se despărțea și devenea patru capete de râuri."},{"v":11,"t":"Numele celui dintâi este Pison; el este cel care înconjoară toată țara Indiei, unde este aurul.","notes":["Targumul redă Havila (Rosen: „ținutul Havila”) prin „țara Indiei” (Hinduqi)."]},{"v":12,"t":"Și aurul acelei țări este ales; acolo sunt bdeliumul și pietrele prețioase de beril.","notes":["„bdeliumul” (bedolḥa) și „beril” (burlin): Rosen redă versetul ebraic „cristalul și piatra onix”."]},{"v":13,"t":"Și numele râului al doilea este Ghihon; el este cel care înconjoară toată țara Cuș."},{"v":14,"t":"Și numele râului al treilea este Tigrul (Diglat); el este cel care curge la răsărit de Asiria; iar râul al patrulea este Eufratul."},{"v":15,"t":"Și Domnul Dumnezeu l-a luat pe om de pe muntele slujirii, locul din care fusese creat, și l-a așezat în grădina Edenului, ca să fie slujitor în Tora și să păzească poruncile ei.","notes":["„muntele slujirii”: muntele Templului (Moria), unde, după tradiție, a fost luată țărâna din care a fost creat omul (vezi 2:7)."]},{"v":16,"t":"Și Domnul Dumnezeu i-a poruncit omului, zicând: „Din orice copac al grădinii poți mânca;"},{"v":17,"t":"dar din pomul ale cărui roade îi fac înțelepți pe cei care le mănâncă, ca să cunoască deosebirea dintre bine și rău, să nu mănânci din el; căci în ziua în care vei mânca din el vei fi vinovat de moarte.”"},{"v":18,"t":"Și Domnul Dumnezeu a zis: „Nu este bine ca omul să doarmă singur; îi voi face o femeie, care să-i fie sprijin alături de el.”"},{"v":19,"t":"Și Domnul Dumnezeu a creat din pământ toate animalele (sau „fiarele sălbatice”) câmpului și toate păsările cerurilor și le-a adus la om, ca să vadă ce nume le va da; și orice nume pe care omul i l-a dat unui suflet dintre vietăți, acela este numele lui."},{"v":20,"t":"Și omul a dat nume tuturor vitelor și tuturor păsărilor cerurilor și tuturor animalelor (sau „fiarelor sălbatice”) câmpului; dar pentru om nu se găsise până atunci un sprijin alături de el."},{"v":21,"t":"Și Domnul Dumnezeu a aruncat un somn adânc asupra omului, și a adormit; și a luat una din coastele lui – aceasta era coasta a treisprezecea din partea dreaptă – și a închis locul cu carne."},{"v":22,"t":"Și Domnul Dumnezeu a zidit coasta pe care o luase din om, făcând din ea o femeie, și a adus-o la om."},{"v":23,"t":"Și omul a zis: „De data aceasta, și nu iarăși, va fi creată o femeie din bărbat, așa cum a fost creată aceasta din mine: os din oasele mele și carne din carnea mea. Pe aceasta se cuvine s-o numesc «femeie», căci din bărbat a fost luată aceasta.”"},{"v":24,"t":"De aceea bărbatul va lăsa și se va despărți de casa de culcare a tatălui său și a mamei sale și se va lipi de soția lui, și amândoi vor fi un singur trup."},{"v":25,"t":"Și amândoi erau înțelepți, omul și soția lui, dar nu au rămas în slava lor.","notes":["„înțelepți” (ḥakimin): Targumul citește ebraicul ʿarummim („goi”) în sensul lui ʿarum („înțelept, viclean”), ca în 3:1. „nu au rămas în slava lor”: ebraica are „și nu se rușinau”."]}]},{"num":3,"title":"Capitolul 3","verses":[{"v":1,"t":"Iar șarpele era înțelept spre rău mai mult decât toate animalele (sau „fiarele sălbatice”) câmpului pe care le făcuse Domnul Dumnezeu; și a zis femeii: „Este adevărat că Domnul Dumnezeu a zis: «Să nu mâncați din niciun copac al grădinii»?”"},{"v":2,"t":"Și femeia a zis șarpelui: „Din celelalte roade ale copacilor grădinii avem voie să mâncăm;"},{"v":3,"t":"dar despre roadele copacului care este în mijlocul grădinii, Domnul a zis: «Să nu mâncați din el și să nu vă atingeți de el, ca nu cumva să muriți.»”"},{"v":4,"t":"În acel ceas, șarpele a vorbit de rău împotriva Creatorului său și a zis femeii: „Nu veți muri; ci orice meșteșugar îl urăște pe tovarășul lui de meșteșug."},{"v":5,"t":"Căci este descoperit înaintea Domnului că, în ziua în care veți mânca din el, veți fi ca îngerii cei mari, care sunt înțelepți să cunoască deosebirea dintre bine și rău.”"},{"v":6,"t":"Și femeia l-a văzut pe Samael, îngerul morții, și s-a temut; și a știut că pomul este bun de mâncat și că este leac pentru lumina ochilor și că pomul este de dorit ca să privești la el; și a luat din rodul lui și a mâncat, și i-a dat și bărbatului ei, care era cu ea, și el a mâncat."},{"v":7,"t":"Și s-au luminat ochii amândurora și au știut că erau goi, căci fuseseră dezbrăcați de veșmântul de unghie în care fuseseră creați, și își vedeau rușinea; și și-au cusut frunze de smochin și și-au făcut brâie.","notes":["„veșmântul de unghie” (levuș ṭufra): după tradiția agadică, primii oameni fuseseră îmbrăcați cu o piele tare și strălucitoare, ca unghia."]},{"v":8,"t":"Și au auzit glasul Cuvântului Domnului Dumnezeu, care umbla prin grădină spre odihna zilei, umbla prin grădină în puterea zilei; și omul și soția lui s-au ascuns dinaintea Domnului Dumnezeu în mijlocul copacilor grădinii."},{"v":9,"t":"Și Domnul Dumnezeu l-a chemat pe om și i-a zis: „Oare nu este descoperită înaintea Mea toată lumea pe care am creat-o, întunericul ca lumina? Și cum gândești tu în inima ta să te ascunzi dinaintea Mea? Oare nu văd Eu locul în care te ascunzi? Și unde sunt poruncile pe care ți le-am poruncit?”"},{"v":10,"t":"Și a zis: „Glasul Cuvântului Tău l-am auzit în grădină și m-am temut, căci sunt gol, iar porunca pe care mi-ai poruncit-o am lepădat-o de la mine; și m-am ascuns de rușine.”"},{"v":11,"t":"Și a zis: „Cine ți-a spus că ești gol? Nu cumva ai mâncat din roadele pomului din care ți-am poruncit să nu mănânci?”"},{"v":12,"t":"Și omul a zis: „Femeia pe care ai dat-o lângă mine, ea mi-a dat din roadele pomului, și am mâncat.”"},{"v":13,"t":"Și Domnul Dumnezeu a zis femeii: „Ce este aceasta ce ai făcut?” Și femeia a zis: „Șarpele m-a amăgit cu înțelepciunea lui și m-a rătăcit cu răutatea lui, și am mâncat.”"},{"v":14,"t":"Și Domnul Dumnezeu i-a adus pe toți trei la judecată și a zis șarpelui: „Pentru că ai făcut aceasta, blestemat ești mai mult decât toate vitele și decât toate animalele (sau „fiarele sălbatice”) câmpului; pe pântecele tău vei umbla, iar picioarele tale vor fi tăiate, și pielea ta o vei lepăda o dată la șapte ani; și veninul morții va fi în gura ta, și țărână vei mânca în toate zilele vieții tale."},{"v":15,"t":"Și dușmănie voi pune între tine și femeie, între urmașii fiilor tăi și urmașii fiilor ei. Și va fi că, atunci când fiii femeii vor păzi poruncile Torei, vor ținti și te vor lovi în cap; iar când vor părăsi poruncile Torei, tu vei ținti și îi vei mușca de călcâi. Dar pentru ei va fi leac, iar pentru tine nu va fi leac; și ei vor face alinare la călcâi, în zilele Regelui Mesia.”","notes":["„vor face alinare (șefiyuta) la călcâi”: sensul exact al cuvântului este nesigur („alinare, liniștire”; unii îl înțeleg „zdrobire”); „la călcâi” se poate citi și „la sfârșit” (ʿiqba = „călcâi” și „sfârșitul zilelor”)."]},{"v":16,"t":"Femeii i-a zis: „Voi înmulți foarte mult chinurile tale, prin sângele fecioriei, și sarcinile tale; cu durere vei naște fii, și spre bărbatul tău va fi dorința ta, iar el va stăpâni peste tine, spre merit și spre păcat.”"},{"v":17,"t":"Iar omului i-a zis: „Pentru că ai primit cuvântul soției tale și ai mâncat din roadele pomului despre care ți-am poruncit, zicând: «Să nu mănânci din el», blestemat este pământul, pentru că nu ți-a arătat vina ta; cu trudă vei mânca din el în toate zilele vieții tale."},{"v":18,"t":"Și spini și mărăcini va face să încolțească și să crească pentru tine, și vei mânca iarba de pe fața câmpului.” Omul a răspuns și a zis: „Te rog, îndurare dinaintea Ta, Doamne, să nu fim socotiți ca vitele, ca să mâncăm iarba de pe fața câmpului; să ne ridicăm acum și să ne trudim cu truda mâinilor mele și să mâncăm hrană din hrana pământului; și astfel să se facă acum deosebire înaintea Ta între fiii oamenilor și fiii vitelor.”"},{"v":19,"t":"„Cu truda palmei mâinii tale vei mânca hrana, până te vei întoarce în țărâna din care ai fost creat; căci țărână ești și în țărână te vei întoarce; dar din țărână vei avea să te ridici, ca să dai judecată și socoteală pentru tot ce ai făcut, în ziua judecății celei mari.”"},{"v":20,"t":"Și omul a pus soției lui numele Eva, căci ea a fost mama tuturor fiilor oamenilor."},{"v":21,"t":"Și Domnul Dumnezeu a făcut omului și soției lui veșminte de slavă din pielea pe care o lepădase șarpele, peste pielea trupului lor, în locul podoabei lor, care le fusese dezbrăcată; și i-a îmbrăcat."},{"v":22,"t":"Și Domnul Dumnezeu a zis îngerilor care slujesc înaintea Lui: „Iată, omul era singur pe pământ, așa cum Eu sunt singur în cerurile de sus; și din el se vor ridica unii care vor ști să deosebească între bine și rău. Dacă ar fi păzit poruncile pe care i le-am poruncit, ar fi trăit și ar fi dăinuit prin pomul vieții în veci. Iar acum, fiindcă n-a păzit ce i-am poruncit, să hotărâm asupra lui și să-l izgonim din grădina Edenului, înainte ca să-și întindă mâna și să ia din roadele pomului vieții; căci iată, dacă mănâncă din el, va trăi și va dăinui în veci.”"},{"v":23,"t":"Și Domnul Dumnezeu l-a alungat din grădina Edenului; și a mers și a locuit pe muntele Moria, ca să lucreze pământul din care fusese creat."},{"v":24,"t":"Și l-a izgonit pe om din locul unde, de la început, făcuse să locuiască slava Șechinei Lui între cei doi heruvimi. Înainte de a crea lumea, a creat Tora; a pregătit grădina Edenului pentru cei drepți, ca să mănânce și să se desfete din roadele pomului, pentru că au slujit în viața lor în învățătura Torei în lumea aceasta și au împlinit poruncile; a pregătit Gheena pentru cei răi, care este asemenea unei săbii ascuțite care mănâncă din amândouă părțile; a pregătit în ea scântei de foc și cărbuni aprinși, ca să-i judece cu ele pe cei răi, care s-au răzvrătit în viața lor împotriva învățăturii Torei. Mai bună este Tora pentru cel care o slujește decât roadele pomului vieții; Cuvântul Domnului a pregătit-o pentru cel care o păzește, ca să dăinuie și să umble pe cărările drumului vieții spre lumea ce va veni.","notes":["Targumul explică „heruvimii și flacăra sabiei rotitoare… drumul către Pomul Vieții” (Rosen) prin Gheena (sabia ascuțită pe ambele părți) și prin Tora (pomul vieții)."]}]},{"num":4,"title":"Capitolul 4","verses":[{"v":1,"t":"Și omul a cunoscut-o pe Eva, soția lui, care îl dorise pe înger; și ea a zămislit și l-a născut pe Cain și a zis: „Am dobândit ca bărbat pe îngerul Domnului.”","notes":["„care îl dorise pe înger… Am dobândit ca bărbat pe îngerul Domnului”: Targumul sugerează că tatăl lui Cain a fost îngerul (Samael, cf. 3:6 și 5:3). Rosen: „Am dobândit un om cu ajutorul Domnului.”"]},{"v":2,"t":"Și a mai născut, de la bărbatul ei, Adam, pe geamăna lui și pe Abel. Și Abel era păstor de oi, iar Cain era un om care lucra pământul."},{"v":3,"t":"Și a fost, la sfârșitul zilelor, în paisprezece Nisan, că Cain a adus din rodul pământului, sămânță de in, ca jertfă de prime roade înaintea Domnului."},{"v":4,"t":"Iar Abel a adus și el din întâii-născuți ai oilor și din cele grase ale lor; și a fost plăcere înaintea Domnului, și a privit cu bunăvoință spre Abel și spre jertfa lui."},{"v":5,"t":"Dar spre Cain și spre jertfa lui nu a privit cu bunăvoință; și lui Cain i-a fost foarte greu, și trăsăturile feței lui s-au posomorât."},{"v":6,"t":"Și Domnul i-a zis lui Cain: „De ce îți este greu și de ce s-au posomorât trăsăturile feței tale?"},{"v":7,"t":"Oare dacă îți vei îndrepta faptele nu ți se va ierta vina? Iar dacă nu-ți vei îndrepta faptele în lumea aceasta, păcatul tău este păstrat pentru ziua judecății celei mari; și la ușile inimii tale păcatul stă pândind. Dar în mâna ta am dat stăpânirea asupra pornirii rele, și spre tine va fi dorința ei, iar tu vei stăpâni peste ea, fie spre merit, fie spre păcat.”"},{"v":8,"t":"Și Cain i-a zis lui Abel, fratele său: „Vino, să ieșim amândoi pe câmp.” Și a fost că, atunci când au ieșit amândoi pe câmp, Cain a răspuns și i-a zis lui Abel: „Văd că lumea a fost creată cu îndurare, dar nu este condusă după roadele faptelor bune, și este părtinire în judecată. De ce a fost primită cu plăcere jertfa ta, iar jertfa mea nu a fost primită de la mine cu plăcere?” Abel a răspuns și i-a zis lui Cain: „Lumea a fost creată cu îndurare și este condusă după roadele faptelor bune, și nu este părtinire în judecată; și pentru că roadele faptelor mele au fost mai bune decât ale tale și au venit înaintea alor tale, jertfa mea a fost primită cu plăcere.” Cain a răspuns și i-a zis lui Abel: „Nu este judecată și nu este judecător, și nu este altă lume, și nu se dă răsplată bună celor drepți și nu se ia plată de la cei răi.” Abel a răspuns și i-a zis lui Cain: „Este judecată și este judecător, și este altă lume, și se dă răsplată bună celor drepți și se ia plată de la cei răi.” Și din pricina acestor cuvinte se certau pe fața câmpului; și Cain s-a ridicat asupra lui Abel, fratele său, și i-a înfipt o piatră în frunte și l-a ucis."},{"v":9,"t":"Și Domnul i-a zis lui Cain: „Unde este Abel, fratele tău?” Și el a zis: „Nu știu; oare sunt eu păzitorul fratelui meu?”"},{"v":10,"t":"Și a zis: „Ce ai făcut? Glasul sângelui fratelui tău ucis, care a fost înghițit de țărână, strigă înaintea Mea din pământ."},{"v":11,"t":"Și acum, pentru că l-ai ucis, blestemat ești de pământul care și-a deschis gura și a primit din mâna ta sângele fratelui tău."},{"v":12,"t":"Când vei lucra pământul, nu-ți va mai da puterea roadelor lui; rătăcitor și exilat vei fi pe pământ.”"},{"v":13,"t":"Și Cain a zis înaintea Domnului: „Prea grea este răzvrătirea mea ca s-o pot purta; dar este putere înaintea Ta s-o porți."},{"v":14,"t":"Iată, m-ai izgonit astăzi de pe fața pământului; oare este cu putință să mă ascund dinaintea Ta? Și dacă voi fi rătăcitor și exilat pe pământ, orice om drept care mă va găsi mă va ucide.”"},{"v":15,"t":"Și Domnul i-a zis: „Iată, de aceea, oricine îl va ucide pe Cain, după șapte generații se va lua plată de la el.” Și Domnul a însemnat pe fața lui Cain un semn din Numele cel mare și cinstit, ca să nu-l ucidă oricine îl va găsi, când se va uita la el."},{"v":16,"t":"Și Cain a ieșit dinaintea Domnului și a locuit în țara rătăcirii exilului său, care fusese făcută pentru el de la început, în grădina Edenului.","notes":["„de la început” (mi-le-qadmin): Targumul citește ebraicul qidmat ʿEden („la răsărit de Eden”) în sensul „înainte”."]},{"v":17,"t":"Și Cain a cunoscut-o pe soția lui, și ea a zămislit și l-a născut pe Enoh; și el construia o cetate și a numit cetatea după numele fiului său, Enoh."},{"v":18,"t":"Și lui Enoh i s-a născut Irad, iar Irad l-a născut pe Mehuiael, iar Mehuiael l-a născut pe Metușael, iar Metușael l-a născut pe Lameh."},{"v":19,"t":"Și Lameh și-a luat două soții: numele uneia era Ada și numele celei de-a doua, Țila."},{"v":20,"t":"Și Ada l-a născut pe Iabal; el a fost căpetenia tuturor celor care locuiesc în corturi și au vite."},{"v":21,"t":"Și numele fratelui său era Iubal; el a fost căpetenia tuturor celor care sunt rânduiți să cânte din liră și din fluier."},{"v":22,"t":"Și Țila l-a născut și ea pe Tubal-Cain, căpetenia tuturor meșteșugarilor care se pricep la lucrul aramei și al fierului. Și sora lui Tubal-Cain era Naama; ea era stăpâna bocetelor și a cântărilor."},{"v":23,"t":"Și Lameh a zis soțiilor lui, Ada și Țila: „Ascultați glasul meu, soții ale lui Lameh, luați aminte la cuvântul meu: căci nu am ucis un bărbat, ca să fiu ucis în locul lui, și nici nu am rănit un tânăr, ca din pricina lui să piară sămânța mea."},{"v":24,"t":"Căci lui Cain, care a păcătuit și s-a întors cu pocăință, i s-a amânat pedeapsa până la șapte generații; iar lui Lameh, fiul fiului său, care nu a păcătuit, se cuvine să i se amâne până la șaptezeci și șapte.”"},{"v":25,"t":"Și Adam a cunoscut-o din nou pe soția lui, la sfârșitul a o sută treizeci de ani de când fusese ucis Abel; și ea a născut un fiu și i-a pus numele Set, căci a zis: „Domnul mi-a dat un alt fiu în locul lui Abel, pe care l-a ucis Cain.”"},{"v":26,"t":"Și lui Set i s-a născut și lui un fiu, și i-a pus numele Enoș. Aceea este generația în ale cărei zile au început să rătăcească: și-au făcut idoli și își numeau idolii cu numele Cuvântului Domnului."}]},{"num":5,"title":"Capitolul 5","verses":[{"v":1,"t":"Aceasta este cartea spițelor urmașilor lui Adam. În ziua în care Domnul l-a creat pe om, după asemănarea Domnului l-a făcut."},{"v":2,"t":"Parte bărbătească și parte femeiască i-a creat; și i-a binecuvântat în numele Cuvântului Său și le-a pus numele Adam, în ziua în care au fost creați."},{"v":3,"t":"Și Adam a trăit o sută treizeci de ani și l-a născut pe Set, care semăna cu chipul lui și cu asemănarea lui; căci mai înainte Eva îl născuse pe Cain, care nu semăna cu el; iar Abel a fost ucis de mâna lui, și Cain a fost izgonit, și urmașii lui nu au fost trecuți în spițele din cartea spițelor lui Adam. Și după aceea a născut pe unul care semăna cu el și i-a pus numele Set.","notes":["În ediția sursă lipsesc versetele 5:5–5:7; numerotarea urmează sursa."]},{"v":4,"t":"Și zilele lui Adam, după ce l-a născut pe Set, au fost opt sute de ani; și a născut fii și fiice."},{"v":8,"t":"Și toate zilele lui Set au fost nouă sute doisprezece ani, și a murit."},{"v":9,"t":"Și Enoș a trăit nouăzeci de ani și l-a născut pe Chenan."},{"v":10,"t":"Și Enoș a trăit, după ce l-a născut pe Chenan, opt sute cincisprezece ani; și a născut fii și fiice."},{"v":11,"t":"Și toate zilele lui Enoș au fost nouă sute cinci ani, și a murit."},{"v":12,"t":"Și Chenan a trăit șaptezeci de ani și l-a născut pe Mahalaleel."},{"v":13,"t":"Și Chenan a trăit, după ce l-a născut pe Mahalaleel, opt sute patruzeci de ani; și a născut fii și fiice."},{"v":14,"t":"Și toate zilele lui Chenan au fost nouă sute zece ani, și a murit."},{"v":15,"t":"Și Mahalaleel a trăit șaizeci și cinci de ani și l-a născut pe Iared."},{"v":16,"t":"Și Mahalaleel a trăit, după ce l-a născut pe Iared, opt sute treizeci de ani; și a născut fii și fiice."},{"v":17,"t":"Și toate zilele lui Mahalaleel au fost opt sute nouăzeci și cinci de ani, și a murit."},{"v":18,"t":"Și Iared a trăit o sută șaizeci și doi de ani și l-a născut pe Enoh."},{"v":19,"t":"Și Iared a trăit, după ce l-a născut pe Enoh, opt sute de ani; și a născut fii și fiice."},{"v":20,"t":"Și toate zilele lui Iared au fost nouă sute șaizeci și doi de ani, și a murit."},{"v":21,"t":"Și Enoh a trăit șaizeci și cinci de ani și l-a născut pe Metusala."},{"v":22,"t":"Și Enoh a slujit în adevăr înaintea Domnului, după ce l-a născut pe Metusala, trei sute de ani; și a născut fii și fiice."},{"v":23,"t":"Și toate zilele lui Enoh cu locuitorii pământului au fost trei sute șaizeci și cinci de ani."},{"v":24,"t":"Și Enoh a slujit în adevăr înaintea Domnului, și iată, nu mai era cu locuitorii pământului, căci a fost luat și s-a urcat la firmament prin Cuvântul dinaintea Domnului; și i-a pus numele Mețațron, marele cărturar.","notes":["Mețațron: numele îngerului cu care tradiția agadică îl identifică pe Enoh după înălțarea lui."]},{"v":25,"t":"Și Metusala a trăit o sută optzeci și șapte de ani și l-a născut pe Lameh."},{"v":26,"t":"Și Metusala a trăit, după ce l-a născut pe Lameh, șapte sute optzeci și doi de ani; și a născut fii și fiice."},{"v":27,"t":"Și toate zilele lui Metusala au fost nouă sute șaizeci și nouă de ani, și a murit."},{"v":28,"t":"Și Lameh a trăit o sută optzeci și doi de ani și a născut un fiu."},{"v":29,"t":"Și i-a pus numele Noe, zicând: „Acesta ne va mângâia de lucrul nostru, care nu izbutește, și de truda mâinilor noastre de pe pământul pe care l-a blestemat Domnul din pricina păcatelor fiilor oamenilor.”"},{"v":30,"t":"Și Lameh a trăit, după ce l-a născut pe Noe, cinci sute nouăzeci și cinci de ani; și a născut fii și fiice."},{"v":31,"t":"Și toate zilele lui Lameh au fost șapte sute șaptezeci și șapte de ani, și a murit."},{"v":32,"t":"Și Noe era în vârstă de cinci sute de ani; și Noe i-a născut pe Sem, pe Ham și pe Iafet."}]},{"num":6,"title":"Capitolul 6","verses":[{"v":1,"t":"Și a fost, când fiii oamenilor au început să se înmulțească pe fața pământului, că li s-au născut fiice frumoase."},{"v":2,"t":"Și fiii celor mari au văzut fiicele oamenilor, că erau frumoase, că își vopseau ochii și își fardau fața și umblau cu trupul descoperit; și s-au gândit la desfrânare și și-au luat soții din toate pe care le-au ales."},{"v":3,"t":"Și Domnul a zis prin Cuvântul Său: „Nu vor fi judecate toate generațiile cele rele care se vor ridica după rânduiala judecății generației potopului, ca să fie pierdute și nimicite din mijlocul lumii. Oare nu am pus Duhul Meu cel sfânt în ei, ca să facă fapte bune? Și iată, și-au stricat faptele. Iată, le-am dat răgaz o sută douăzeci de ani, ca să se pocăiască, dar nu s-au pocăit.”"},{"v":4,"t":"Șemḥazai și ʿUziel – ei sunt cei care au căzut din ceruri, și erau pe pământ în zilele acelea; și de asemenea după aceea, când fiii celor mari au intrat la fiicele oamenilor, și ele le-au născut; și aceștia sunt numiți vitejii de odinioară, oameni cu nume.","notes":["Șemḥazai și ʿUziel: în literatura agadică, numele îngerilor căzuți; Targumul redă astfel ebraicul nefilim („cei căzuți”)."]},{"v":5,"t":"Și Domnul a văzut că răutatea omului era mare pe pământ și că orice pornire a gândurilor inimii lui era numai rea în fiecare zi."},{"v":6,"t":"Și Domnul S-a căit prin Cuvântul Său că l-a făcut pe om pe pământ, și a hotărât judecată asupra lor prin Cuvântul Său."},{"v":7,"t":"Și Domnul a zis: „Voi nimici prin Cuvântul Meu pe omul pe care l-am creat, de pe fața pământului, de la om până la vită, până la târâtoare și până la păsările cerurilor, căci M-am căit prin Cuvântul Meu că i-am făcut.”"},{"v":8,"t":"Iar Noe, care era drept, a găsit bunăvoință înaintea Domnului."},{"v":9,"t":"Aceștia sunt urmașii lui Noe: acestea sunt spițele familiei lui Noe. Noe era un om drept, desăvârșit în fapte bune a fost în generațiile lui; Noe umbla în frica Domnului.","notes":["Ediția sursă începe versetul cu cuvintele ebraice ale Torei („Aceștia sunt urmașii lui Noe”, Rosen), urmate de traducerea aramaică."]},{"v":10,"t":"Și Noe a născut trei fii: pe Sem, pe Ham și pe Iafet."},{"v":11,"t":"Și pământul s-a stricat din pricina locuitorilor lui, care s-au abătut de la căile cele drepte înaintea Domnului; și pământul s-a umplut de jafuri."},{"v":12,"t":"Și Domnul a văzut pământul, și iată, se stricase; căci orice făptură își stricase, fiecare, calea pe pământ."},{"v":13,"t":"Și Domnul i-a zis lui Noe: „Sfârșitul a toată făptura a venit înaintea Mea, căci pământul s-a umplut de jafuri din pricina faptelor lor rele; și iată, Eu îi voi nimici împreună cu pământul."},{"v":14,"t":"Fă-ți o arcă din lemn de cedru (qadronin); o sută cincizeci de despărțituri să faci în arcă, în stânga ei, și treizeci și șase în lățimea ei, și zece cămări în mijloc, ca să păstrezi în ele hrana, și cinci cămări de provizii în dreapta și cinci în stânga; și s-o ungi pe dinăuntru și pe dinafară cu smoală.","notes":["qadronin: probabil „cedri”; sensul cuvântului este nesigur. În ediția sursă lipsește versetul 6:15; numerotarea urmează sursa."]},{"v":16,"t":"Du-te la Pison și ia de acolo o piatră strălucitoare și pune-o în arcă, ca să vă lumineze; și s-o termini sus, la un cot; și ușa arcei s-o pui în partea ei; cu caturi – de jos, al doilea și al treilea – s-o faci.","notes":["„o piatră strălucitoare” (yohara): Targumul înțelege ebraicul ṣohar ca pe o piatră prețioasă luminoasă adusă de la râul Pison (cf. 2:11–12)."]},{"v":17,"t":"Iar Eu, iată, aduc potopul de ape pe pământ, ca să nimicească toată făptura în care este suflarea vieții, de sub ceruri; tot ce este pe pământ va pieri."},{"v":18,"t":"Dar voi întări legământul Meu cu tine; și vei intra în arcă tu și fiii tăi și soția ta și soțiile fiilor tăi împreună cu tine."},{"v":19,"t":"Și din tot ce este viu, din toată făptura, câte doi din toate vei aduce în arcă, ca să rămână în viață cu tine; parte bărbătească și parte femeiască să fie."},{"v":20,"t":"Din păsări după soiul lor și din vite după soiul lor și din toate târâtoarele pământului după soiul lor, câte doi din toate vor intra la tine, prin mâna unui înger care le prinde și le aduce la tine, ca să rămână în viață."},{"v":21,"t":"Iar tu ia-ți din toată mâncarea care se mănâncă, și să fie de mâncare pentru tine și pentru ei.”"},{"v":22,"t":"Și Noe a făcut după tot ce i-a poruncit Domnul."}]},{"num":7,"title":"Capitolul 7","verses":[{"v":1,"t":"Și Domnul i-a zis lui Noe: „Intră tu și toți oamenii casei tale în arcă, fiindcă pe tine te-am văzut drept înaintea Mea în generația aceasta."},{"v":2,"t":"Din toate vitele curate să-ți iei câte șapte, câte șapte, parte bărbătească și parte femeiască; iar din vitele care nu sunt curate, câte două, parte bărbătească și parte femeiască."},{"v":3,"t":"Însă din păsările cerurilor câte șapte, câte șapte, parte bărbătească și parte femeiască, ca să rămână din ele sămânță pe pământ."},{"v":4,"t":"Căci iată, Eu vă dau răgaz șapte zile: dacă se vor pocăi, li se va ierta; iar dacă nu se vor pocăi, peste încă șapte zile Eu voi aduce ploaie pe pământ patruzeci de zile și patruzeci de nopți și voi nimici de pe pământ toate trupurile oamenilor și ale vitelor.”"},{"v":5,"t":"Și Noe a făcut după tot ce i-a poruncit Domnul."},{"v":6,"t":"Și Noe era în vârstă de șase sute de ani, iar potopul de ape a venit pe pământ."},{"v":7,"t":"Și Noe și fiii lui și soția lui și soțiile fiilor lui au intrat împreună cu el în arcă, din pricina apelor potopului."},{"v":8,"t":"Din vitele curate și din vitele care nu sunt curate și din păsări și din tot ce se târăște pe pământ,"},{"v":9,"t":"câte două, câte două au intrat la Noe în arcă, parte bărbătească și parte femeiască, așa cum îi poruncise Domnul lui Noe."},{"v":10,"t":"Și a fost, după șapte zile, după ce se încheiase jelirea pentru Metusala, Domnul a văzut, și iată, fiii oamenilor nu se pocăiseră; și apele potopului coborau fierbinți din ceruri pe pământ."},{"v":11,"t":"În anul al șase sutelea al vieții lui Noe, în luna a doua – aceasta este luna Marḥeșvan, căci până atunci lunile nu erau numărate decât de la Tișri, care era începutul anului pentru desăvârșirea lumii –, în ziua a șaptesprezecea a lunii, în ziua aceasta s-au rupt toate izvoarele marelui adânc; și fiii uriașilor își puneau acolo copiii și le astupau, iar după aceea s-au deschis zăgazurile cerurilor."},{"v":12,"t":"Și ploaia a coborât pe pământ patruzeci de zile și patruzeci de nopți."},{"v":13,"t":"Chiar în ziua aceasta au intrat Noe, Sem, Ham și Iafet, fiii lui Noe, și soția lui Noe și cele trei soții ale fiilor lui împreună cu el în arcă;"},{"v":14,"t":"ei și toate animalele (sau „fiarele sălbatice”) după soiul lor și toate vitele după soiul lor și toate târâtoarele care se târăsc pe pământ după soiul lor, toate păsările după soiul lor, toate zburătoarele, tot ce zboară."},{"v":15,"t":"Și au intrat la Noe în arcă câte două, câte două din toată făptura în care este suflarea vieții."},{"v":16,"t":"Și cele care au intrat, parte bărbătească și parte femeiască din toată făptura, au intrat așa cum îi poruncise Domnul; și Cuvântul Domnului a ocrotit ușa arcei în fața lui."},{"v":17,"t":"Și potopul a fost patruzeci de zile pe pământ; și apele au crescut și au ridicat arca, și ea s-a înălțat deasupra pământului."},{"v":18,"t":"Și apele au fost puternice și au crescut foarte mult pe pământ, și arca mergea plutind pe fața apelor."},{"v":19,"t":"Și apele au fost foarte puternice pe pământ, și au fost acoperiți toți munții înalți care sunt sub toate cerurile."},{"v":20,"t":"Cincisprezece coți deasupra au fost puternice apele, și munții au fost acoperiți."},{"v":21,"t":"Și a pierit toată făptura care se târăște pe pământ: păsări, vite, animale (sau „fiare sălbatice”) și toate târâtoarele care se târăsc pe pământ, și toți fiii oamenilor."},{"v":22,"t":"Tot ce avea în nări suflarea duhului vieții, din tot ce era pe uscat, a murit."},{"v":23,"t":"Și a nimicit toate trupurile oamenilor și ale vitelor care erau pe fața pământului, de la om până la vită, până la târâtoare și până la pasărea care zboară în văzduhul cerurilor; și au fost nimicite de pe pământ, și au rămas doar Noe și cei care erau cu el în arcă."},{"v":24,"t":"Și apele au fost puternice pe pământ o sută cincizeci de zile."}]},{"num":8,"title":"Capitolul 8","verses":[{"v":1,"t":"Și Domnul Și-a adus aminte prin Cuvântul Său de Noe și de toate animalele (sau „fiarele sălbatice”) și de toate vitele care erau cu el în arcă; și Domnul a trecut un duh de milă peste pământ, și apele s-au potolit."},{"v":2,"t":"Și s-au închis izvoarele adâncului și zăgazurile cerurilor, și ploaia a fost oprită să mai coboare din ceruri."},{"v":3,"t":"Și apele s-au retras de pe pământ, ducându-se și întorcându-se; și apele au scăzut la sfârșitul celor o sută cincizeci de zile."},{"v":4,"t":"Și arca s-a așezat în luna a șaptea – aceasta este luna Nisan –, în ziua a șaptesprezecea a lunii, pe munții Qardon; numele unui munte este Qardonya și numele celuilalt munte este Armenia, și acolo a fost zidită cetatea Armeniei, în țara răsăritului.","notes":["Rosen: „pe munții Ararat”; Targumul identifică locul cu munții Qardon (Kardu)."]},{"v":5,"t":"Și apele s-au tot dus și au scăzut până în luna a zecea, luna Tamuz; în Tamuz, în ziua întâi a lunii, s-au arătat vârfurile munților."},{"v":6,"t":"Și a fost, la sfârșitul a patruzeci de zile, că Noe a deschis fereastra arcei pe care o făcuse."},{"v":7,"t":"Și i-a dat drumul corbului, și el a ieșit, tot ducându-se și întorcându-se, până când s-au uscat apele de pe pământ."},{"v":8,"t":"Și a trimis de la el porumbelul de casă, ca să vadă dacă s-au micșorat apele de pe fața pământului."},{"v":9,"t":"Dar porumbelul nu a găsit odihnă pentru talpa piciorului său și s-a întors la el în arcă și i-a dat de știre că erau ape pe fața întregului pământ; și el și-a întins mâna și l-a luat și l-a adus la sine în arcă."},{"v":10,"t":"Și a mai așteptat încă șapte zile și a trimis din nou porumbelul din arcă."},{"v":11,"t":"Și porumbelul a venit la el la vremea serii, și iată, o frunză de măslin, ruptă, frântă și pusă în ciocul lui, pe care o luase de pe Muntele Măslinilor; și Noe a știut că apele se micșoraseră de pe pământ."},{"v":12,"t":"Și a mai așteptat încă șapte zile și a trimis din nou porumbelul, și el nu s-a mai întors la el."},{"v":13,"t":"Și a fost, în anul al șase sute unulea, în Tișri, în ziua întâi a lunii, la începutul anului, că apele s-au zvântat de pe pământ; și Noe a dat la o parte acoperământul arcei și s-a uitat, și iată, fața pământului se zvântase."},{"v":14,"t":"Și în luna Marḥeșvan, în ziua a douăzeci și șaptea a lunii, pământul s-a uscat."},{"v":15,"t":"Și Domnul i-a vorbit lui Noe, zicând:"},{"v":16,"t":"„Ieși din arcă tu și soția ta și fiii tăi și soțiile fiilor tăi împreună cu tine."},{"v":17,"t":"Toate animalele (sau „fiarele sălbatice”) care sunt cu tine, din toată făptura – păsări, vite și toate târâtoarele care se târăsc pe pământ –, scoate-le cu tine, ca să se nască pe pământ și să rodească și să se înmulțească pe pământ.”"},{"v":18,"t":"Și Noe a ieșit, și fiii lui și soția lui și soțiile fiilor lui împreună cu el."},{"v":19,"t":"Toate animalele (sau „fiarele sălbatice”), toate târâtoarele și toate păsările, tot ce se târăște pe pământ, după neamurile lor, au ieșit din arcă."},{"v":20,"t":"Și Noe a zidit un altar înaintea Domnului – acesta este altarul pe care l-a zidit Adam în vremea când a fost izgonit din grădina Edenului și pe care a adus jertfă, și pe care Cain și Abel și-au adus jertfele; iar când au coborât apele potopului, a fost dărâmat, și Noe l-a zidit din nou – și a luat din toate vitele curate și din toate păsările curate și a adus patru pe acel altar.","notes":["„a adus patru”: sursa are doar „patru”, fără substantiv; se subînțelege probabil „arderi-de-tot”; tradus după sursă."]},{"v":21,"t":"Și Domnul a primit cu bunăvoință jertfa lui, și Domnul a zis prin Cuvântul Său: „Nu voi mai blestema iarăși pământul din pricina păcatelor fiilor oamenilor, căci pornirea inimii omului este rea din tinerețea lui; și nu voi mai lovi iarăși tot ce este viu, cum am făcut."},{"v":22,"t":"Cât vor mai fi toate zilele pământului, semănatul în anotimpul lui Tișri și secerișul în anotimpul lui Nisan, frigul în anotimpul lui Tevet și căldura în anotimpul lui Tamuz, vara și iarna, ziua și noaptea nu vor înceta.”"}]},{"num":9,"title":"Capitolul 9","verses":[{"v":1,"t":"Și Domnul i-a binecuvântat pe Noe și pe fiii lui și le-a zis: „Rodiți și înmulțiți-vă și umpleți pământul."},{"v":2,"t":"Și teama de voi și groaza de voi să fie peste toate animalele (sau „fiarele sălbatice”) pământului și peste toate păsările cerurilor, peste tot ce mișună pe pământ și peste toți peștii mării; în mâna voastră vor fi date."},{"v":3,"t":"Orice târâtoare care este vie să vă fie de mâncare; ca iarba verde, v-am dat totul."},{"v":4,"t":"Însă carnea tăiată dintr-un animal viu, cât timp sufletul lui este în el, sau tăiată dintr-un animal înjunghiat înainte ca suflarea să fi ieșit cu totul din el, să nu o mâncați."},{"v":5,"t":"Și negreșit sângele vostru, al sufletelor voastre, îl voi cere din mâna oricărui animal (sau „oricărei fiare sălbatice”) care ucide un om – îl voi cere, ca să fie ucis pentru el; și din mâna omului, din mâna omului care varsă sângele fratelui său, voi cere sufletul omului."},{"v":6,"t":"Cine varsă sângele omului în fața martorilor, judecătorii îl vor osândi la moarte; iar cine varsă fără martori, Stăpânul lumii îi va cere socoteală în ziua judecății celei mari; căci după chipul Domnului l-a făcut pe om."},{"v":7,"t":"Iar voi, rodiți și înmulțiți-vă, nașteți-vă pe pământ și înmulțiți-vă pe el.”"},{"v":8,"t":"Și Domnul le-a zis lui Noe și fiilor lui, care erau cu el, zicând:"},{"v":9,"t":"„Eu, iată, Eu întăresc legământul Meu cu voi și cu fiii voștri după voi,"},{"v":10,"t":"și cu orice suflet viu care este cu voi – păsări, vite și toate animalele (sau „fiarele sălbatice”) pământului care sunt cu voi –, din toate cele care au ieșit din arcă, pentru toate animalele (sau „fiarele sălbatice”) pământului."},{"v":11,"t":"Și voi întări legământul Meu cu voi: nicio făptură nu va mai fi nimicită de apele potopului și nu va mai fi potop ca să pustiască pământul.”"},{"v":12,"t":"Și Domnul a zis: „Acesta este semnul legământului pe care îl întăresc între Cuvântul Meu și voi și orice suflet viu care este cu voi, pentru generațiile lumii:"},{"v":13,"t":"Curcubeul Meu l-am pus în nor, și el va fi semnul legământului între Cuvântul Meu și pământ."},{"v":14,"t":"Și va fi, când voi întinde norii slavei peste pământ, curcubeul se va vedea ziua, înainte ca soarele să apună în nor."},{"v":15,"t":"Și Îmi voi aduce aminte de legământul Meu, care este între Cuvântul Meu și voi și orice suflet viu din toată făptura; și apele nu vor mai fi un potop ca să nimicească toată făptura."},{"v":16,"t":"Și curcubeul va fi în nor, și îl voi vedea, ca să-Mi aduc aminte de legământul veșnic dintre Cuvântul Domnului și orice suflet viu din toată făptura care este pe pământ.”"},{"v":17,"t":"Și Domnul i-a zis lui Noe: „Acesta este semnul legământului pe care l-am întărit între Cuvântul Meu și cuvântul a toată făptura care este pe pământ.”"},{"v":18,"t":"Și fiii lui Noe care au ieșit din arcă erau Sem, Ham și Iafet; și Ham este tatăl lui Canaan."},{"v":19,"t":"Aceștia trei sunt fiii lui Noe, și de la ei s-au răspândit ca să locuiască pe tot pământul."},{"v":20,"t":"Și Noe a început să fie un om care lucrează pământul; și a găsit o viță pe care râul o adusese din grădina Edenului, și a sădit-o ca vie; și chiar în ziua aceea a înflorit și a copt struguri, și el i-a stors."},{"v":21,"t":"Și a băut din vin și s-a îmbătat și s-a dezgolit în cortul lui."},{"v":22,"t":"Și Ham, tatăl lui Canaan, a văzut goliciunea tatălui său și le-a spus celor doi frați ai săi în piață."},{"v":23,"t":"Și Sem și Iafet au luat haina și au pus-o pe umerii amândurora și au mers îndărăt și au acoperit goliciunea tatălui lor; iar fețele lor erau întoarse îndărăt, și goliciunea tatălui lor nu au văzut-o."},{"v":24,"t":"Și Noe s-a trezit din vinul lui și a aflat, prin povestirea unui vis, ce îi făcuse Ham, fiul lui, care era mic în merite, pentru că pricinuise ca el să nu mai nască un al patrulea fiu."},{"v":25,"t":"Și a zis: „Blestemat să fie Canaan, care este al patrulea fiu al lui; rob supus să fie pentru frații lui.”"},{"v":26,"t":"Și a zis: „Binecuvântat fie Domnul, Dumnezeul lui Sem, ale cărui fapte sunt drepte; și de aceea Canaan să-i fie rob."},{"v":27,"t":"Domnul să lărgească hotarele lui Iafet, și fiii lui să devină prozeliți și să locuiască în casa de învățătură a lui Sem; și Canaan să le fie rob.”"},{"v":28,"t":"Și Noe a trăit după potop trei sute cincizeci de ani."},{"v":29,"t":"Și toate zilele lui Noe au fost nouă sute cincizeci de ani, și a murit."}]},{"num":10,"title":"Capitolul 10","verses":[{"v":1,"t":"Acestea sunt spițele fiilor lui Noe; și li s-au născut fii după potop."},{"v":2,"t":"Fiii lui Iafet: Gomer și Magog și Madai și Iavan și Tubal și Meșec și Tiras; și numele provinciilor lor: Africa și Germania și Media și Macedonia și Bitinia și Asia și Tracia.","notes":["Numele provinciilor (aici și la 10:4, 10:6–7, 10:10–14, 10:17–19, 10:30) sunt redate după sursă; identificările cu locuri cunoscute sunt cele uzuale, iar formele nesigure sunt transcrise."]},{"v":3,"t":"Și fiii lui Gomer: Așchenaz și Rifat și Togarma."},{"v":4,"t":"Și fiii lui Iavan: Elișa, Elas și Tars, Ahaia și Dardania."},{"v":5,"t":"De la aceștia s-au despărțit familiile insulelor neamurilor, fiecare după limba lui, după spițele lor, în neamurile lor."},{"v":6,"t":"Și fiii lui Ham: Cuș și Mițraim și Put și Canaan; și numele provinciilor lor: Arabia și Egipt („Mițrayim”) și Eliḥaroq și Canaan."},{"v":7,"t":"Și fiii lui Cuș: Seba și Havila și Sabta și Rama și Sabteca; și numele provinciilor lor: Siniraii și Hinduki și Samidaii și Luvaii și Zingaii; și fiii lui Mauritinos: Zemadgad și Mezag."},{"v":8,"t":"Și Cuș l-a născut pe Nimrod; el a început să fie viteaz în păcat și în răzvrătire înaintea Domnului pe pământ."},{"v":9,"t":"El a fost un viteaz răzvrătit înaintea Domnului; de aceea se spune: „De când a fost creată lumea nu a fost ca Nimrod, viteaz la vânătoare și în răzvrătire înaintea Domnului.”"},{"v":10,"t":"Și începutul împărăției lui a fost Babilonul cel mare și Hadas și Nețivin și Ctesifon, în țara Pontului.","notes":["Rosen: „Babel; și Erec, Acad și Calne în țara Șinear”; Targumul redă numele prin cetăți cunoscute în vremea lui."]},{"v":11,"t":"Din țara aceea a ieșit Nimrod și a domnit în Asur, pentru că nu a vrut să fie în sfatul generației dezbinării și a părăsit aceste patru cetăți; și de aceea Domnul i-a dat un loc, și a zidit alte patru cetăți: Ninive și cetatea Pelaṭiat și Peryot","notes":["„generația dezbinării”: generația turnului Babel (cap. 11)."]},{"v":12,"t":"și Telasar, care este zidită între Ninive și Ḥadyat; aceasta este cetatea cea mare."},{"v":13,"t":"Și Mițraim i-a născut pe nivvoṭai și pe marṭiyoṭai și pe livvqai și pe penṭaskinai"},{"v":14,"t":"și pe nasyoṭai și pe penṭapoloṭai – din care au ieșit filistenii – și pe capadocieni."},{"v":15,"t":"Și Canaan l-a născut pe Sidon, întâiul său născut, și pe Het,"},{"v":16,"t":"și pe iebusiți și pe amoriți și pe ghirgașiți,"},{"v":17,"t":"și pe hiviți și pe arkiți și pe anṭosai,"},{"v":18,"t":"și pe loṭsai și pe ḥumṣai și pe anṭekhai; și după aceea s-au răspândit familiile canaaniților."},{"v":19,"t":"Și hotarul canaaniților era de la Kotnayim, venind către Gherar, până la Gaza; venind spre Sodoma și Gomora, Adma și Țeboim, până la Qaldehi."},{"v":20,"t":"Aceștia sunt fiii lui Ham, după familiile spițelor lor, după limbile lor, în așezările țărilor lor, în familiile neamurilor lor."},{"v":21,"t":"Și lui Sem i s-a născut și lui un fiu; el este tatăl tuturor fiilor evreilor, fratele lui Iafet, mare în frica Domnului.","notes":["Rosen: „tatăl tuturor celor de dincolo, fratele lui Iafet cel mare”; Targumul înțelege ʿever ca „evrei” și „cel mare” ca „mare în frica Domnului”."]},{"v":22,"t":"Fiii lui Sem: Elam și Asur și Arpacșad și Lud și Aram.","notes":["În ediția sursă lipsește versetul 10:23; numerotarea urmează sursa."]},{"v":24,"t":"Și Arpacșad l-a născut pe Șelah, și Șelah l-a născut pe Eber."},{"v":25,"t":"Și lui Eber i s-au născut doi fii: numele unuia era Peleg, fiindcă în zilele lui a fost împărțit pământul; și numele fratelui său era Ioctan."},{"v":26,"t":"Și Ioctan l-a născut pe Almodad, care a măsurat pământul cu funii, și pe Șelef, care a scos apele râurilor, și pe Hațarmavet și pe Ierah,"},{"v":27,"t":"și pe Hadoram și pe Uzal și pe Dicla,"},{"v":28,"t":"și pe Obal și pe Abimael și pe Șeba,"},{"v":29,"t":"și pe Ofir și pe Havila și pe Iobab; toți aceștia sunt fiii lui Ioctan."},{"v":30,"t":"Și locul așezărilor lor era de la Meșa, venind către Sefarvai, muntele răsăritului."},{"v":31,"t":"Aceștia sunt fiii lui Sem, după spițele lor, în așezările țărilor lor, după familiile neamurilor lor."},{"v":32,"t":"Acestea sunt spițele fiilor lui Noe, după spițele lor, în neamurile lor; și de la aceștia s-au despărțit neamurile pe pământ după potop."}]},{"num":11,"title":"Capitolul 11","verses":[{"v":1,"t":"Și tot pământul avea o singură limbă și o singură vorbire și un singur sfat; vorbeau în limba sfântă, prin care fusese creată lumea de la început."},{"v":2,"t":"Și a fost, când au călătorit dinspre răsărit, au găsit o vale în țara Babel și s-au așezat acolo.","notes":["Rosen: „în țara Șinear”; Targumul are „în țara Babel”."]},{"v":3,"t":"Și și-au zis unul altuia: „Haideți să facem cărămizi și să le punem în cuptor.” Și cărămida le-a fost drept piatră, iar lutul le-a fost drept mortar."},{"v":4,"t":"Și au zis: „Haideți să ne construim un oraș și un turn al cărui vârf să ajungă până la înălțimea cerurilor, și să ne facem în vârful lui un idol, și să-i punem o sabie în mână, ca să facă împotriva Lui rânduieli de luptă, înainte să fim împrăștiați de pe fața pământului.”"},{"v":5,"t":"Și S-a arătat Domnul ca să-i pedepsească pentru lucrarea orașului și a turnului pe care le-au construit fiii oamenilor."},{"v":6,"t":"Și a zis Domnul: „Iată, un singur popor și o singură limbă au toți, și aceasta s-au gândit să facă; și acum nu li se va împiedica nimic din tot ce s-au gândit să facă.”"},{"v":7,"t":"Și a zis Domnul către cei șaptezeci de îngeri care stau înaintea Lui: „Veniți acum, să coborâm și să le încurcăm acolo limba, ca să nu înțeleagă omul limba semenului său.”"},{"v":8,"t":"Și S-a arătat Cuvântul Domnului asupra orașului, și cu El cei șaptezeci de îngeri, corespunzător celor șaptezeci de popoare, și fiecare avea în mână limba poporului său (după altă versiune: și semnul scrierii lui) (și de acolo kafteh); și i-a împrăștiat de acolo pe fața întregului pământ, în șaptezeci de limbi, și nu știa unul ce spune semenul său, și se omorau unul pe altul; și s-au oprit din a construi orașul.","notes":["Cele două paranteze sunt în ediția sursă (variante de text). Prima are în sursă indicația „altă versiune”; a doua (u-mi-șam kafteh) are un sens nesigur și este redată „și de acolo”, cu ultimul cuvânt transcris."]},{"v":9,"t":"De aceea i-a pus numele Babel, căci acolo a încurcat Domnul limba tuturor locuitorilor pământului, și de acolo i-a împrăștiat Domnul pe fața întregului pământ."},{"v":10,"t":"Aceștia sunt urmașii lui Sem: Sem avea o sută de ani când l-a născut pe Arpacșad, la doi ani după potop."},{"v":11,"t":"Și a trăit Sem, după ce l-a născut pe Arpacșad, cinci sute de ani și a născut fii și fiice."},{"v":12,"t":"Și Arpacșad a trăit treizeci și cinci de ani și l-a născut pe Șelah."},{"v":13,"t":"Și a trăit Arpacșad, după ce l-a născut pe Șelah, patru sute trei ani și a născut fii și fiice."},{"v":14,"t":"Și Șelah a trăit treizeci de ani și l-a născut pe Eber."},{"v":15,"t":"Și a trăit Șelah, după ce l-a născut pe Eber, patru sute trei ani și a născut fii și fiice."},{"v":16,"t":"Și Eber a trăit treizeci și patru de ani și l-a născut pe Peleg."},{"v":17,"t":"Și a trăit Eber, după ce l-a născut pe Peleg, patru sute treizeci de ani și a născut fii și fiice."},{"v":18,"t":"Și Peleg a trăit treizeci de ani și l-a născut pe Reu."},{"v":19,"t":"Și a trăit Peleg, după ce l-a născut pe Reu, două sute nouă ani și a născut fii și fiice."},{"v":20,"t":"Și Reu a trăit treizeci și doi de ani și l-a născut pe Serug."},{"v":21,"t":"Și a trăit Reu, după ce l-a născut pe Serug, două sute șapte ani și a născut fii și fiice."},{"v":22,"t":"Și Serug a trăit treizeci de ani și l-a născut pe Nahor."},{"v":23,"t":"Și a trăit Serug, după ce l-a născut pe Nahor, două sute de ani și a născut fii și fiice."},{"v":24,"t":"Și Nahor a trăit douăzeci și nouă de ani și l-a născut pe Terah."},{"v":25,"t":"Și a trăit Nahor, după ce l-a născut pe Terah, o sută nouăsprezece ani și a născut fii și fiice."},{"v":26,"t":"Și Terah a trăit șaptezeci de ani și i-a născut pe Avram, pe Nahor și pe Haran."},{"v":27,"t":"Și aceștia sunt urmașii lui Terah: Terah i-a născut pe Avram, pe Nahor și pe Haran; și Haran l-a născut pe Lot."},{"v":28,"t":"Și a fost, când l-a aruncat Nimrod pe Avram în cuptorul de foc, pentru că nu slujea idolilor lui, și focul nu a avut putere să-l ardă, atunci s-a împărțit inima lui Haran, zicând: „Dacă biruiește Nimrod, voi fi din tabăra lui, și dacă biruiește Avram, voi fi din tabăra lui.” Și când au văzut toate popoarele care erau acolo că focul nu a stăpânit asupra lui Avram, au zis în inima lor: „Oare nu este Haran, fratele lui Avram, plin de vrăji și de farmece, și el a descântat focul ca să nu-l ardă pe fratele lui?” Îndată a căzut foc din cerurile de sus și l-a mistuit; și a murit Haran, văzând tatăl său Terah cum a fost ars, în țara nașterii lui, în cuptorul de foc pe care caldeenii îl făcuseră pentru Avram, fratele lui.","notes":["Rosen: „Și a murit Haran înaintea tatălui său Terah, în țara sa natală, în Ur Casdim.” Targumul înțelege Ur („foc”) drept cuptorul de foc în care a fost aruncat Avram."]},{"v":29,"t":"Și și-au luat Avram și Nahor soții: numele soției lui Avram era Sarai și numele soției lui Nahor era Milca, fiica lui Haran, tatăl Milcăi și tatăl Iscăi; aceea este Sarai.","notes":["„aceea este Sarai”: Targumul o identifică pe Isca cu Sarai."]},{"v":30,"t":"Și Sarai era stearpă, nu avea copil."},{"v":31,"t":"Și Terah i-a luat pe Avram, fiul său, și pe Lot, fiul lui Haran, fiul fiului său, și pe Sarai, nora sa, soția fiului său Avram, și au ieșit împreună cu ei din Ur Casdim, ca să meargă în țara Canaanului; și au ajuns până în Haran și s-au așezat acolo."},{"v":32,"t":"Și zilele lui Terah au fost două sute cinci ani, și a murit Terah în Haran."}]},{"num":12,"title":"Capitolul 12","verses":[{"v":1,"t":"Și a zis Domnul către Avram: „Du-te, pleacă din țara ta, desparte-te de rudenia ta, ieși din casa tatălui tău, du-te în țara pe care ți-o voi arăta."},{"v":2,"t":"Și te voi face un popor mare și te voi binecuvânta și îți voi face mare numele, și vei fi binecuvântat."},{"v":3,"t":"Și îi voi binecuvânta pe preoții care își întind mâinile în rugăciune și îi binecuvântează pe fiii tăi, iar pe Balaam, care îi blestemă, îl voi blestema, și îl vor ucide cu ascuțișul sabiei; și se vor binecuvânta prin tine toate familiile pământului.”","notes":["Rosen: „Îi voi binecuvânta pe cei care te binecuvântează, iar pe cel care te blestemă îl voi blestema.” Targumul îi identifică pe cei care binecuvântează cu preoții (binecuvântarea preoțească), iar pe cel care blestemă cu Balaam (Numeri 22–24; moartea lui prin sabie: Numeri 31:8)."]},{"v":4,"t":"Și s-a dus Avram, cum îi vorbise Domnul, și s-a dus cu el Lot; și Avram avea șaptezeci și cinci de ani când a ieșit din Haran."},{"v":5,"t":"Și Avram a luat-o pe Sarai, soția sa, și pe Lot, fiul fratelui său, și toate averile lor pe care le agonisiseră și sufletele pe care le convertiseră în Haran, și au ieșit ca să meargă în țara Canaanului; și au ajuns în țara Canaanului.","notes":["„pe care le convertiseră” (di gayyeru): Targumul înțelege „sufletele pe care le făcuseră” (Rosen) ca pe oamenii aduși la credința în Dumnezeu."]},{"v":6,"t":"Și Avram a trecut prin țară până la locul Sihem, până la câmpia More; iar canaaniții erau atunci în țară, pentru că încă nu sosise vremea ca fiii lui Israel s-o moștenească.","notes":["Rosen: „până la Elon More”."]},{"v":7,"t":"Și S-a arătat Domnul lui Avram și a zis: „Fiilor tăi le voi da țara aceasta.” Și a construit acolo un altar înaintea Domnului, care i Se arătase."},{"v":8,"t":"Și s-a mutat de acolo la muntele de la răsărit de Betel și și-a întins cortul, cu Betel la apus și Ai la răsărit; și a construit acolo un altar înaintea Domnului și s-a rugat în Numele Domnului."},{"v":9,"t":"Și Avram a pornit, mergând și călătorind către miazăzi."},{"v":10,"t":"Și a fost foamete în țară, și Avram a coborât în Egipt („Mițrayim”) ca să locuiască acolo ca străin, căci foametea era grea în țară."},{"v":11,"t":"Și a fost, când s-a apropiat să intre în hotarul Egiptului („Mițrayim”), au ajuns la râu și și-au dezvelit trupurile ca să treacă, și a zis Avram către Sarai, soția sa: „Iată, până acum nu m-am uitat la trupul tău, și acum știu că ești o femeie frumoasă la înfățișare."},{"v":12,"t":"Și va fi, când se vor uita la tine egiptenii și vor vedea frumusețea ta, vor zice: «Aceasta este soția lui», și mă vor ucide pe mine, iar pe tine te vor lăsa în viață."},{"v":13,"t":"Spune, te rog, că ești sora mea, ca să-mi fie bine datorită ție și să-mi rămână sufletul în viață din pricina ta.”"},{"v":14,"t":"Și a fost, când a intrat Avram în Egipt („Mițrayim”), egiptenii au văzut femeia, că era foarte frumoasă."},{"v":15,"t":"Și au văzut-o dregătorii lui Faraon și i-au lăudat-o lui Faraon, și femeia a fost dusă în casa regală a lui Faraon."},{"v":16,"t":"Iar lui Avram Faraon i-a făcut bine din pricina ei, și a avut din averea lui oi și boi și măgari și robi și roabe și măgărițe și cămile."},{"v":17,"t":"Și Cuvântul Domnului a trimis asupra lui Faraon și asupra oamenilor casei lui urgii mari, din pricina Sarei, soția lui Avram."},{"v":18,"t":"Și Faraon l-a chemat pe Avram și a zis: „Ce este aceasta ce mi-ai făcut? De ce nu mi-ai spus că ea este soția ta?"},{"v":19,"t":"De ce ai spus: «Ea este sora mea», și am luat-o de soție? Și îndată a fost trimisă asupra mea urgia, și nu m-am apropiat de ea. Și acum, iată soția ta: ia-o și du-te.”"},{"v":20,"t":"Și Faraon a poruncit unor oameni în privința lui, și l-au însoțit pe el și pe soția lui și tot ce era al lui."}]},{"num":13,"title":"Capitolul 13","verses":[{"v":1,"t":"Și Avram a urcat din Egipt („Mițrayim”), el și soția lui și tot ce era al lui, și Lot cu el, ca să meargă în miazăzi."},{"v":2,"t":"Și Avram era foarte bogat în vite, în argint și în aur."},{"v":3,"t":"Și a mers în călătoriile lui de la miazăzi până la Betel și s-a întors până la locul unde își întinsese cortul la început, între Betel și Ai,"},{"v":4,"t":"la locul altarului pe care îl făcuse acolo la început; și s-a rugat acolo Avram în Numele Domnului."},{"v":5,"t":"Și de asemenea Lot, care era călăuzit prin meritul lui Avram, avea oi și boi și corturi."},{"v":6,"t":"Și țara nu-i mai putea purta ca să locuiască împreună, căci averile lor erau multe și nu puteau locui împreună."},{"v":7,"t":"Și era ceartă între păstorii vitelor lui Avram și păstorii vitelor lui Lot, pentru că păstorilor lui Avram li se poruncise de el: „Nu umblați printre canaaniți și printre periziți, care încă au stăpânire în țară”, și își legau botul animalelor ca să nu mănânce din ce era furat, până ce ajungeau la locul lor de pășune; iar păstorii lui Lot rătăceau și mergeau și pășteau în câmpurile canaaniților și ale periziților, care încă locuiau în țară."},{"v":8,"t":"Și a zis Avram către Lot: „Să nu fie, te rog, ceartă între mine și tine și între păstorii mei și păstorii tăi, căci suntem oameni frați."},{"v":9,"t":"Oare nu este toată țara înaintea ta? Desparte-te, te rog, de mine: dacă tu mergi la miazănoapte, eu la miazăzi; dacă tu la miazăzi, eu la miazănoapte.”"},{"v":10,"t":"Și Lot și-a ridicat ochii spre desfrâu și a văzut toată câmpia Iordanului, că toată era loc udat — înainte ca Domnul să nimicească în mânia Lui Sodoma și Gomora, țara aceea era lăudată pentru pomii ei, ca grădina Domnului, și pentru roadele ei, ca țara Egiptului („Mițrayim”) — până la Țoar.","notes":["„spre desfrâu” (le-zenu): Targumul adaugă motivul alegerii lui Lot. Rosen: „precum grădina Domnului, precum țara Egiptului, până la Țoar.”"]},{"v":11,"t":"Și și-a ales Lot toată câmpia Iordanului, și Lot a pornit dinspre răsărit, și s-au despărțit unul de altul."},{"v":12,"t":"Avram a locuit în țara Canaanului, iar Lot a locuit în cetățile câmpiei și și-a întins cortul până la Sodoma."},{"v":13,"t":"Și oamenii Sodomei erau răi cu banii lor unul față de altul și păcătoși cu trupul lor, prin dezgolirea goliciunii și prin vărsare de sânge nevinovat și prin slujire străină, și se răzvrăteau foarte mult împotriva Numelui Domnului."},{"v":14,"t":"Și Domnul i-a zis lui Avram, după ce Lot se despărțise de el: „Ridică-ți, te rog, ochii și privește din locul în care ești, spre miazănoapte și spre miazăzi și spre răsărit și spre apus,"},{"v":15,"t":"căci toată țara pe care o vezi ți-o voi da ție și fiilor tăi pe veci."},{"v":16,"t":"Și îi voi face pe fiii tăi mulți ca țărâna pământului: așa cum este cu putință ca un om să numere țărâna pământului, tot așa vor putea fi numărați și fiii tăi."},{"v":17,"t":"Ridică-te, umblă prin țară și ia-o în stăpânire, în lungul și în latul ei, căci ție ți-o voi da.”"},{"v":18,"t":"Și Avram și-a întins cortul, tayyirin imur (după altă versiune: mișkoni le-tiri ve-imri), și a venit și s-a așezat în Ḥezu Mamre, care este în Hebron, și a construit acolo un altar înaintea Domnului.","notes":["Începutul versetului este nesigur în ediția sursă; cuvintele de după „cortul” și varianta din paranteză (care este în sursă) sunt transcrise, pentru că sensul lor nu se poate stabili sigur. „Ḥezu Mamre” transcris; Rosen: „în câmpiile lui Mamre”."]}]},{"num":14,"title":"Capitolul 14","verses":[{"v":1,"t":"Și a fost în zilele lui Amrafel — acesta este Nimrod, care a poruncit să-l arunce pe Avram în foc —, el era regele Pontului; ale lui Arioh, care era înalt între uriași, regele Telasarului; ale lui Chedorlaomer, care era ca un mănunchi legat ce se rostogolește printre snopi, regele Elamului; și ale lui Tidal, înșelător ca vulpea, regele popoarelor care îl ascultau.","notes":["Targumul explică numele regilor prin jocuri de cuvinte: Arioh – arikh („înalt”), Chedorlaomer – ʿomrin („snopi”; sensul exact al imaginii este nesigur), Tidal – taʿla („vulpe”). Rosen: „Amrafel regele Șinearului… Arioh, regele Elasarului… Tidal, regele Goimului”."]},{"v":2,"t":"Ei au făcut război cu Bera, ale cărui fapte erau în rău, regele Sodomei, și cu Birșa, ale cărui fapte erau în nelegiuire, regele Gomorei, cu Șineab, care își ura chiar și tatăl, regele Adma, și cu Șemeber, care își strica mădularele spre desfrâu, regele Țeboimului, și cu regele cetății ai cărei locuitori au fost înghițiți, aceasta este Țoar.","notes":["Și aici numele regilor sunt explicate prin jocuri de cuvinte: Bera – be-raʿ („în rău”), Birșa – be-reșaʿ („în nelegiuire”), Șineab – sone av („urăște pe tatăl”), Șemeber – „strică mădularele (evarim)”; Bela – „înghițit” (balaʿ)."]},{"v":3,"t":"Toți aceștia s-au unit în câmpia livezilor; acesta este locul care revarsă șuvoaie de ape și le aruncă în Marea Sărată.","notes":["Rosen: „la valea Sidim, adică la Marea Sărată.” „șuvoaie de ape” (pirqṭonin): sensul cuvântului este nesigur."]},{"v":4,"t":"Doisprezece ani l-au slujit pe Chedorlaomer, iar în al treisprezecelea an s-au răzvrătit."},{"v":5,"t":"Și în al paisprezecelea an a venit Chedorlaomer și regii care erau cu el și i-au lovit pe uriașii din Așterot-Karnaim și pe cei puternici din Hamta și pe cei înfricoșători din Șave-Chiriataim,","notes":["Rosen: „pe refaimiți la Așterot-Karnaim, pe zuziți în Ham, pe emimi la Șave-Chiriataim”; Targumul traduce numele popoarelor după sens (uriași, puternici, înfricoșători)."]},{"v":6,"t":"și pe horiți, care erau în munții înalți ai Gavlei, până la câmpia Paran, care este lângă marginea pustiului.","notes":["Gavla: numele aramaic al ținutului Seir."]},{"v":7,"t":"Și s-au întors și au venit la locul unde avea să fie despărțită judecata lui Moise profetul, la izvorul apelor certei, aceasta este Reqam; și au lovit toate câmpurile amalekiților și de asemenea pe amoritul care locuia în Ein-Ghedi.","notes":["Rosen: „la Ein-Mișpat, adică la Cades… în Hațațon-Tamar.” Targumul leagă Ein-Mișpat („izvorul judecății”) de apele Meriba (Numeri 20:13) și identifică Cades cu Reqam și Hațațon-Tamar cu Ein-Ghedi (2 Cronici 20:2)."]},{"v":8,"t":"Și a ieșit regele Sodomei și regele Gomorei și regele Adma și regele Țeboimului și regele cetății ai cărei locuitori au fost înghițiți, aceasta este Țoar, și s-au rânduit împotriva lor în linii de luptă în câmpia livezilor,"},{"v":9,"t":"împotriva lui Chedorlaomer, regele Elamului, și a lui Tidal, regele popoarelor care îl ascultau, și a lui Amrafel, regele Pontului, și a lui Arioh, regele Telasarului: patru regi s-au rânduit la luptă împotriva a cinci."},{"v":10,"t":"Iar câmpia livezilor era numai gropi pline de smoală; și au fugit regele Sodomei și al Gomorei și au căzut acolo, iar cei care au rămas au fugit la munte."},{"v":11,"t":"Și au luat toată averea Sodomei și a Gomorei și toată hrana lor și au plecat."},{"v":12,"t":"Și l-au luat prizonier pe Lot și averea lui, fiul fratelui lui Avram, și au plecat; iar el locuia în Sodoma."},{"v":13,"t":"Și a venit Og, care scăpase dintre uriașii care muriseră în potop: călărise pe corabie și era un acoperiș deasupra capului lui, și se hrănea din hrana lui Noe; și nu prin meritul lui a scăpat, ci ca să vadă locuitorii lumii puterea Domnului și să spună: „Oare nu uriașii care au fost odinioară s-au răzvrătit împotriva Stăpânului lumii, și El i-a nimicit de pe pământ?” Și când au făcut război regii aceștia, Og era cu ei; și a zis în inima lui: „Mă voi duce și-i voi spune lui Avram despre Lot, care a fost luat prizonier, și el va veni să-l scape din mâna regilor și va fi dat în mâinile lor.” Și a venit la intrarea zilei de Pesah și l-a găsit făcând turte azime; atunci i-a dat de veste lui Avram evreul. Iar el locuia în Ḥezu Mamre, amoritul, fratele lui Eșcol și fratele lui Aner, iar ei erau aliații lui Avram.","notes":["Rosen: „Fugarul a venit și i-a dat de veste lui Avram evreul”; Targumul îl identifică pe fugar cu Og, regele Basanului (Deuteronomul 3:11)."]},{"v":14,"t":"Și când a auzit Avram că fratele lui fusese luat prizonier, i-a înarmat pe tinerii pe care îi deprinsese la război, dintre cei crescuți în casa lui; dar ei n-au vrut să meargă cu el, și a ales dintre ei pe Eliezer, fiul lui Nimrod, care era în vitejie cât toți cei trei sute optsprezece; și a urmărit până la Dan.","notes":["Rosen: „și-a înarmat discipolii născuți în casa sa, cei trei sute optsprezece”. Valoarea numerică a numelui Eliezer este 318 (Nedarim 32a)."]},{"v":15,"t":"Și noaptea s-a împărțit pentru ei pe drum: o jumătate a luptat cu regii, iar cealaltă jumătate a fost păstrată ca să-i lovească pe întâii născuți în Egipt („Mițrayim”); și s-a ridicat el și slujitorii lui și i-a lovit și i-a urmărit pe cei care rămăseseră dintre ei, până ce și-a amintit de păcatul ce avea să fie în Dan, care este la miazănoapte de Damasc.","notes":["„cealaltă jumătate a fost păstrată…”: noaptea din Exodul 12:29. Rosen: „până la Hoba, care este la miazănoapte de Damasc”; Targumul citește Hoba ca ḥova („păcat”), adică idolul din Dan (Judecătorii 18; 1 Împărați 12:29)."]},{"v":16,"t":"Și a adus înapoi toată averea, și de asemenea pe Lot, fratele lui, și averea lui a adus-o înapoi, și de asemenea pe femei și pe popor."},{"v":17,"t":"Și a ieșit regele Sodomei în întâmpinarea lui, după ce s-a întors de la lovirea lui Chedorlaomer și a regilor care erau cu el, la câmpia Mafna, aceasta este Beit Risa a regelui.","notes":["Rosen: „în valea Șave, care este valea regelui.” Beit Risa: probabil „locul de întreceri” (hipodromul) al regelui; transcris."]},{"v":18,"t":"Și regele drept — acesta este Sem, fiul lui Noe —, regele Ierusalimului, a ieșit în întâmpinarea lui Avram și i-a scos pâine și vin; în vremea aceea el slujea înaintea Dumnezeului Preaînalt.","notes":["Rosen: „Melhisedec, regele Salemului… el fiind preot al Dumnezeului Preaînalt.” Targumul traduce Melhisedec („regele dreptății”), îl identifică cu Sem și Salem cu Ierusalimul."]},{"v":19,"t":"Și l-a binecuvântat și a zis: „Binecuvântat este Avram de la Domnul, Dumnezeul Preaînalt, care, pentru cei drepți, a dobândit cerurile și pământul."},{"v":20,"t":"Și binecuvântat este Dumnezeul Preaînalt, care i-a făcut pe dușmanii tăi ca un scut care primește lovitura.” Și i-a dat una din zece din tot ce adusese înapoi.","notes":["Rosen: „care i-a predat pe dușmanii tăi în mâna ta”; Targumul leagă cuvântul miggen de magen („scut”)."]},{"v":21,"t":"Și a zis regele Sodomei către Avram: „Dă-mi sufletele oamenilor din poporul meu pe care le-ai adus înapoi, iar averea ia-o pentru tine.”"},{"v":22,"t":"Și a zis Avram către regele Sodomei: „Mi-am ridicat mâna în jurământ înaintea Domnului, Dumnezeul Preaînalt, care, pentru cei drepți, a dobândit prin puterea Lui cerurile și pământul,"},{"v":23,"t":"că de la un fir și până la cureaua sandalei nu voi lua nimic din tot ce este al tău, ca să nu te lauzi zicând: «Eu l-am îmbogățit pe Avram din ce este al meu»."},{"v":24,"t":"Nu am niciun drept asupra a nimic din țară; în afară de mine, numai ce au mâncat tinerii și partea oamenilor care au mers cu mine, Aner, Eșcol și Mamre: și ei își vor lua partea lor.”","notes":["Rosen: „Departe de mine!” Construcția din sursă este greoaie („în toată țara, în afară de mine”); redată literal."]}]},{"num":15,"title":"Capitolul 15","verses":[{"v":1,"t":"După aceste lucruri, după ce s-au adunat regii și au căzut înaintea lui Avram, și el a ucis patru regi și a adus înapoi nouă oștiri, Avram s-a gândit în inima lui și a zis: „Vai mie acum! Poate că am primit răsplata poruncilor mele în lumea aceasta și nu am parte în lumea care vine. Sau poate vor merge frații și rudele celor uciși și se vor uni în legiuni și vor veni asupra mea. Sau poate că în vremea aceea s-a aflat la mine răsplata unor merite mici, și au căzut înaintea mea, iar a doua oară nu se va afla la mine răsplată, și se va pângări prin mine Numele Cerului.” Și atunci a fost cuvântul Domnului cu Avram într-o viziune, spunând: „Nu te teme! Chiar dacă vitejii lor se unesc în legiuni și vin asupra ta, Cuvântul Meu îți va fi pavăză; și chiar dacă ei cad înaintea ta în lumea aceasta, răsplata faptelor tale bune este păstrată și pregătită înaintea Mea pentru lumea care vine, foarte mare.”","notes":["Rosen: „După aceste lucruri, a fost cuvântul Domnului către Avram într-o viziune, spunând: «Nu te teme, Avram! Eu sunt pavăză pentru tine; răsplata ta este foarte mare.»” „nouă oștiri”: sursa are „nouă” (tișaʿ); redat după sursă."]},{"v":2,"t":"Și a zis Avram: „Doamne Dumnezeule, multe binecuvântări mi-ai dat și multe sunt înaintea Ta ca să-mi dai; dar ce folos am eu, când plec din lume fără fii, iar Eliezer, fiul administratorului casei mele, prin mâna căruia mi s-au făcut minuni în Damasc, nădăjduiește să mă moștenească?”","notes":["Rosen: „intendentul casei mele este Eliezer din Damasc”."]},{"v":3,"t":"Și a zis Avram: „Iată, mie nu mi-ai dat fiu, și iată, fiul administratorului casei mele mă va moșteni.”"},{"v":4,"t":"Și iată, cuvântul de la Domnul a fost către el, spunând: „Nu acesta te va moșteni, ci fiul pe care îl vei naște, acela te va moșteni.”"},{"v":5,"t":"Și l-a scos afară și a zis: „Privește, te rog, la ceruri și numără stelele, dacă le poți număra.” Și i-a zis: „Așa vor fi fiii tăi.”"},{"v":6,"t":"Și a avut credință în Cuvântul Domnului, și El i-a socotit-o ca merit, pentru că nu a vorbit împotriva Lui cu vorbe."},{"v":7,"t":"Și i-a zis: „Eu sunt Domnul, care te-am scos din cuptorul de foc al caldeenilor, ca să-ți dau țara aceasta s-o moștenești.”"},{"v":8,"t":"Și a zis: „Doamne Dumnezeule, prin ce voi ști că o voi moșteni?”"},{"v":9,"t":"Și i-a zis: „Ia pentru Mine jertfe și adu înaintea Mea o vițea de trei ani și un berbec de trei ani și o capră de trei ani și o turturea și un pui de porumbel.”","notes":["Rosen: „Ia pentru Mine trei vițele, trei iezi, trei berbeci, o turturea și un porumbel tânăr.” Targumul înțelege meșulleșet ca „de trei ani”."]},{"v":10,"t":"Și a adus înaintea Lui toate acestea și le-a despicat la mijloc și a așezat fiecare bucată în fața celeilalte; dar pasărea n-a despicat-o."},{"v":11,"t":"Și au coborât popoare închinătoare la idoli, care sunt asemănate cu pasărea necurată, ca să prade averile lui Israel; și meritul lui Avram îi ocrotea.","notes":["Rosen: „Păsările de pradă au coborât asupra stârvurilor și Avram le-a gonit.” „închinătoare la idoli”: în sursă prescurtarea ʿ\"A (ʿovdei elilim)."]},{"v":12,"t":"Și soarele era aproape să apună, și un somn adânc a căzut peste Avram; și iată, patru împărății stăteau gata să-i subjuge pe fiii lui: „groaza”, aceasta este Babilonul; „întunericul”, aceasta este Media; „mare”, aceasta este Grecia; „cade”, aceasta este Persia, care va cădea și nu va avea cine s-o ridice; și de acolo va urca poporul casei lui Israel.","notes":["Targumul citește cele patru cuvinte din versetul ebraic („groază, întuneric, mare, cade asupra lui”) ca pe cele patru împărății care aveau să-l subjuge pe Israel."]},{"v":13,"t":"Și i-a zis lui Avram: „Să știi negreșit că fiii tăi vor fi străini într-o țară care nu este a lor, pentru că nu ai crezut, și îi vor subjuga și îi vor asupri patru sute de ani."},{"v":14,"t":"Și de asemenea poporul căruia îi vor sluji îl voi judeca Eu, cu două sute cincizeci de lovituri, și după aceea vor ieși la libertate cu averi multe.","notes":["„cu două sute cincizeci de lovituri”: plăgile din Egipt (vezi Hagada de Pesah, după Rabbi Akiva)."]},{"v":15,"t":"Iar tu te vei aduna la părinții tăi în pace, sufletul tău se va odihni, și vei fi îngropat la o bătrânețe bună."},{"v":16,"t":"Și generația a patra a fiilor tăi se va întoarce aici ca s-o moștenească, căci nu s-a împlinit păcatul amoriților (până) acum.”","notes":["„(până)”: paranteza este în ediția sursă."]},{"v":17,"t":"Și soarele apusese și era întuneric beznă; și iată, Avram a văzut Gheena ridicând fum și cărbuni de foc și aprinzând scântei de foc, ca să-i judece în ea pe cei nelegiuiți; și iată, a trecut printre bucățile acestea.","notes":["Rosen: „un furnal fumegând și o văpaie de foc au trecut printre acele bucăți”; Targumul vede în furnal Gheena."]},{"v":18,"t":"În ziua aceea a încheiat Domnul cu Avram un legământ, să nu-i judece în ea pe fiii lui și să-i răscumpere de sub împărății, spunând: „Fiilor tăi le voi da țara aceasta, de la Nilul Egiptului („Mițrayim”) până la râul cel mare, râul Eufrat:"},{"v":19,"t":"pe șalmaiți și pe chenizit și pe cadmonit,","notes":["Rosen: „pe chenit”; Targumul are șalmaʾei (ca la Onkelos)."]},{"v":20,"t":"și pe hitiți și pe periziți și pe uriași,","notes":["Rosen: „pe refaimiți”; Targumul are gubraʾei („uriașii, cei puternici”), ca la 14:5."]},{"v":21,"t":"și pe amoriți și pe canaaniți și pe ghirgașiți și pe iebusiți.”"}]},{"num":16,"title":"Capitolul 16","verses":[{"v":1,"t":"Și Sarai, soția lui Avram, nu-i născuse copii; și avea o roabă egipteancă, al cărei nume era Agar, fiica lui Faraon, pe care el i-o dăduse ca roabă atunci când a luat-o, când a fost lovit prin Cuvântul de la Domnul.","notes":["„când a fost lovit”: vezi 12:17."]},{"v":2,"t":"Și a zis Sarai către Avram: „Iată acum, Domnul m-a oprit de la a naște; intră la roaba mea, și o voi elibera; poate voi fi zidită prin ea.” Și Avram a ascultat de vorba Sarei."},{"v":3,"t":"Și Sarai, soția lui Avram, a luat-o pe Agar egipteanca, roaba ei, după zece ani de când locuia Avram în țara Canaanului, și a eliberat-o și a dat-o lui Avram, bărbatul ei, să-i fie soție."},{"v":4,"t":"Și a intrat la Agar, și ea a rămas însărcinată; și când a văzut că a rămas însărcinată, a disprețuit cinstea stăpânei ei în ochii ei."},{"v":5,"t":"Și a zis Sarai către Avram: „Toată nedreptatea mea este de la tine; căci eram încrezătoare că îmi vei face dreptate, pentru că eu am lăsat țara și casa tatălui meu și am urcat cu tine într-o țară străină. Și acum, pentru că nu nășteam, mi-am eliberat roaba și am dat-o să se culce în brațele tale, și a văzut că a rămas însărcinată și a fost disprețuită cinstea mea înaintea ei. Și acum să se descopere înaintea Domnului nedreptatea mea, și să-Și întindă pacea între mine și tine, și să se umple pământul de noi, și să nu avem nevoie de fiii Agarei, fiica lui Faraon, fiul lui Nimrod, care te-a aruncat în cuptorul de foc.”","notes":["„fiica lui Faraon, fiul lui Nimrod”: așa în sursă."]},{"v":6,"t":"Și a zis Avram către Sarai: „Iată, roaba ta este în puterea ta; fă-i ce este bine în ochii tăi.” Și Sarai a asuprit-o, și ea a fugit dinaintea ei."},{"v":7,"t":"Și a găsit-o îngerul Domnului la izvorul de apă din pustiu, la izvorul de pe drumul către Hagra.","notes":["Rosen: „pe drumul către Șur”; Targumul are Hagra (ca Onkelos)."]},{"v":8,"t":"Și a zis: „Agar, roaba Sarei, de unde vii și încotro te duci?” Și ea a zis: „Fug dinaintea Sarei, stăpâna mea.”"},{"v":9,"t":"Și i-a zis îngerul Domnului: „Întoarce-te la stăpâna ta și supune-te sub mâinile ei.”"},{"v":10,"t":"Și i-a zis îngerul Domnului: „Voi înmulți foarte mult pe fiii tăi, și nu vor putea fi numărați de mulțime.”"},{"v":11,"t":"Și i-a zis îngerul Domnului: „Iată, ești însărcinată și vei naște un fiu și îi vei pune numele Ismael, căci s-a descoperit înaintea Domnului suferința ta."},{"v":12,"t":"Și el va fi asemenea unui măgar sălbatic între oameni: mâinile lui se vor răzbuna pe dușmanii lui, și mâinile dușmanilor lui se vor întinde să-i facă rău; și în fața tuturor fraților lui se va amesteca și va locui.”","notes":["Rosen: „mâna lui împotriva tuturor și mâna tuturor împotriva lui; și asupra tuturor fraților lui va sălășlui.”"]},{"v":13,"t":"Și ea a mulțumit înaintea Domnului, al cărui Cuvânt îi vorbise, și așa a zis: „Tu ești Cel Viu și Veșnic, care vede și nu este văzut”, căci a zis: „Iată, cu adevărat aici s-a descoperit slava Șechinei Domnului, după vedenie.”","notes":["Rosen: „Agar a pus numele Domnului care îi vorbise Ata-El-Roi, căci a spus: «Am văzut și aici, după ce m-a văzut?»”"]},{"v":14,"t":"De aceea a numit fântâna: „Fântâna în care S-a descoperit Cel Viu și Veșnic”; și iată, ea este așezată între Reqam și Ḥaluṣa.","notes":["Rosen: „De aceea, fântâna s-a numit Beer-Lahai-Roi – iată, ea este între Cades și Bered.” Targumul traduce numele fântânii și identifică Cades cu Reqam și Bered cu Ḥaluṣa."]},{"v":15,"t":"Și Agar i-a născut lui Avram un fiu, și Avram i-a pus fiului său, pe care i l-a născut Agar, numele Ismael."},{"v":16,"t":"Și Avram avea optzeci și șase de ani când i l-a născut Agar pe Ismael lui Avram."}]},{"num":17,"title":"Capitolul 17","verses":[{"v":1,"t":"Și Avram avea nouăzeci și nouă de ani, și S-a arătat Domnul lui Avram și i-a zis: „Eu sunt Dumnezeul Atotputernic; slujește înaintea Mea și fii desăvârșit în trupul tău.","notes":["Rosen: „mergi înaintea Mea și fii integru!”"]},{"v":2,"t":"Și voi pune legământul Meu între Cuvântul Meu și tine și te voi înmulți foarte, foarte mult.”"},{"v":3,"t":"Și pentru că Avram nu era circumcis, nu putea să stea în picioare, și a căzut cu fața la pământ; și Domnul a vorbit cu el, spunând:"},{"v":4,"t":"„Eu, iată, am încheiat legământul Meu cu tine, și vei fi tatăl multor popoare."},{"v":5,"t":"Și numele tău nu se va mai chema Avram, ci numele tău va fi Avraam, căci te-am rânduit tatăl unei mulțimi de popoare.","notes":["Rosen: „căci ți-am dat să fii tatăl multor neamuri.”"]},{"v":6,"t":"Și te voi face foarte, foarte roditor și te voi face adunări, și regi care stăpânesc peste popoare vor ieși din tine."},{"v":7,"t":"Și voi statornici legământul Meu între Cuvântul Meu și tine și fiii tăi după tine, în generațiile lor, ca legământ veșnic, ca să-ți fiu Dumnezeu ție și fiilor tăi după tine."},{"v":8,"t":"Și îți voi da ție și fiilor tăi după tine țara în care locuiești ca străin, toată țara Canaanului, ca moștenire veșnică, și le voi fi Dumnezeu.”"},{"v":9,"t":"Și a zis Domnul către Avraam: „Iar tu să păzești legământul Meu, tu și fiii tăi după tine, în generațiile lor."},{"v":10,"t":"Acesta este legământul Meu pe care să-l păziți, între Cuvântul Meu și voi și fiii tăi după tine: să fie circumcis la voi orice bărbat, dacă nu are tată care să-l circumcidă."},{"v":11,"t":"Și să tăiați carnea prepuțului vostru, și va fi semn de legământ între Cuvântul Meu și voi."},{"v":12,"t":"Și la vârsta de opt zile să fie circumcis la voi orice băiat, în generațiile voastre, cei născuți în casele voastre și cei cumpărați cu argintul vostru dintre toți fiii popoarelor, care nu sunt din fiii tăi."},{"v":13,"t":"Cel care circumcide să circumcidă pe cei născuți în casele voastre și pe cei cumpărați cu argintul vostru, și legământul Meu va fi în carnea voastră ca legământ veșnic."},{"v":14,"t":"Iar bărbatul necircumcis, care nu-și va tăia carnea prepuțului — și dacă nu are cine să-l circumcidă —, omul acela va fi nimicit din poporul său: legământul Meu l-a schimbat.”","notes":["Rosen: „a nesocotit legământul Meu”; Targumul are „legământul Meu l-a schimbat”."]},{"v":15,"t":"Și a zis Domnul către Avraam: „Pe Sarai, soția ta, să nu-i mai spui pe nume Sarai, căci Sara este numele ei."},{"v":16,"t":"Și o voi binecuvânta în trupul ei, și de asemenea îți voi da din ea un fiu; și o voi binecuvânta prin el, și ea va deveni adunări, și regi care stăpânesc peste popoare vor fi din ea.”"},{"v":17,"t":"Și Avraam a căzut cu fața la pământ și s-a mirat și a zis în inima lui: „Oare unui om de o sută de ani i se va naște un copil? Și Sara, oare la nouăzeci de ani va naște?”"},{"v":18,"t":"Și a zis Avraam înaintea Domnului: „O, de ar trăi Ismael și de ar sluji înaintea Ta!”"},{"v":19,"t":"Și a zis Domnul: „Cu adevărat, Sara, soția ta, îți va naște un fiu, și îi vei pune numele Isaac; și voi statornici legământul Meu cu el ca legământ veșnic pentru fiii lui după el."},{"v":20,"t":"Iar pentru Ismael ți-am primit rugăciunea: iată, l-am binecuvântat și îl voi face roditor și îl voi înmulți foarte, foarte mult; doisprezece căpetenii va naște, și îl voi face un popor mare."},{"v":21,"t":"Dar legământul Meu îl voi statornici cu Isaac, pe care ți-l va naște Sara la vremea aceasta, în anul celălalt.”"},{"v":22,"t":"Și a încetat să vorbească cu el, și slava Domnului S-a înălțat de la Avraam."},{"v":23,"t":"Și Avraam l-a luat pe Ismael, fiul său, și pe toți cei născuți în casa lui și pe toți cei cumpărați cu argintul lui, pe orice bărbat dintre oamenii casei lui Avraam, și le-a tăiat carnea prepuțului chiar în ziua aceea, cum îi vorbise Domnul."},{"v":24,"t":"Și Avraam avea nouăzeci și nouă de ani când și-a tăiat carnea prepuțului."},{"v":25,"t":"Și Ismael, fiul său, avea treisprezece ani când și-a tăiat carnea prepuțului."},{"v":26,"t":"Chiar în ziua aceea, în paisprezece ani, au fost circumciși Avraam și Ismael, fiul său.","notes":["„în paisprezece ani”: așa în ediția sursă; sensul nu este clar (poate o greșeală de copist); redat literal."]},{"v":27,"t":"Și toți oamenii casei lui, cei născuți în casă și cei cumpărați cu argint dintre fiii popoarelor, au fost circumciși cu el."}]},{"num":18,"title":"Capitolul 18","verses":[{"v":1,"t":"S-a arătat: și S-a descoperit asupra lui slava Domnului în Ḥezu Mamre; iar el era bolnav de durerea circumciziei și ședea la intrarea cortului, în arșița zilei.","notes":["Ediția sursă începe versetul cu cuvântul ebraic al Torei („S-a arătat”), urmat de traducerea aramaică. Rosen: „în Elonei-Mamre”."]},{"v":2,"t":"Și și-a ridicat ochii și a privit, și iată, trei îngeri în chip de oameni stăteau înaintea lui, care fuseseră trimiși pentru trei lucruri, căci nu se cuvine ca un înger slujitor să fie trimis pentru mai mult de un singur lucru: unul a venit să-l vestească că Sara va naște un fiu, unul a venit să-l scape pe Lot și unul a venit să răstoarne Sodoma și Gomora. Și când i-a văzut, a alergat în întâmpinarea lor de la intrarea cortului și s-a plecat până la pământ."},{"v":3,"t":"Și a zis: „Te rog, cu îndurare dinaintea Ta, Doamne: dacă am găsit acum har înaintea Ta, nu-Ți înălța, te rog, slava Șechinei Tale de la robul Tău, până ce îi voi primi pe acești trecători.”"},{"v":4,"t":"sub pom.","notes":["În ediția sursă versetul are numai cuvintele „sub pom”; restul versetului lipsește; numerotarea urmează sursa."]},{"v":5,"t":"„Și voi lua o bucată de pâine, și întăriți-vă inima și mulțumiți Numelui Cuvântului Domnului, și după aceea veți trece; căci de aceea, la vremea mesei, v-ați nimerit și ați trecut pe la robul vostru, ca să mâncați.” Și au zis: „Bine ai vorbit; fă după cuvântul tău.”"},{"v":6,"t":"Și Avraam s-a grăbit în cort la Sara și a zis: „Grăbește-te: trei sea de făină de grâu aleasă, frământ-o și fă turte.”"},{"v":7,"t":"Și la cireadă a alergat Avraam și a luat un vițel fraged și gras și l-a dat tânărului, și acesta s-a grăbit să-l gătească în mâncăruri."},{"v":8,"t":"Și a luat unt și lapte și vițelul pe care tânărul îl gătise în mâncăruri și le-a pus înaintea lor, după obiceiul oamenilor lumii; iar el slujea înaintea lor, și ei ședeau sub pom, și i se părea că mănâncă."},{"v":9,"t":"Și i-au zis: „Unde este Sara, soția ta?” Și el a zis: „Iată, este în cort.”"},{"v":10,"t":"Și a zis unul dintre ei: „Mă voi întoarce negreșit la tine la anul care vine, și voi veți fi în viață, și iată, Sara, soția ta, va avea un fiu.” Iar Sara asculta la intrarea cortului, și Ismael stătea în spatele lui și asculta ce spunea îngerul."},{"v":11,"t":"Și Avraam și Sara erau bătrâni, înaintați în zile; încetase pentru Sara să mai aibă rânduiala femeilor."},{"v":12,"t":"Și s-a mirat Sara în inima ei, spunând: „După ce am îmbătrânit, voi mai rămâne oare însărcinată? Și stăpânul meu, Avraam, este bătrân!”","notes":["„voi mai rămâne oare însărcinată” (ʿiddu'yin): sensul cuvântului este nesigur; Rosen: „oare voi mai avea pielea netedă?”"]},{"v":13,"t":"Și a zis Domnul către Avraam: „De ce a râs Sara aceasta, spunând: «Oare cu adevărat voi naște, când eu am îmbătrânit?»"},{"v":14,"t":"Oare este cu putință să fie ascuns ceva înaintea Domnului? La vremea sărbătorii Mă voi întoarce, la vremea aceasta, și voi veți fi în viață, iar Sara va avea un fiu.”"},{"v":15,"t":"Și Sara a tăgăduit, spunând: „Nu m-am mirat”, căci se temea. Și a zis îngerul: „Nu vă temeți, căci cu adevărat ai râs.”"},{"v":16,"t":"Și s-au ridicat de acolo îngerii care erau asemenea unor oameni: cel care o vestise pe Sara s-a înălțat la cerurile de sus, iar doi dintre ei au privit spre fața Sodomei; și Avraam mergea cu ei ca să-i însoțească."},{"v":17,"t":"Și Domnul a zis prin Cuvântul Său: „Nu se cuvine să ascund de Avraam ce voi face, și este drept să nu facem nimic până nu-l vom înștiința."},{"v":18,"t":"Iar Avraam va fi un popor mare și puternic, și se vor binecuvânta pentru el, prin meritul lui, toate popoarele pământului."},{"v":19,"t":"Căci este descoperită înaintea Mea evlavia lui, pentru că le va porunci fiilor lui și oamenilor casei lui după el, și vor păzi căile care sunt drepte înaintea Domnului, făcând dreptate și judecată, ca să aducă Domnul asupra lui Avraam ceea ce a vorbit despre el.”"},{"v":20,"t":"Și a zis Domnul către îngerii slujitori: „Strigătul Sodomei și al Gomorei, pentru că îi asupresc pe săraci și au hotărât ca oricine dă pâine săracului să fie ars în foc, este mare, și păcatul lor este foarte greu."},{"v":21,"t":"Mă voi descoperi acum și voi vedea: dacă au făcut după strigătul fetei Peliṭit, care a ajuns înaintea Mea, sunt vinovați de nimicire; iar dacă fac pocăință, oare nu sunt ei nevinovați înaintea Mea, ca și cum n-aș fi știut, și nu Mă voi răzbuna.”","notes":["Peliṭit: după tradiția agadică, o fată din Sodoma (fiica lui Lot) arsă pentru că dăduse pâine unui sărac (Sanhedrin 109b; Pirkei de-Rabbi Eliezer 25). Rosen: „dacă au făcut ca strigătul care a ajuns la Mine – distrugere! Iar dacă nu, voi ști.”"]},{"v":22,"t":"Și s-au întors de acolo îngerii care erau asemenea unor oameni și s-au dus la Sodoma; iar Avraam încă cerea îndurare pentru Lot și slujea în rugăciune înaintea Domnului."},{"v":23,"t":"Și s-a rugat Avraam și a zis: „Oare mânia Ta îl va nimici pe cel drept împreună cu cel nelegiuit?"},{"v":24,"t":"Poate sunt cincizeci de drepți în cetate, care să se roage înaintea Ta, câte zece pentru fiecare cetate, corespunzător celor cinci cetăți, Sodoma, Gomora, Adma, Țeboim și Țoar; oare mânia Ta va nimici și nu va ierta locul pentru meritele celor cincizeci de drepți care sunt în el?"},{"v":25,"t":"Departe de Tine să faci un astfel de lucru, să-l ucizi pe cel drept împreună cu cel nelegiuit, și să fie cel drept ca cel nelegiuit; departe de Tine! Oare este cu putință ca Cel care judecă tot pământul să nu facă judecată?”"},{"v":26,"t":"Și a zis Domnul: „Dacă voi găsi în Sodoma cincizeci de drepți în cetate, care să se roage înaintea Mea, voi ierta tot ținutul pentru ei.”"},{"v":27,"t":"Și Avraam a răspuns și a zis: „Te rog, cu îndurare: iată, am început să vorbesc înaintea Domnului, iar eu sunt asemenea țărânei și cenușii."},{"v":28,"t":"Poate le vor lipsi celor cincizeci de drepți cinci; oare vei nimici, pentru cei cinci care lipsesc, pentru Țoar, toată cetatea?” Și a zis: „Nu voi nimici, dacă voi găsi acolo patruzeci și cinci.”"},{"v":29,"t":"Și a mai continuat să vorbească înaintea Lui și a zis: „Poate se vor găsi acolo patruzeci, câte zece pentru fiecare cetate, pentru patru cetăți; iar Țoar, ale cărei păcate sunt ușoare, iart-o pentru îndurarea Ta.” Și a zis: „Nu voi face nimicire, pentru meritul celor patruzeci.”"},{"v":30,"t":"Și a zis: „Să nu se aprindă, te rog, mânia Stăpânului tuturor lumilor, Domnul, și voi vorbi: poate se vor găsi acolo treizeci care să se roage, câte zece pentru fiecare cetate, pentru trei cetăți; iar Țeboim și Țoar iartă-le pentru îndurarea Ta.” Și a zis: „Nu voi face nimicire, dacă voi găsi acolo treizeci.”"},{"v":31,"t":"Și a zis: „Te rog, cu îndurare: iată, am început să vorbesc înaintea Stăpânului tuturor lumilor, Domnul: poate se vor găsi douăzeci care să se roage, câte zece pentru două cetăți, iar pe celelalte trei iartă-le pentru îndurarea Ta.” Și a zis: „Nu voi nimici, pentru meritele celor douăzeci.”"},{"v":32,"t":"Și a zis: „Te rog, cu îndurare dinaintea Ta, să nu se aprindă, te rog, mânia Stăpânului tuturor lumilor, Domnul, și voi vorbi numai de data aceasta: poate se vor găsi acolo zece, și vom fi eu și ei și vom cere îndurare pentru tot ținutul, și îi vei ierta.” Și a zis: „Nu voi nimici, pentru meritele celor zece.”"},{"v":33,"t":"Și slava Domnului S-a înălțat, când a încetat să vorbească cu Avraam, iar Avraam s-a întors la locul lui."}]},{"num":19,"title":"Capitolul 19","verses":[{"v":1,"t":"Și cei doi îngeri au venit la Sodoma seara, iar Lot ședea la poarta Sodomei; și Lot a văzut și s-a ridicat în întâmpinarea lor de la intrarea cortului și s-a plecat cu fața la pământ."},{"v":2,"t":"Și a zis: „Vă rog acum, domnii mei, abateți-vă acum de aici și intrați în casa robului vostru și înnoptați și spălați-vă picioarele, și vă veți scula devreme și veți merge pe drumul vostru.” Și au zis: „Nu, ci vom înnopta în piață.”","notes":["„spălați-vă” (șezugu): Targumul are verbul „a clăti, a spăla”."]},{"v":3,"t":"Și a stăruit foarte mult pe lângă ei, și s-au abătut la el și au intrat în casa lui; și le-a făcut un ospăț și le-a copt azime, și i se părea că mănâncă."},{"v":4,"t":"Înainte să se culce, oamenii nelegiuiți din cetate, oamenii Sodomei, au înconjurat casa, de la tânăr până la bătrân, tot poporul, până la unul."},{"v":5,"t":"Și l-au chemat pe Lot și i-au zis: „Unde sunt oamenii care au intrat la tine în noaptea aceasta? Scoate-i la noi, ca să ne culcăm cu ei.”"},{"v":6,"t":"Și Lot a ieșit la ei la intrare și a închis ușa după el."},{"v":7,"t":"Și a zis: „Vă rog, frații mei, nu faceți rău."},{"v":8,"t":"Iată, am două fiice care nu s-au culcat cu bărbat; le voi scoate acum la voi, și faceți-le ce este bine înaintea voastră; numai acestor oameni să nu le faceți nimic rău, căci de aceea au intrat să înnopteze la umbra acoperișului meu.”"},{"v":9,"t":"Și au zis: „Dă-te mai încolo!” Și au zis: „Oare nu a venit acesta singur să locuiască ca străin printre noi, și iată, s-a făcut judecător și ne judecă pe toți? Și acum îți vom face mai mult rău decât lor.” Și au năvălit foarte tare asupra omului, asupra lui Lot, și s-au apropiat să spargă ușa."},{"v":10,"t":"Și oamenii și-au întins mâinile și l-au adus pe Lot la ei în casă, iar ușa au închis-o."},{"v":11,"t":"Iar pe oamenii care erau la intrarea casei i-au lovit cu orbire, de la tânăr până la bătrân, și s-au trudit să găsească intrarea."},{"v":12,"t":"Și au zis oamenii către Lot: „Mai ai pe cineva în cetate, o rudă sau un frate aici? Pe ginerii tăi, pe fiii tăi, pe fiicele tale scoate-i din locul acesta."},{"v":13,"t":"Căci noi nimicim locul acesta, pentru că strigătul lor a crescut înaintea Domnului, și Domnul ne-a trimis să-l nimicim.”"},{"v":14,"t":"Și Lot a ieșit și a vorbit cu ginerii lui, care luaseră pe fiicele lui, și a zis: „Sculați-vă, ieșiți din locul acesta, căci Domnul nimicește cetatea”; dar cuvântul a fost ca o glumă, ca un om care glumește, în ochii ginerilor lui."},{"v":15,"t":"Și când zorii erau gata să se ridice, îngerii l-au zorit pe Lot, spunând: „Ridică-te, ia-ți soția și pe cele două fiice ale tale care se găsesc la tine, ca să nu fii nimicit în păcatele locuitorilor cetății.”"},{"v":16,"t":"Și el zăbovea; și oamenii l-au apucat de mână, pe el, pe soția lui și pe cele două fiice ale lui, pentru că îndurarea de la Domnul era asupra lui, și l-au scos și l-au așezat în afara cetății."},{"v":17,"t":"Și a fost, când i-au scos afară, unul dintre ei s-a întors la Sodoma ca s-o nimicească, iar unul a rămas cu Lot și i-a zis: „Cruță-ți viața! Nu privi înapoia ta și nu te opri în toată câmpia; scapă la munte, ca să nu fii nimicit.”"},{"v":18,"t":"Și a zis Lot către el: „Te rog, așteaptă-mă puțin, până vom cere îndurare dinaintea Domnului."},{"v":19,"t":"Iată, robul tău a găsit acum îndurare înaintea ta, și ai mărit bunătatea pe care ai făcut-o cu mine, ca să-mi păstrezi viața; dar eu nu pot scăpa la munte, ca nu cumva să mă ajungă nenorocirea și să mor."},{"v":20,"t":"Iată acum, te rog, cetatea aceasta: așezarea ei este aproape și se poate fugi acolo, și ea este mică, iar păcatele ei sunt ușoare; să scap acolo — oare nu este mică? — și să-mi rămână viața.”"},{"v":21,"t":"Și i-a zis: „Iată, ți-am primit rugămintea și în lucrul acesta, ca să nu răstorn cetatea despre care ai vorbit, ca să scapi în ea."},{"v":22,"t":"Grăbește-te, scapă acolo, căci nu pot face nimic până nu vei intra acolo.” De aceea a numit numele cetății Țoar."},{"v":23,"t":"Soarele a trecut marea și a ieșit pe pământ la sfârșitul a trei ore, iar Lot a intrat în Țoar.","notes":["Rosen: „Soarele răsărea asupra pământului și Lot a ajuns în Țoar.” Începutul versetului din sursă („soarele a trecut marea”) este redat literal."]},{"v":24,"t":"Și Cuvântul Domnului a coborât ploi de bunăvoință asupra Sodomei și asupra Gomorei, ca să facă pocăință, dar ei n-au făcut, căci au zis: „Nu sunt descoperite înaintea Domnului faptele rele.” Iată, atunci au coborât asupra lor pucioasă și foc dinaintea Cuvântului Domnului, din ceruri.","notes":["Rosen: „Și Domnul a făcut să plouă asupra Sodomei și asupra Gomorei pucioasă și foc de la Domnul, din ceruri.”"]},{"v":25,"t":"Și a răsturnat cetățile acestea și toată câmpia și pe toți locuitorii cetăților și vegetația pământului."},{"v":26,"t":"Și soția lui s-a uitat înapoi, în urma îngerului, ca să știe ce se va întâmpla la sfârșit cu casa tatălui ei, căci ea era dintre fiicele sodomiților; și pentru că păcătuise cu sare, dând în vileag pe săraci, iată, ea a fost făcută stâlp de sare.","notes":["„a păcătuit cu sare, dând în vileag pe săraci”: după tradiția agadică, ea a cerut sare de la vecini pentru oaspeți și astfel i-a dat de gol (Bereșit Rabba 51:5; 50:4). Rosen: „Iar soția lui Lot s-a uitat din spatele lui”."]},{"v":27,"t":"Și Avraam s-a sculat devreme dimineața la locul unde slujise în rugăciune înaintea Domnului."},{"v":28,"t":"Și a privit spre fața Sodomei și a Gomorei și spre toată fața ținutului câmpiei; și a văzut, și iată, fumul pământului se ridica precum fumul unui cuptor."},{"v":29,"t":"Și a fost, când Domnul a nimicit cetățile câmpiei, Domnul Și-a amintit de meritul lui Avraam și l-a trimis pe Lot din mijlocul prăpădului, când a răsturnat cetățile în care locuia Lot."},{"v":30,"t":"Și Lot a urcat din Țoar și a locuit în munte, și cele două fiice ale lui cu el, căci se temea să locuiască în Țoar; și a locuit în peșteră, el și cele două fiice ale lui."},{"v":31,"t":"Și a zis cea mare către cea mică: „Tatăl nostru este bătrân, și nu este bărbat pe pământ care să intre la noi după obiceiul întregului pământ."},{"v":32,"t":"Vino, să-i dăm tatălui nostru să bea vin, și când va fi beat să ne culcăm cu el și să ridicăm fii de la tatăl nostru.”"},{"v":33,"t":"Și i-au dat tatălui lor să bea vin în noaptea aceea, și el s-a îmbătat; și s-a ridicat cea mare și s-a culcat cu tatăl ei, iar el nu a știut când s-a culcat ea și nu a știut când s-a ridicat."},{"v":34,"t":"Și a fost a doua zi, și a zis cea mare către cea mică: „Iată, m-am culcat deja aseară cu tatăl meu; să-i dăm să bea vin și în noaptea aceasta, și se va îmbăta, și intră, culcă-te cu el, și să ridicăm fii de la tatăl nostru.”"},{"v":35,"t":"Și i-au dat tatălui lor să bea vin și în noaptea aceea, și s-a îmbătat; și s-a ridicat cea mică și s-a culcat cu el, iar el nu a știut când s-a culcat ea și nici când s-a ridicat."},{"v":36,"t":"Și cele două fiice ale lui Lot au rămas însărcinate de la tatăl lor."},{"v":37,"t":"Și cea mare a născut un fiu și i-a pus numele Moav, căci de la tatăl ei rămăsese însărcinată; el este tatăl moabiților până în ziua aceasta.","notes":["„Moav”: me-av, „de la tată”."]},{"v":38,"t":"Și cea mică a născut și ea un fiu și i-a pus numele Ben-Ami, căci el este fiul tatălui ei; el este tatăl poporului amoniților până în ziua aceasta."}]},{"num":20,"title":"Capitolul 20","verses":[{"v":1,"t":"Și Avraam a pornit de acolo spre țara de miazăzi și a locuit între Reqam și Hagra și a locuit ca străin în Gherar.","notes":["Rosen: „s-a așezat între Cades și Șur”; Targumul are Reqam și Hagra (ca la 16:7, 16:14)."]},{"v":2,"t":"Și Avraam a zis despre Sara, soția lui: „Ea este sora mea.” Și Abimelec, regele Gherarului, a trimis și a luat-o pe Sara."},{"v":3,"t":"Și a venit un cuvânt de la Domnul la Abimelec în visul nopții și i-a zis: „Iată, vei muri din pricina femeii pe care ai luat-o cu sila, căci ea este măritată cu un bărbat.”"},{"v":4,"t":"Dar Abimelec nu se apropiase de ea ca s-o pângărească; și a zis: „Doamne, oare un popor care nu a păcătuit și căruia i se cuvine să fie achitat la judecată îl vei ucide?","notes":["Rosen: „Stăpâne, oare vei ucide un neam, chiar dacă este drept?”"]},{"v":5,"t":"Oare nu el mi-a zis: «Ea este sora mea»? Și ea însăși a zis: «El este fratele meu.» Cu inima curată și cu mâini nevinovate am făcut aceasta.”"},{"v":6,"t":"Și i-a zis Cuvântul Domnului în vis: „Și înaintea Mea este descoperit că ai făcut aceasta cu inima curată, și te-am oprit și Eu de la a păcătui înaintea Mea; de aceea nu te-am lăsat să te apropii de ea."},{"v":7,"t":"Și acum dă înapoi soția bărbatului, căci el este profet și se va ruga pentru tine și vei trăi; iar dacă nu o dai înapoi, să știi că vei muri negreșit, tu și tot ce este al tău.”"},{"v":8,"t":"Și Abimelec s-a sculat devreme dimineața și i-a chemat pe toți slujitorii lui și a spus toate aceste cuvinte înaintea lor, iar oamenii s-au temut foarte mult."},{"v":9,"t":"Și Abimelec l-a chemat pe Avraam și a zis: „Ce ne-ai făcut? Și cu ce am păcătuit față de tine, că ai adus asupra mea și asupra împărăției mele un păcat mare? Fapte care nu se cuvin să fie făcute ai făcut cu mine.”"},{"v":10,"t":"Și a zis Abimelec către Avraam: „Ce ai văzut de ai făcut lucrul acesta?”"},{"v":11,"t":"Și a zis Avraam: „Pentru că am zis în inima mea: «Numai că nu este frica Domnului în locul acesta, și mă vor ucide din pricina soției mele.»"},{"v":12,"t":"Și totuși, cu adevărat, ea este sora mea, fiica fratelui tatălui meu, dar nu din familia mamei mele; și mi-a devenit soție."},{"v":13,"t":"Și a fost, când închinătorii la idoli au căutat să mă rătăcească și am ieșit din casa tatălui meu, i-am zis: «Aceasta este bunătatea pe care să mi-o faci: în orice loc în care vom merge, spune despre mine: El este fratele meu.»”"},{"v":14,"t":"Și Abimelec a luat oi și boi și robi și roabe și i-a dat lui Avraam și i-a dat înapoi pe Sara, soția lui."},{"v":15,"t":"Și a zis Abimelec: „Iată, țara mea este înaintea ta; locuiește unde este bine în ochii tăi.”"},{"v":16,"t":"Iar Sarei i-a zis: „Iată, i-am dat fratelui tău o mie de sela de argint; iată, ele să-ți fie o desfătare a ochilor (sau „o podoabă pentru ochi”), pentru că ai fost ascunsă de bărbatul tău o noapte și te-am văzut; căci chiar dacă ți-aș fi dat tot ce aveam, n-ar fi fost de ajuns.” Și lucrurile s-au lămurit, și Avraam a știut că Abimelec nu se apropiase de Sara, soția lui.","notes":["„Sela”: monedă de argint."]},{"v":17,"t":"Și Avraam s-a rugat înaintea Domnului, și Domnul l-a vindecat pe Abimelec și pe soția lui și pe roabele lui, și au fost ușurate; căci Cuvântul Domnului închisese de tot, cu toate balamalele lor, pântecele femeilor din casa lui Abimelec, din pricina Sarei, soția lui Avraam.","notes":["„Cu toate balamalele lor” (be-anpei kol ṣireih): imaginea pântecelui ca ușă cu balamale.","Unitatea este traducerea versetelor 20:17–18."]}]},{"num":21,"title":"Capitolul 21","verses":[{"v":1,"t":"Și Domnul Și-a amintit de Sara, cum îi spusese, și Domnul i-a făcut Sarei o minune, cum vorbise lui Avraam în rugăciunea lui pentru Abimelec."},{"v":2,"t":"Și Sara a rămas însărcinată și i-a născut lui Avraam un fiu, care semăna cu el, la bătrânețea lui, la vremea despre care îi vorbise Domnul."},{"v":3,"t":"Și Avraam i-a pus fiului său, care i se născuse, pe care i-l născuse Sara, numele Isaac."},{"v":4,"t":"Și Avraam l-a circumcis pe Isaac, fiul său, la vârsta de opt zile, cum îi poruncise Domnul."},{"v":5,"t":"Și Avraam avea o sută de ani când i s-a născut Isaac, fiul său."},{"v":6,"t":"Și a zis Sara: „O minune mi-a făcut Domnul; oricine va auzi se va minuna de mine.”","notes":["Rosen: „Dumnezeu mi-a făcut pricină de râs; oricine aude va râde pentru mine.” Targumul: „o minune… se va minuna”."]},{"v":7,"t":"Și a zis: „Cât de vrednic de încredere este vestitorul care l-a vestit pe Avraam și a zis: «Sara va alăpta fii»; căci i-am născut un fiu la vremea bătrâneții lui.”"},{"v":8,"t":"Și copilul a crescut și a fost înțărcat, și Avraam a făcut un ospăț mare în ziua în care l-a înțărcat pe Isaac."},{"v":9,"t":"Și Sara l-a văzut pe fiul Agarei egipteanca, pe care ea i-l născuse lui Avraam, râzând în slujirea străină și plecându-se idolului.","notes":["Rosen: „Și Sara l-a văzut pe fiul Agarei egipteanca, pe care i-l născuse lui Avraam, batjocorind.” Targumul înțelege meṣaḥeq ca joc idolatru."]},{"v":10,"t":"Și i-a zis lui Avraam: „Alungă-o pe roaba aceasta și pe fiul ei, căci nu se cuvine ca fiul roabei acesteia să moștenească împreună cu fiul meu și să poarte război cu Isaac.”"},{"v":11,"t":"Și lucrul a fost foarte rău în ochii lui Avraam din pricina lui Ismael, fiul lui, care avea să slujească slujirii străine."},{"v":12,"t":"Și a zis Domnul către Avraam: „Să nu fie rău în ochii tăi pentru copilul care a ieșit din grija ta și pentru roaba ta pe care o alungi; tot ce îți va spune Sara primește de la ea, căci ea este profetesă; pentru că prin Isaac ți se vor numi fii, iar acesta, fiul roabei, nu va fi socotit în urma ta."},{"v":13,"t":"Și de asemenea pe fiul roabei îl voi face un popor de tâlhari, pentru că este fiul tău.”","notes":["Rosen: „Dar și pe fiul slujnicei îl voi face un neam, căci este din seminția ta.”"]},{"v":14,"t":"Și Avraam s-a sculat devreme dimineața și a luat pâine și un burduf cu apă și i le-a dat Agarei, i le-a pus pe umăr și i l-a legat la mijloc, ca să se știe că ea este roabă, și pe copil, și a trimis-o cu act de despărțire; și ea a plecat și s-a rătăcit de pe drum în pustiul care este lângă Beer-Șeba.","notes":["Beer-Șeba: Targumul are aici „fântâna lui Șeba” (bira de-Ševaʿ)."]},{"v":15,"t":"Și a fost, când au ajuns la intrarea pustiului, și-au amintit să rătăcească după slujirea străină; și Ismael a fost lovit de o febră arzătoare și a băut toată apa, până s-a terminat toată apa din burduf; și a fost ars de febră, și i-a slăbit trupul; și ea l-a purtat și a obosit, și a chemat idolul tatălui ei, dar acesta nu i-a răspuns; și îndată l-a aruncat pe copil sub unul dintre pomi."},{"v":16,"t":"Și s-a dus și s-a așezat deoparte și a aruncat idolul; s-a depărtat de fiul ei cât o aruncătură de arc, căci a zis: „Nu pot să privesc moartea copilului”; și s-a așezat în fața fiului ei și și-a ridicat glasul și a plâns."},{"v":17,"t":"Și s-a auzit înaintea Domnului glasul copilului, pentru meritul lui Avraam; și îngerul Domnului a chemat-o pe Agar din ceruri și i-a zis: „Ce ai, Agar? Nu te teme, căci s-a auzit înaintea Domnului glasul copilului, și nu l-a judecat după faptele lui rele pe care avea să le facă, ci, pentru meritul lui Avraam, S-a îndurat de el în locul în care este."},{"v":18,"t":"Ridică-te, ia copilul și întărește-ți mâinile asupra lui, căci îl voi face un popor mare.”"},{"v":19,"t":"Și Domnul i-a deschis ochii, și i s-a arătat o fântână de apă; și s-a dus și a umplut burduful cu apă și i-a dat copilului să bea."},{"v":20,"t":"Și Cuvântul Domnului a fost în ajutorul copilului, și a crescut și a locuit în pustiu și a devenit un arcaș iscusit."},{"v":21,"t":"Și a locuit în pustiul Paran și și-a luat o soție, pe ʿAdișa, și a alungat-o; și mama lui i-a luat-o de soție pe Faṭima, din țara Egiptului („Mițrayim”).","notes":["ʿAdișa și Faṭima: numele soțiilor lui Ismael după tradiția agadică (Pirkei de-Rabbi Eliezer 30)."]},{"v":22,"t":"Și a fost în vremea aceea, și au zis Abimelec și Picol, căpetenia oștirii lui, către Avraam, spunând: „Cuvântul Domnului este în ajutorul tău în tot ce faci."},{"v":23,"t":"Și acum jură-mi aici pe Cuvântul Domnului că nu vei fi necredincios față de mine și față de fiul meu și față de fiul fiului meu; după bunătatea pe care am făcut-o cu tine să faci și tu cu mine și cu țara în care ai locuit ca străin.”"},{"v":24,"t":"Și a zis Avraam: „Eu voi jura.”"},{"v":25,"t":"Și Avraam l-a mustrat pe Abimelec din pricina fântânii de apă pe care i-o luaseră cu sila slujitorii lui Abimelec."},{"v":26,"t":"Și a zis Abimelec: „Nu știu cine a făcut lucrul acesta; și nici tu nu mi-ai spus, și nici eu n-am auzit de la alții, decât astăzi de la tine.”"},{"v":27,"t":"Și Avraam a luat oi și boi și i-a dat lui Abimelec, și au încheiat amândoi un legământ."},{"v":28,"t":"Și Avraam a pus deoparte șapte mielușele și le-a despărțit de boi."},{"v":29,"t":"Și a zis Abimelec către Avraam: „Ce sunt aceste șapte mielușele pe care le-ai pus deoparte?”"},{"v":30,"t":"Și a zis: „Aceste șapte mielușele să le primești din mâna mea, ca să-mi fie mărturie că eu am săpat fântâna aceasta.”"},{"v":31,"t":"De aceea a numit fântâna aceea „Fântâna celor șapte mielușele”, căci acolo au jurat amândoi.","notes":["Rosen: „De aceea, locul acela s-a numit Beer Șeba”; Targumul traduce numele („fântâna celor șapte mielușele”)."]},{"v":32,"t":"Și au încheiat legământ la Fântâna celor șapte mielușele; și s-au ridicat Abimelec și Picol, căpetenia oștirii lui, și s-au întors în țara filistenilor."},{"v":33,"t":"Și a sădit o livadă la Fântâna celor șapte mielușele și a pregătit în ea mâncare și băutură pentru trecători și pentru cei care veneau; și le vestea acolo: „Mulțumiți și credeți în Numele Cuvântului Domnului, Dumnezeul lumii.”","notes":["Rosen: „Iar Avraam a sădit un eșel în Beer-Șeba și a chemat acolo numele Domnului, Dumnezeului lumii.” Targumul înțelege eșel ca „livadă” cu ospitalitate. Targumul nu numește aici pe Avraam. În ediția sursă lipsește versetul 21:34; numerotarea urmează sursa."]}]},{"num":22,"title":"Capitolul 22","verses":[{"v":1,"t":"Și a fost după aceste lucruri, după ce s-au certat Isaac și Ismael. Ismael zicea: „Mi se cuvine să-l moștenesc pe tata, pentru că eu sunt fiul lui cel întâi născut.” Iar Isaac zicea: „Mi se cuvine să-l moștenesc pe tata, pentru că eu sunt fiul Sarei, soția lui, iar tu ești fiul Agarei, roaba mamei mele.” A răspuns Ismael și a zis: „Eu sunt mai drept decât tine, căci eu am fost circumcis la treisprezece ani, și dacă aș fi vrut să mă împotrivesc, nu m-aș fi dat să fiu circumcis; iar tu ai fost circumcis la opt zile: dacă ai fi avut știință, poate nu te-ai fi dat să fii circumcis.” A răspuns Isaac și a zis: „Iată, astăzi am treizeci și șase de ani, și dacă Sfântul, binecuvântat fie El, mi-ar cere toate mădularele mele, nu m-aș împotrivi.” Îndată s-au auzit aceste cuvinte înaintea Stăpânului lumii, și îndată Cuvântul Domnului l-a încercat pe Avraam și i-a zis: „Avraam!” Și el i-a zis: „Iată-mă.”"},{"v":2,"t":"Și a zis: „Ia, te rog, pe fiul tău, pe unicul tău, pe care îl iubești, pe Isaac, și du-te în țara slujirii și adu-l acolo ca ardere-de-tot pe unul dintre munții pe care ți-l voi spune.”","notes":["Rosen: „mergi spre ținutul Moria”; Targumul: „țara slujirii” (a închinării, adică locul Templului)."]},{"v":3,"t":"Și Avraam s-a sculat devreme dimineața și și-a pregătit măgarul și i-a luat cu el pe cei doi tineri ai lui, pe Eliezer și pe Ismael, și pe Isaac, fiul său; și a tăiat lemne de qeyta, de smochin și de finic, care sunt potrivite pentru arderea-de-tot; și s-a ridicat și s-a dus la locul pe care i-l spusese Domnul.","notes":["qeyta: sensul nesigur; probabil măslinul (alte ediții au zayta, „măslin”)."]},{"v":4,"t":"În ziua a treia, Avraam și-a ridicat ochii și a văzut norul slavei legat de munte și l-a recunoscut de departe."},{"v":5,"t":"Și a zis Avraam către tinerii lui: „Așteptați aici cu măgarul, iar eu și tânărul vom ajunge până acolo, ca să vedem dacă se va împlini ce am fost vestit, «așa vor fi fiii tăi»; și ne vom închina Stăpânului lumii și ne vom întoarce la voi.”","notes":["„așa vor fi fiii tăi”: făgăduința de la 15:5."]},{"v":6,"t":"Și Avraam a luat lemnele pentru arderea-de-tot și le-a pus pe Isaac, fiul său, și a luat în mâna lui focul și cuțitul; și au mers amândoi împreună."},{"v":7,"t":"Și a zis Isaac către Avraam, tatăl său, și a zis: „Tată!” Și el a zis: „Iată-mă.” Și a zis: „Iată focul și lemnele, dar unde este mielul pentru arderea-de-tot?”"},{"v":8,"t":"Și a zis Avraam: „Domnul Își va alege mielul pentru arderea-de-tot.” Și au mers amândoi împreună, cu inimă întreagă."},{"v":9,"t":"Și au venit la locul pe care i-l spusese Domnul, și Avraam a construit acolo altarul pe care îl construise Adam și care fusese dărâmat de apele potopului, și pe care l-a refăcut Noe și fiii lui și care a fost dărâmat în generația dezbinării; și a așezat pe el lemnele și l-a legat pe Isaac, fiul său, și l-a pus pe altar, deasupra lemnelor."},{"v":10,"t":"Și Avraam și-a întins mâna și a luat cuțitul ca să-l înjunghie pe fiul său. A răspuns Isaac și a zis către tatăl său: „Leagă-mă bine, ca să nu zvâcnesc din durerea sufletului meu și să fiu împins în groapa pieirii și să se afle un cusur în jertfa ta.” Ochii lui Avraam priveau la ochii lui Isaac, iar ochii lui Isaac priveau la îngerii de sus; Isaac îi vedea, iar Avraam nu-i vedea. Au răspuns îngerii de sus: „Veniți, vedeți doi unici care sunt în lume: unul înjunghie și unul este înjunghiat; cel care înjunghie nu șovăie, iar cel care este înjunghiat își întinde gâtul.”"},{"v":11,"t":"Și l-a chemat îngerul Domnului din ceruri și i-a zis: „Avraam, Avraam!” Și el a zis: „Iată-mă.”"},{"v":12,"t":"Și a zis: „Nu-ți întinde mâna asupra copilului și nu-i face nimic rău, căci acum este descoperit înaintea Mea că ești temător de Domnul și nu l-ai oprit de la Mine pe fiul tău, pe unicul tău.”"},{"v":13,"t":"Și Avraam și-a ridicat ochii și a văzut, și iată, un berbec, care fusese creat în amurgul desăvârșirii lumii, prins cu coarnele în desișul unui copac; și Avraam s-a dus și l-a luat și l-a adus ca ardere-de-tot în locul fiului său.","notes":["„creat în amurg”: berbecul lui Isaac este unul dintre lucrurile create în amurgul primei vineri (Mișna Avot 5:6). Rosen: „un berbec, după aceea, prins în desiș cu coarnele.”"]},{"v":14,"t":"Și Avraam a mulțumit și s-a rugat acolo, în locul acela, și a zis: „Te rog, cu îndurare dinaintea Ta, Doamne: este descoperit înaintea Ta că nu a fost viclenie în inima mea și m-am îndreptat să împlinesc porunca Ta cu bucurie. Tot așa, când fiii lui Isaac, fiul meu, vor intra în ceasul strâmtorării, să-Ți amintești de ei și să le răspunzi și să-i răscumperi.” Și toate generațiile care vor fi vor spune: „Pe muntele acesta l-a legat Avraam pe Isaac, fiul său, și acolo S-a descoperit asupra lui Șechina Domnului.”","notes":["Rosen: „Și Avraam a pus acelui loc numele Adonai-Ire, de unde se spune până astăzi: «pe munte Domnul va fi văzut.»”"]},{"v":15,"t":"Și îngerul Domnului l-a chemat pe Avraam a doua oară din ceruri"},{"v":16,"t":"și a zis: „Pe Cuvântul Meu am jurat, zice Domnul: pentru că ai făcut lucrul acesta și nu l-ai oprit pe fiul tău, pe unicul tău,"},{"v":17,"t":"te voi binecuvânta negreșit și îi voi înmulți foarte mult pe fiii tăi ca stelele cerurilor și vor fi ca nisipul de pe țărmul mării; și fiii tăi vor moșteni cetățile dușmanilor lor."},{"v":18,"t":"Și se vor binecuvânta, pentru meritele fiilor tăi, toate popoarele pământului, pentru că ai ascultat de Cuvântul Meu.”"},{"v":19,"t":"Și îngerii de sus l-au luat pe Isaac și l-au dus la casa de studiu a lui Sem cel Mare, și a fost acolo trei ani; iar în ziua aceea Avraam s-a întors la tinerii lui, și s-au ridicat și s-au dus împreună la Beer-Șeba; și Avraam a locuit în Beer-Șeba."},{"v":20,"t":"Și a fost după aceste lucruri, după ce Avraam l-a legat pe Isaac, a venit Satan și i-a spus Sarei că Avraam l-a înjunghiat pe Isaac; și Sara s-a ridicat și a strigat și s-a sufocat și a murit de durere. Și Avraam a venit și a înnoptat pe drum, și i s-a spus lui Avraam: „Iată, Milca a fost și ea ușurată, prin meritul surorii ei, să nască fii lui Nahor, fratele tău:","notes":["Rosen: „Și a fost după aceste lucruri, că lui Avraam i s-a vestit, spunând: iată, Milca i-a născut și ea copii fratelui tău Nahor”."]},{"v":21,"t":"pe Uț, întâiul lui născut, și pe Buz, fratele lui, și pe Chemuel, căpetenia vrăjitorilor arameilor,","notes":["Rosen: „pe Chemuel, părintele Aramului”."]},{"v":22,"t":"și pe Chesed și pe Hazo și pe Pildaș și pe Idlaf și pe Betuel.”"},{"v":23,"t":"Și Betuel a născut-o pe Rebeca. Pe acești opt i-a născut Milca lui Nahor, fratele lui Avraam."},{"v":24,"t":"Și concubina lui, al cărei nume era Reuma, a născut și ea pe Tebah și pe Gaham și pe Tahaș și pe Maaca."}]},{"num":23,"title":"Capitolul 23","verses":[{"v":1,"t":"Și au fost anii vieții Sarei — și au fost anii vieții Sarei o sută douăzeci și șapte de ani —, anii vieții Sarei.","notes":["Rosen: „Și a fost viața Sarei o sută douăzeci și șapte de ani – anii vieții Sarei.” Sursa repetă începutul versetului; redat după sursă."]},{"v":2,"t":"Și Sara a murit în Chiriat-Arba, adică Hebron, în țara Canaanului; și Avraam a venit de pe muntele slujirii și a găsit-o moartă, și s-a așezat s-o jelească pe Sara și s-o plângă.","notes":["„muntele slujirii”: muntele Moria (vezi 22:2)."]},{"v":3,"t":"Și Avraam s-a ridicat de lângă moarta lui și a vorbit cu fiii lui Het, spunând:"},{"v":4,"t":"„Străin și locuitor vremelnic sunt eu printre voi; vindeți-mi, vă rog, o moștenire pentru mormânt la voi, ca să-mi îngrop moarta acolo.”"},{"v":5,"t":"Și fiii lui Het i-au răspuns lui Avraam, spunându-i:"},{"v":6,"t":"„Ascultă-ne, stăpâne! Mare înaintea Domnului ești tu printre noi; în cel mai frumos dintre mormintele noastre îngroapă-ți moarta: niciunul dintre noi nu-ți va opri mormântul lui, ca să nu-ți îngropi moarta.”"},{"v":7,"t":"Și Avraam s-a ridicat și s-a plecat înaintea poporului țării, înaintea fiilor lui Het."},{"v":8,"t":"Și a vorbit cu ei, spunând: „Dacă este voia voastră să-mi îngrop moarta dinaintea mea, ascultați-mă și rugați-vă pentru mine înaintea lui Efron, fiul lui Țohar,"},{"v":9,"t":"să-mi vândă peștera cea dublă, care este a lui, care este construită la marginea câmpului lui; cu argint deplin să mi-o dea în mijlocul vostru ca moștenire pentru mormânt.”","notes":["Rosen: „peștera Macpela”; Targumul are kefilta, „cea dublă”; la 23:17 și 23:19 numele este transcris (Kafelta)."]},{"v":10,"t":"Și Efron ședea în mijlocul fiilor lui Het; și Efron hititul i-a răspuns lui Avraam în fața fiilor lui Het, a tuturor celor care intrau pe poarta cetății lui, spunând:"},{"v":11,"t":"„Te rog, stăpâne, ascultă-mă: câmpul ți l-am dat, și peștera care este în el ți-am dat-o; ca dar, în fața fiilor poporului meu, ți-am dat-o; du-te, îngroapă-ți moarta.”"},{"v":12,"t":"Și Avraam s-a plecat înaintea lui, în fața fiilor lui Het."},{"v":13,"t":"Și a vorbit cu Efron în fața poporului țării, spunând: „Numai, dacă vrei să-mi faci un bine, ascultă-mă: voi da argintul, prețul câmpului; ia-l de la mine, și îmi voi îngropa moarta acolo.”"},{"v":14,"t":"Și Efron i-a răspuns lui Avraam, spunându-i:"},{"v":15,"t":"„Stăpâne, ascultă-mă: un pământ al cărui preț este de patru sute de sela de argint, ce este aceasta între mine și tine? Îngroapă-ți moarta.”","notes":["Rosen: „patru sute de sicli de argint”; Targumul are selaʿin („sela”)."]},{"v":16,"t":"Și Avraam l-a ascultat pe Efron, și Avraam i-a cântărit lui Efron argintul de care vorbise în fața fiilor lui Het, patru sute de sela de argint bun, care trec la orice masă de schimb și sunt primite în orice negoț."},{"v":17,"t":"Și s-a statornicit cumpărarea câmpului lui Efron, care este în Kafelta, care este în fața lui Mamre: câmpul și peștera care este în el și toți pomii care sunt în câmp, care sunt în tot hotarul lui de jur împrejur,"},{"v":18,"t":"lui Avraam, ca bun cumpărat, în fața fiilor lui Het, a tuturor celor care intrau pe poarta cetății lui."},{"v":19,"t":"Și după aceea Avraam a îngropat-o pe Sara, soția lui, în peștera câmpului Kafelta, care este în fața lui Mamre, adică Hebron, în țara Canaanului."},{"v":20,"t":"Și s-a statornicit câmpul și peștera care este în el lui Avraam ca moștenire pentru mormânt, de la fiii lui Het."}]},{"num":24,"title":"Capitolul 24","verses":[{"v":1,"t":"Și Avraam era bătrân, înaintat în zile, și Cuvântul Domnului l-a binecuvântat pe Avraam cu toate felurile de binecuvântări."},{"v":2,"t":"Și a zis Avraam către Eliezer, slujitorul lui, bătrânul casei lui, care stăpânea peste toate vistieriile lui: „Pune-ți, te rog, mâna sub tăietura circumciziei mele.","notes":["Rosen: „Pune-ți, te rog, mâna sub coapsa mea.”"]},{"v":3,"t":"Și te voi pune să juri pe Numele Cuvântului Domnului, Dumnezeul a cărui locuință este în cerurile de sus, El este Dumnezeul a cărui stăpânire este peste pământ, că nu vei lua soție pentru fiul meu dintre fiicele canaaniților, în mijlocul cărora locuiesc eu;"},{"v":4,"t":"ci în țara mea și la casa familiei mele te vei duce și vei lua o soție pentru fiul meu, Isaac.”"},{"v":5,"t":"Și i-a zis slujitorul: „Poate femeia nu va voi să vină după mine în țara aceasta; să-l duc oare înapoi pe fiul tău în țara din care ai ieșit?”"},{"v":6,"t":"Și i-a zis Avraam: „Păzește-te să nu-l duci pe fiul meu înapoi acolo."},{"v":7,"t":"Domnul, Dumnezeul a cărui locuință este în cerurile de sus, care m-a luat din casa tatălui meu și din țara nașterii mele și care mi-a vorbit și mi-a jurat, spunând: «Fiilor tăi le voi da țara aceasta», El va trimite pe îngerul Său înaintea ta, și vei lua de acolo o soție pentru fiul meu."},{"v":8,"t":"Iar dacă femeia nu va voi să vină după tine, vei fi dezlegat de jurământul acesta al meu; numai pe fiul meu să nu-l duci înapoi acolo.”"},{"v":9,"t":"Și slujitorul și-a pus mâna sub tăietura circumciziei lui Avraam, stăpânul său, și i-a jurat (pentru) lucrul acesta.","notes":["„(pentru)”: paranteza este în ediția sursă."]},{"v":10,"t":"Și slujitorul a luat zece cămile dintre cămilele stăpânului său și a plecat, având în mâna lui tot ce era mai bun din vistieriile stăpânului său; și s-a ridicat și s-a dus în Aramul de pe Eufrat, la cetatea lui Nahor.","notes":["Rosen: „la Aram-Naharaim”."]},{"v":11,"t":"Și a făcut cămilele să îngenuncheze afară din cetate, lângă fântâna de apă, la vremea serii, la vremea când ies cele care scot apă."},{"v":12,"t":"Și a zis: „Doamne, Dumnezeul stăpânului meu Avraam, pregătește acum înaintea mea, astăzi, o femeie potrivită, și fă bine stăpânului meu Avraam."},{"v":13,"t":"Iată, eu stau lângă izvorul de apă, și fiicele oamenilor cetății ies să scoată apă."},{"v":14,"t":"Și fata căreia îi voi spune: «Apleacă-ți, te rog, ulciorul, ca să beau», și va zice: «Bea, și voi adăpa și cămilele tale», pe aceea ai pregătit-o prin soartă robului Tău, lui Isaac; și prin ea voi ști că ai făcut bine stăpânului meu.”","notes":["„prin soartă” (be-mazzala): literal „prin constelație, noroc”."]},{"v":15,"t":"Și a fost într-o clipă: încă nu terminase să vorbească, și iată, Rebeca a ieșit, care i se născuse lui Betuel, fiul Milcăi, soția lui Nahor, fratele lui Avraam, cu ulciorul pe umăr."},{"v":16,"t":"Și fata era foarte frumoasă la vedere, fecioară, și niciun bărbat nu o cunoscuse prin culcare; și a coborât la izvor și și-a umplut ulciorul și a urcat."},{"v":17,"t":"Și slujitorul a alergat în întâmpinarea ei și a zis: „Dă-mi să gust, te rog, puțină apă din ulciorul tău.”"},{"v":18,"t":"Și ea a zis: „Bea, stăpâne”; și s-a grăbit și și-a coborât ulciorul pe mână și i-a dat să bea."},{"v":19,"t":"Și a terminat să-i dea să bea și a zis: „Și pentru cămilele tale voi scoate, până vor termina de băut.”"},{"v":20,"t":"Și s-a grăbit și și-a golit ulciorul în jgheabul adăpătorii și a alergat iarăși la fântână să scoată, și a scos pentru toate cămilele lui."},{"v":21,"t":"Și omul o aștepta și tăcea, ca să știe dacă Domnul i-a făcut să izbutească drumul sau nu."},{"v":22,"t":"Și a fost, când cămilele au terminat de băut, omul a luat un inel de nas de aur, greu de o drahmă, corespunzător drahmei de cap pe care aveau s-o dea fiii ei pentru lucrarea Cortului, și două brățări le-a pus pe mâinile ei, grele de zece sela de aur, suma greutății lor corespunzând celor două table pe care sunt scrise cele Zece Cuvinte.","notes":["Rosen: „un inel de aur pentru nas în greutate de o beka… cu greutatea de zece sicli de aur.” „drahma de cap”: jumătatea de siclu dată pentru Cort (Exodul 38:26). „aveau s-o dea” (ʾiṭmosin): sensul cuvântului din sursă este nesigur; redat după context."]},{"v":23,"t":"Și a zis: „A cui fiică ești? Spune-mi, te rog: este în casa tatălui tău un loc potrivit pentru noi ca să înnoptăm?”"},{"v":24,"t":"Și ea i-a zis: „Sunt fiica lui Betuel, fiul Milcăi, pe care ea i l-a născut lui Nahor.”"},{"v":25,"t":"Și i-a mai zis: „Și paie și nutreț avem din belșug, și un loc potrivit pentru înnoptat.”"},{"v":26,"t":"Și omul s-a plecat și s-a închinat înaintea Domnului, care pregătise înaintea lui o femeie potrivită."},{"v":27,"t":"Și a zis: „Binecuvântat este Numele Domnului, Dumnezeul stăpânului meu Avraam, care nu Și-a oprit bunătatea și adevărul de la stăpânul meu; pe mine, prin meritul lui, pe calea cea dreaptă m-a călăuzit Domnul la casa fratelui stăpânului meu.”"},{"v":28,"t":"Și fata a alergat și a povestit în casa mamei ei după cuvintele acestea."},{"v":29,"t":"Și Rebeca avea un frate, al cărui nume era Laban; și Laban a alergat la omul acela afară, la izvor."},{"v":30,"t":"Și a fost, când a văzut inelul de nas și brățările pe mâinile surorii lui și când a auzit cuvintele Rebecăi, sora lui, spunând: „Așa mi-a vorbit omul”, a venit la omul acela; și iată, el stătea lângă cămile, la izvor."},{"v":31,"t":"Și Laban a crezut că el este Avraam și a zis: „Intră, binecuvântatul Domnului! De ce stai afară? Iar eu am curățat casa de slujirea străină și am pregătit loc pentru cămile.”"},{"v":32,"t":"Și omul a intrat în casă și a dezlegat botnițele cămilelor; și (Laban) a dat paie și nutreț cămilelor și apă ca să-și spele picioarele lui și picioarele oamenilor care erau cu el.","notes":["„(Laban)”: paranteza este în ediția sursă."]},{"v":33,"t":"Și au pus înaintea lui să mănânce o mâncare în care era otravă de moarte; dar el a simțit-o și a zis: „Nu voi mânca până nu voi spune cuvintele mele.” Și a zis: „Vorbește.”"},{"v":34,"t":"Și a zis: „Eu sunt slujitorul lui Avraam."},{"v":35,"t":"Și Domnul l-a binecuvântat foarte mult pe stăpânul meu, și el a ajuns mare; și i-a dat oi și boi și argint și aur și robi și roabe și cămile și măgari."},{"v":36,"t":"Și Sara, soția stăpânului meu, i-a născut stăpânului meu un fiu după ce îmbătrânise, și el i-a dat tot ce are."},{"v":37,"t":"Și stăpânul meu m-a pus să jur, spunând: «Să nu iei soție pentru fiul meu dintre fiicele canaaniților, în țara cărora locuiesc eu;"},{"v":38,"t":"ci la casa tatălui meu să te duci și la neamul meu și să iei o soție pentru fiul meu.»"},{"v":39,"t":"Și i-am zis stăpânului meu: «Poate femeia nu va veni după mine.»"},{"v":40,"t":"Și mi-a zis: «Domnul, înaintea căruia am slujit, Își va trimite îngerul cu tine și va face să izbutească drumul tău, și vei lua o soție pentru fiul meu din neamul meu și din familia casei tatălui meu."},{"v":41,"t":"Atunci vei fi dezlegat de jurământul meu, dacă vei merge la casa neamului meu; și dacă nu ți-o vor da, vei fi nevinovat față de jurământul meu.»"},{"v":42,"t":"Și am venit astăzi la izvor și am zis: «Doamne, Dumnezeul stăpânului meu Avraam, dacă faci acum să izbutească drumul meu pe care merg,"},{"v":43,"t":"iată, eu stau lângă izvorul de apă, și fata care va ieși să scoată apă și căreia îi voi spune: Dă-mi să beau, te rog, puțină apă din ulciorul tău,"},{"v":44,"t":"și îmi va spune: Și tu bea, și pentru cămilele tale voi scoate, ea este femeia pe care Domnul a pregătit-o prin soartă pentru fiul stăpânului meu.»"},{"v":45,"t":"Eu încă nu terminasem să vorbesc cu gândurile inimii mele, și iată, Rebeca a ieșit cu ulciorul pe umăr și a coborât la izvor și a scos apă; și i-am zis: «Dă-mi să beau, te rog.»"},{"v":46,"t":"Și s-a grăbit și și-a coborât ulciorul de pe ea și a zis: «Bea, și voi adăpa și cămilele tale»; și am băut, și a adăpat și cămilele."},{"v":47,"t":"Și am întrebat-o și am zis: «A cui fiică ești?» Și ea a zis: «Fiica lui Betuel, fiul lui Nahor, pe care i l-a născut Milca.» Și i-am pus inelul în nas și brățările pe mâini."},{"v":48,"t":"Și m-am plecat și m-am închinat înaintea Domnului și L-am binecuvântat pe Domnul, Dumnezeul stăpânului meu Avraam, care m-a călăuzit pe calea adevărului ca s-o iau pe fiica fratelui stăpânului meu pentru fiul lui."},{"v":49,"t":"Și acum, dacă vreți să faceți bunătate și adevăr cu stăpânul meu, spuneți-mi; și dacă nu, spuneți-mi, și mă voi întoarce spre miazăzi sau spre miazănoapte.”"},{"v":50,"t":"Și au răspuns Laban și Betuel și au zis: „De la Domnul a ieșit lucrul ca Rebeca să fie dată lui Isaac; noi nu-ți putem spune nici rău, nici bine."},{"v":51,"t":"Iată, Rebeca este înaintea ta: ia-o și du-te, și să fie soție fiului stăpânului tău, cum a vorbit Domnul.”"},{"v":52,"t":"Și a fost, când slujitorul lui Avraam a auzit cuvintele lor, s-a închinat până la pământ înaintea Domnului."},{"v":53,"t":"Și slujitorul a scos vase de argint și vase de aur și haine și le-a dat Rebecăi; și daruri a dat fratelui ei și mamei ei."},{"v":54,"t":"Și au mâncat și au băut, el și oamenii care erau cu el, și au înnoptat; și s-au sculat dimineața, și el a zis: „Lăsați-mă să plec la stăpânul meu.”"},{"v":55,"t":"Și pentru că vorbiseră seara, Betuel mâncase din mâncarea aceea, și l-au găsit dimineața, și iată, era mort. Și au zis fratele ei și mama ei: „Să rămână fata cu noi zilele unui an sau zece luni, și după aceea se va duce.”","notes":["Targumul explică de ce Betuel nu mai apare în continuare: a mâncat el însuși din mâncarea otrăvită pregătită pentru slujitor (24:33)."]},{"v":56,"t":"Și le-a zis: „Nu mă opriți, căci Domnul a făcut să izbutească drumul meu; lăsați-mă să plec, și mă voi duce la stăpânul meu.”"},{"v":57,"t":"Și au zis: „S-o chemăm pe fată și să auzim ce va spune ea.”"},{"v":58,"t":"Și au chemat-o pe Rebeca și i-au zis: „Te duci cu omul acesta?” Și ea a zis: „Mă duc.”"},{"v":59,"t":"Și au lăsat-o să plece pe Rebeca, sora lor, și pe doica ei și pe slujitorul lui Avraam și pe oamenii lui."},{"v":60,"t":"Și au binecuvântat-o pe Rebeca și i-au zis: „Până acum ai fost sora noastră, iar acum te duci și te măriți cu cel drept. Fie voia ca din tine să iasă mii de zeci de mii, și fiii tăi să moștenească cetățile dușmanilor lor.”"},{"v":61,"t":"Și s-a ridicat Rebeca și slujnicele ei și au încălecat pe cămile și au mers după omul acela; și slujitorul a luat-o pe Rebeca cu el și a călătorit. Și așa cum i se scurtase drumul când a mers la Padan-Aram, tot așa i s-a scurtat și la întoarcere: într-o zi a mers și într-o zi s-a întors."},{"v":62,"t":"Iar Isaac venea de la casa de studiu a lui Sem cel Mare, de la intrarea fântânii la care Se descoperise Cel Viu și Veșnic, care vede și nu este văzut; și el locuia în țara de miazăzi.","notes":["Rosen: „Iar Isaac tocmai venise de la Beer-Lahai-Roi”; vezi 16:14."]},{"v":63,"t":"Și Isaac a ieșit să se roage pe fața câmpului, spre seară; și și-a ridicat ochii și a văzut, și iată, veneau cămile.","notes":["Rosen: „Isaac a ieșit să cugete pe câmp pe înserat”; Targumul: „să se roage”."]},{"v":64,"t":"Și Rebeca și-a ridicat ochii și l-a văzut pe Isaac și s-a aplecat de pe cămilă."},{"v":65,"t":"Și a zis către slujitor: „Cine este omul acela falnic și chipeș care merge pe câmp în întâmpinarea noastră?” Și slujitorul a zis: „Este stăpânul meu.” Și ea a luat vălul și s-a acoperit cu el."},{"v":66,"t":"Și slujitorul i-a povestit lui Isaac toate lucrurile pe care le făcuse."},{"v":67,"t":"Și Isaac a adus-o în cortul Sarei, mama lui, și îndată s-a aprins candela care se stinsese când a murit Sara; și a luat-o pe Rebeca, și ea i-a devenit soție, și el a iubit-o, pentru că a văzut că faptele ei erau drepte ca faptele mamei lui; și Isaac s-a mângâiat după moartea mamei lui."}]},{"num":25,"title":"Capitolul 25","verses":[{"v":1,"t":"Și Avraam a mai luat o soție, și numele ei era Chetura; aceasta este Agar, care îi fusese legată de la început.","notes":["„care îi fusese legată” (de-qeṭira): Targumul leagă numele Chetura de verbul „a lega”."]},{"v":2,"t":"Și i i-a născut pe Zimran și pe Iocșan și pe Medan și pe Madian și pe Ișbac și pe Șuah."},{"v":3,"t":"Și Iocșan i-a născut pe Șeba și pe Dedan; și fiii lui Dedan au fost negustori și neguțători și căpetenii de popoare.","notes":["Rosen: „și fiii lui Dedan au fost Așurim, Letușim și Leumim”; Targumul traduce numele după sens."]},{"v":4,"t":"Și fiii lui Madian: Efa și Efer și Enoh și Abida și Eldaa; toți aceștia sunt fiii Cheturei."},{"v":5,"t":"Și Avraam i-a dat ca dar tot ce avea lui Isaac."},{"v":6,"t":"Iar fiilor concubinelor lui Avraam, Avraam le-a dat ca daruri averi și lucruri mișcătoare și i-a alungat de la Isaac, fiul său, cât era încă în viață; și s-au dus să locuiască spre răsărit, în țara răsăritului."},{"v":7,"t":"Și aceasta este suma zilelor vieții lui Avraam, pe care le-a trăit: o sută șaptezeci și cinci de ani."},{"v":8,"t":"Și Avraam și-a dat sufletul și a murit la o bătrânețe bună, bătrân și sătul de tot binele; iar Ismael a făcut pocăință în zilele lui; și după aceea a fost adunat la poporul său."},{"v":9,"t":"Și l-au îngropat Isaac și Ismael, fiii lui, în peștera cea dublă, în câmpul lui Efron, fiul lui Țohar hititul, care este în fața lui Mamre,"},{"v":10,"t":"câmpul pe care Avraam îl cumpărase de la fiii lui Het; acolo au fost îngropați Avraam și Sara, soția lui."},{"v":11,"t":"Și pentru că Avraam nu voise să-l binecuvânteze pe Ismael, de aceea nu l-a binecuvântat nici pe Isaac; căci dacă l-ar fi binecuvântat pe Isaac și nu l-ar fi binecuvântat pe Ismael, acesta i-ar fi păstrat dușmănie. Și după ce a murit Avraam, Domnul l-a binecuvântat pe Isaac; și Isaac a locuit lângă fântâna la care se descoperise slava Celui Viu și Veșnic, care vede și nu este văzut."},{"v":12,"t":"Și aceștia sunt urmașii lui Ismael, fiul lui Avraam, pe care i l-a născut lui Avraam Agar egipteanca, roaba Sarei."},{"v":13,"t":"Și acestea sunt numele fiilor lui Ismael, după numele lor, după urmașii lor: întâiul născut al lui Ismael, Nevai; și ʿArav și Adbeel și Mibsam,","notes":["La 25:13–15, unele nume sunt redate în sursă prin forme sau echivalente aramaice, transcrise aici: Nevai (Rosen: Nebaiot), ʿArav („Arabia”; Rosen: Chedar), Țemita (Rosen: Mișma), Șetuqa („tăcere”; Rosen: Duma), Subra („povară”; Rosen: Masa), Ḥarifa (Rosen: Hadad)."]},{"v":14,"t":"și Țemita și Șetuqa și Subra,"},{"v":15,"t":"Ḥarifa și Tema, Ietur, Nafiș și Chedma."},{"v":16,"t":"Aceștia sunt fiii lui Ismael, și acestea sunt numele lor, în satele lor și în taberele lor: doisprezece căpetenii pentru neamurile lor.","notes":["Rosen: „după așezările lor și după cetățile lor”."]},{"v":17,"t":"Și aceștia sunt anii vieții lui Ismael: o sută treizeci și șapte de ani; și s-a întors cu pocăință și și-a dat sufletul și a fost adunat la poporul său."},{"v":18,"t":"Și au locuit de la India până la Ḥaluṣa, care este în fața Egiptului („Mițrayim”), cum mergi spre Asiria; în fața tuturor fraților lui a locuit, în moștenirea lui.","notes":["Rosen: „de la Havila până la Șur, care este aproape de Egipt, venind spre Asiria”; India și Ḥaluṣa: ca la 2:11 și 16:14."]},{"v":19,"t":"Și acestea — și aceștia sunt urmașii lui Isaac, fiul lui Avraam; și pentru că chipul lui Isaac semăna cu chipul lui Avraam, oamenii ziceau: „Cu adevărat Avraam l-a născut pe Isaac.”","notes":["Ediția sursă începe versetul cu cuvântul ebraic al Torei („Și acestea”), urmat de traducerea aramaică."]},{"v":20,"t":"Și Isaac avea patruzeci de ani când a luat-o de soție pe Rebeca, fiica lui Betuel arameul din Padan-Aram, sora lui Laban arameul."},{"v":21,"t":"Și Isaac s-a dus la muntele slujirii, la locul unde îl legase tatăl lui, și Isaac a întors prin rugăciunea lui gândul Sfântului, binecuvântat fie El, de la ceea ce hotărâse asupra soției lui, căci era stearpă la el douăzeci și doi de ani; și s-a întors, pentru el, gândul Sfântului, binecuvântat fie El, de la ceea ce hotărâse asupra lui, căci și el era sterp; și a fost ușurată, și Rebeca, soția lui, a rămas însărcinată.","notes":["Rosen: „Și Isaac l-a implorat pe Domnul în legătură cu soția sa, căci era stearpă.” „Sfântul, binecuvântat fie El”: în sursă prescurtat (QB\"H)."]},{"v":22,"t":"Și copiii se îmbrânceau în pântecele ei ca niște oameni care se războiesc; și ea a zis: „Dacă așa este durerea nașterii, de ce să am copii?” Și s-a dus la casa de studiu a lui Sem cel Mare să ceară îndurare dinaintea Domnului."},{"v":23,"t":"Și Domnul i-a zis: „Două popoare sunt în pântecele tău și două împărății din pântecele tău se vor despărți; și o împărăție va fi mai tare decât cealaltă împărăție, iar cel mare va fi supus celui mic, dacă fiii celui mic vor păzi poruncile Torei.”","notes":["Rosen: „unul va fi mai puternic decât celălalt și cel mare va sluji celui tânăr.”"]},{"v":24,"t":"Și s-au împlinit cele două sute șaptezeci de zile ale sarcinii ei ca să nască, și iată, erau gemeni în pântecele ei.","notes":["„două sute șaptezeci de zile”: nouă luni."]},{"v":25,"t":"Și cel dintâi a ieșit roșcat cu totul, ca o manta de păr; și i-au pus numele Esau, pentru că se născuse cu totul desăvârșit, cu păr pe cap și barbă și dinți și măsele."},{"v":26,"t":"Și după aceea a ieșit fratele lui, cu mâna ținând călcâiul lui Esau, și i-a pus numele Iacov; și Isaac avea șaizeci de ani când i-a născut ea."},{"v":27,"t":"Și copiii au crescut, și Esau a fost un om vânător, care prindea păsări și fiare, un om care ieșea la câmp, ucigaș de suflete, căci el l-a ucis pe Nimrod și pe Enoh, fiul lui; iar Iacov a fost un om desăvârșit în faptele lui, care slujea în casa de studiu a lui Eber, cerând învățătură dinaintea Domnului."},{"v":28,"t":"Și Isaac îl iubea pe Esau, pentru că avea gura plină de vorbe înșelătoare; iar Rebeca îl iubea pe Iacov.","notes":["Rosen: „căci mânca din vânatul lui”; Targumul: „vorbe înșelătoare”."]},{"v":29,"t":"Și în ziua în care a murit Avraam, Iacov a fiert o mâncare de linte și s-a dus să-și mângâie tatăl; și Esau a venit de la câmp, și era istovit, căci cinci păcate săvârșise în ziua aceea: a slujit slujirii străine, a vărsat sânge nevinovat, a intrat la o fată logodită, a tăgăduit viața lumii care vine și a disprețuit dreptul de întâi născut."},{"v":30,"t":"Și a zis Esau către Iacov: „Dă-mi să gust, te rog, din mâncarea aceasta roșie, roșie, căci sunt istovit”; de aceea i s-a pus numele Edom."},{"v":31,"t":"Și a zis Iacov: „Vinde-mi astăzi, ca în ziua în care vei moșteni, dreptul tău de întâi născut.”","notes":["Rosen: „Vinde-mi, precum ziua de azi, dreptul tău de întâi-născut!”"]},{"v":32,"t":"Și a zis Esau: „Iată, eu mă duc să mor și nu voi mai trăi în altă lume; și la ce-mi folosește dreptul de întâi născut și partea din lumea despre care vorbești?”"},{"v":33,"t":"Și a zis Iacov: „Jură-mi, ca în ziua care va fi.” Și i-a jurat și i-a vândut lui Iacov dreptul lui de întâi născut."},{"v":34,"t":"Și Iacov i-a dat lui Esau pâine și mâncare de linte; și a mâncat și a băut și s-a ridicat și a plecat; și Esau a disprețuit dreptul de întâi născut și partea din lumea care vine."}]},{"num":26,"title":"Capitolul 26","verses":[{"v":1,"t":"Și a fost o foamete grea în țara Canaanului, în afară de foametea dintâi care fusese în zilele lui Avraam; și Isaac s-a dus la Abimelec, regele filistenilor, la Gherar.","notes":["Rosen: „Și a fost foamete în țară”; Targumul: „în țara Canaanului”."]},{"v":2,"t":"Și era în inima lui Isaac să coboare în Egipt („Mițrayim”); și i S-a arătat Domnul și a zis: „Nu coborî în Egipt; locuiește în țara pe care ți-o voi spune."},{"v":3,"t":"Locuiește ca străin în țara aceasta, și Cuvântul Meu va fi în ajutorul tău și te voi binecuvânta, căci ție și fiilor tăi îți voi da toate țările acestea, și voi împlini jurământul pe care l-am jurat lui Avraam, tatăl tău."},{"v":4,"t":"Și îi voi înmulți pe fiii tăi ca stelele cerurilor și le voi da fiilor tăi toate țările acestea, și se vor binecuvânta pentru fiii tăi toate popoarele pământului,"},{"v":5,"t":"pentru că Avraam a ascultat de Cuvântul Meu și a păzit păzirea Cuvântului Meu, poruncile Mele, legămintele Mele și învățăturile Mele.”"},{"v":6,"t":"Și Isaac a locuit în Gherar."},{"v":7,"t":"Și oamenii locului l-au întrebat despre soția lui, și el a zis: „Este sora mea”, căci se temea să-i spună „soția mea”, pentru că se gândea în inima lui: „Poate mă vor ucide oamenii locului din pricina Rebecăi, căci este frumoasă la înfățișare.”"},{"v":8,"t":"Și a fost, când i s-au înmulțit acolo zilele de locuire, Abimelec, regele filistenilor, a privit pe fereastră și a văzut: și iată, Isaac glumea cu Rebeca, soția lui."},{"v":9,"t":"Și Abimelec l-a chemat pe Isaac și a zis: „Iată, totuși ea este soția ta; și cum ai zis: «Este sora mea»?” Și i-a zis Isaac: „Pentru că am zis în inima mea: «Să nu fiu ucis din pricina ei».”"},{"v":10,"t":"Și a zis Abimelec: „Ce este aceasta ce ne-ai făcut? Puțin a lipsit să se culce regele, care este unic în popor, cu soția ta, și ai fi adus asupra noastră păcat.”","notes":["Rosen: „Puțin a lipsit ca unul din popor să se culce cu soția ta”; Targumul înțelege „unul din popor” ca „cel unic în popor”, adică regele."]},{"v":11,"t":"Și Abimelec a poruncit întregului popor, spunând: „Cine se va atinge cu rău de omul acesta și de soția lui va fi negreșit ucis.”"},{"v":12,"t":"Și Isaac a semănat pentru milostenie în țara aceea și a găsit în anul acela însutit față de ce socotise; și Domnul l-a binecuvântat.","notes":["„însutit față de ce socotise”: Targumul leagă ebraicul șeʿarim („măsuri”) de evaluarea recoltei."]},{"v":13,"t":"Și omul a ajuns mare și a mers crescând, până a ajuns foarte mare."},{"v":14,"t":"Și avea turme de oi, cirezi de boi și multă slujitorime; și filistenii l-au invidiat."},{"v":15,"t":"Și toate fântânile pe care le săpaseră slujitorii tatălui său în zilele lui Avraam, tatăl său, filistenii le-au astupat și le-au umplut cu țărână."},{"v":16,"t":"Și a zis Abimelec către Isaac: „Pleacă de la noi, căci ai ajuns mult mai tare decât noi în averi.”"},{"v":17,"t":"Și Isaac a plecat de acolo și și-a așezat tabăra în valea Gherarului și a locuit acolo."},{"v":18,"t":"Și Isaac a săpat din nou fântânile de apă pe care le săpaseră slujitorii tatălui său în zilele lui Avraam, tatăl său, și pe care filistenii le astupaseră după moartea lui Avraam; și le-a pus nume ca numele pe care le pusese tatăl său."},{"v":19,"t":"Și slujitorii lui Isaac au săpat pe malul văii și au găsit acolo o fântână de apă izvorâtoare."},{"v":20,"t":"Și păstorii din Gherar s-au certat cu păstorii lui Isaac, spunând: „A noastră este apa!” Și a fost voie din cer, și a secat; și atunci i-au dat-o înapoi lui Isaac, și a izvorât; și a pus numele fântânii Esek, căci s-au îndeletnicit cu ea împreună cu el.","notes":["„s-au îndeletnicit” (itʿasaqu): joc de cuvinte cu numele Esek."]},{"v":21,"t":"Și au săpat o altă fântână și s-au certat și pentru ea, și a secat și n-a mai izvorât; și i-a pus numele Sitna."},{"v":22,"t":"Și s-a mutat de acolo și a săpat o altă fântână, și nu s-au certat pentru ea ca pentru cele dintâi; și i-a pus numele Rewaḥta și a zis: „Căci acum Domnul ne-a făcut loc larg și ne va face roditori în țară.”","notes":["Rosen: „i-a pus numele Rehobot”; Targumul are forma aramaică Rewaḥta („loc larg”)."]},{"v":23,"t":"Și a urcat de acolo la Beer-Șeba."},{"v":24,"t":"Și i S-a arătat Domnul în noaptea aceea și a zis: „Eu sunt Dumnezeul lui Avraam, tatăl tău; nu te teme, căci Cuvântul Meu este în ajutorul tău, și te voi binecuvânta și îi voi înmulți pe fiii tăi pentru meritele lui Avraam, slujitorul Meu.”"},{"v":25,"t":"Și a construit acolo un altar și s-a rugat în Numele Domnului și și-a întins acolo cortul; și slujitorii lui Isaac au săpat acolo o fântână."},{"v":26,"t":"Și când Isaac a ieșit din Gherar, fântânile lor au secat și pomii lor n-au mai făcut roade; și și-au dat seama că pentru că l-au alungat li s-au întâmplat toate acestea. Și Abimelec s-a dus la el din Gherar și s-a întărit cu prietenii lui ca să meargă cu el, și Picol, căpetenia oștirii lui.","notes":["Rosen: „Iar Abimelec a mers la el din Gherar cu un grup de apropiați și cu Picol, comandantul oștirii sale.”"]},{"v":27,"t":"Și le-a zis Isaac: „De ce ați venit la mine, ca să mă rog pentru voi, când voi m-ați urât și m-ați alungat de la voi?”"},{"v":28,"t":"Și au zis: „Am văzut bine că Cuvântul Domnului a fost în ajutorul tău, căci prin meritul tău am avut tot binele; iar când ai ieșit din țara noastră, fântânile noastre au secat și pomii n-au mai făcut roade. Și am zis: «Să-l aducem înapoi la noi», și să se întărească acum jurământul care a fost între noi, și de acum să fie între noi și tine, și să încheiem un legământ cu tine,"},{"v":29,"t":"că nu ne vei face rău, așa cum nu ne-am atins de tine cu rău și așa cum ți-am făcut numai bine și te-am lăsat să pleci în pace; tu ești acum binecuvântatul Domnului.”"},{"v":30,"t":"Și le-a făcut un ospăț, și au mâncat și au băut."},{"v":31,"t":"Și s-au sculat devreme dimineața și au jurat unul altuia; și a tăiat frâul măgarului său și le-a dat o bucată ca mărturie; și Isaac s-a rugat pentru ei, și au fost ușurați; și Isaac i-a însoțit, și au plecat de la el în pace.","notes":["„a tăiat frâul măgarului său”: sursa nu numește subiectul; redat după sursă."]},{"v":32,"t":"Și a fost în ziua aceea, și au venit slujitorii lui Isaac și i-au povestit despre fântâna pe care o săpaseră și i-au zis: „Am găsit apă.”"},{"v":33,"t":"Și a numit-o Șiba; de aceea numele cetății este Beer-Șeba până în ziua aceasta."},{"v":34,"t":"Și Esau avea patruzeci de ani și a luat de soție pe Iudit, fiica lui Beeri hititul, și pe Basmat, fiica lui Elon hititul."},{"v":35,"t":"Și ele se închinau în slujirea străină și căutau să se răzvrătească prin faptele lor rele împotriva lui Isaac și a Rebecăi.","notes":["Rosen: „Și ele au fost motiv de amărăciune pentru Isaac și Rebeca.”"]}]},{"num":27,"title":"Capitolul 27","verses":[{"v":1,"t":"Și a fost, când Isaac îmbătrânise și i se slăbiseră ochii de la vedere — căci, atunci când l-a legat tatăl său, el a privit la Tronul slavei, și de atunci au început ochii lui să slăbească —, l-a chemat pe Esau, fiul său cel mare, la paisprezece Nisan, și i-a zis: „Fiul meu, iată, în noaptea aceasta cei de sus Îl laudă pe Stăpânul lumii, și vistieriile de rouă se deschid în ea.” Și el i-a zis: „Iată-mă.”","notes":["„paisprezece Nisan”: ajunul de Pesah; „vistieriile de rouă”: după tradiție, în noaptea de Pesah se judecă lumea în privința rouăi."]},{"v":2,"t":"Și a zis: „Iată acum, am îmbătrânit; nu știu ziua morții mele."},{"v":3,"t":"Și acum, ia-ți, te rog, armele, tolba și arcul și ieși la câmp și vânează-mi vânat."},{"v":4,"t":"Și fă-mi mâncăruri cum îmi plac și adu-mi, și voi mânca, ca să te binecuvânteze sufletul meu înainte să mor.”"},{"v":5,"t":"Și Rebeca a auzit prin duhul sfințeniei când vorbea Isaac cu Esau, fiul lui; și Esau s-a dus la câmp să vâneze vânat ca să-l aducă."},{"v":6,"t":"Și Rebeca a zis către Iacov, fiul ei, spunând: „Iată, în noaptea aceasta cei de sus Îl laudă pe Stăpânul lumii, și vistieriile de rouă se deschid în ea; și l-am auzit pe tatăl tău vorbind cu Esau, fratele tău, spunând:"},{"v":7,"t":"«Adu-mi vânat și fă-mi mâncăruri, și voi mânca și te voi binecuvânta înaintea Domnului înainte să mor.»"},{"v":8,"t":"Și acum, fiul meu, ascultă-mă în ceea ce îți poruncesc."},{"v":9,"t":"Du-te, te rog, la turmă și ia-mi de acolo doi iezi grași: unul pentru jertfa de Pesah și unul pentru jertfa sărbătorii; și îi voi face mâncăruri pentru tatăl tău, cum îi plac.","notes":["Rosen: „doi iezi buni”; Targumul îi leagă de jertfa de Pesah și de jertfa sărbătorii (ḥagiga)."]},{"v":10,"t":"Și le vei duce tatălui tău, și va mânca, ca să te binecuvânteze înainte de moartea lui.”"},{"v":11,"t":"Și pentru că Iacov se temea de păcat, se temea ca nu cumva tatăl său să-l blesteme, a zis: „Iată, Esau, fratele meu, este un om păros, iar eu sunt un om neted."},{"v":12,"t":"Poate tata mă va pipăi, și voi fi în ochii lui ca unul care își bate joc de el, și voi aduce asupra mea blesteme, și nu binecuvântări.”"},{"v":13,"t":"Și i-a zis mama lui: „Dacă te va binecuvânta cu binecuvântări, să vină asupra ta și asupra fiilor tăi; iar dacă te va blestema cu blesteme, să vină asupra mea și asupra sufletului meu. Numai ascultă-mă și du-te, ia-mi-i.”"},{"v":14,"t":"Și s-a dus și i-a luat și i-a adus mamei lui, și mama lui a făcut mâncăruri cum îi plăceau tatălui lui."},{"v":15,"t":"Și Rebeca a luat hainele de preț ale lui Esau, fiul ei cel mare, care fuseseră ale lui Adam cel dintâi — iar în ziua aceea Esau nu le îmbrăcase, și rămăseseră la ea în casă —, și l-a îmbrăcat pe Iacov, fiul ei cel mic.","notes":["„care fuseseră ale lui Adam cel dintâi”: după tradiția agadică, hainele de piele din 3:21, trecute la Nimrod și luate de Esau."]},{"v":16,"t":"Și pieile iezilor le-a pus pe mâinile lui și pe partea netedă a gâtului lui."},{"v":17,"t":"Și a dat mâncărurile și pâinea pe care le făcuse în mâna lui Iacov, fiul ei."},{"v":18,"t":"Și a intrat la tatăl său și a zis: „Tată!” Și el a zis: „Iată-mă; cine ești tu, fiul meu?”"},{"v":19,"t":"Și a zis Iacov către tatăl său: „Eu sunt Esau, întâiul tău născut; am făcut cum mi-ai vorbit. Ridică-te, te rog, așază-te și mănâncă din vânatul meu, ca să mă binecuvânteze sufletul tău.”"},{"v":20,"t":"Și a zis Isaac către fiul său: „Cum de te-ai grăbit să găsești, fiul meu?” Și el a zis: „Pentru că Domnul, Dumnezeul tău, mi l-a pregătit înainte.”"},{"v":21,"t":"Și a zis Isaac către Iacov: „Apropie-te, te rog, să te pipăi, fiul meu: ești tu fiul meu Esau sau nu?”"},{"v":22,"t":"Și Iacov s-a apropiat de Isaac, tatăl său, și el l-a pipăit și a zis: „Glasul acesta este glasul lui Iacov, dar pipăitul mâinilor lui este ca pipăitul mâinilor lui Esau.”"},{"v":23,"t":"Și nu l-a recunoscut, căci mâinile lui erau ca mâinile lui Esau, fratele lui, păroase; și l-a binecuvântat."},{"v":24,"t":"Și a zis: „Tu ești fiul meu Esau?” Și el a zis: „Eu sunt.”"},{"v":25,"t":"Și a zis: „Apropie-mi, ca să mănânc din vânatul fiului meu, ca să te binecuvânteze sufletul meu.” Și i-a apropiat, și a mâncat. Și nu avea vin la el, dar i s-a înfățișat un înger și a adus din vinul care fusese păstrat în strugurii lui din zilele începutului lumii și l-a dat în mâna lui Iacov, iar Iacov i l-a dus tatălui său, și a băut."},{"v":26,"t":"Și Isaac, tatăl său, i-a zis: „Apropie-te, te rog, și sărută-mă, fiul meu.”"},{"v":27,"t":"Și s-a apropiat și l-a sărutat, și el a mirosit mireasma hainelor lui și l-a binecuvântat și a zis: „Vedeți, mireasma fiului meu este ca mireasma tămâiei de mirodenii care avea să fie adusă pe muntele Casei Sanctuarului, care este numit «câmp», pe care l-a binecuvântat Domnul și pe care l-a ales ca să-Și sălășluiască acolo Șechina.","notes":["Rosen: „Uite, aroma fiului meu este ca aroma unui câmp pe care l-a binecuvântat Domnul.” „Casa Sanctuarului” = Templul."]},{"v":28,"t":"Și să-ți dea Cuvântul Domnului din binele rourilor care coboară din ceruri și din binele izvoarelor care urcă și fac să crească vegetația pământului de jos, și belșug de grâne și vin."},{"v":29,"t":"Să te slujească popoarele, toți fiii lui Esau, și să se plece înaintea ta împărățiile, toți fiii Cheturei; mare și stăpân să fii peste fratele tău, și să se grăbească să te întrebe de sănătate fiii mamei tale. Cei care te blestemă, fiule, să fie blestemați ca Balaam, fiul lui Beor, iar cei care te binecuvântează să fie binecuvântați ca Moise profetul, cărturarul lui Israel.”","notes":["Rosen: „Popoare te vor sluji și neamuri ți se vor prosterna; stăpân le vei fi fraților tăi și fiii mamei tale ți se vor prosterna”."]},{"v":30,"t":"Și a fost, când a terminat Isaac de binecuvântat pe Iacov, și abia ieșise Iacov, ca două foi de ușă, de la Isaac, tatăl său, iar Esau, fratele lui, a venit de la vânătoarea lui.","notes":["„ca două foi de ușă” (ki-tartein ṭefuḥin): sensul imaginii este nesigur (probabil: unul ieșea pe când celălalt intra); redat literal."]},{"v":31,"t":"Dar Cuvântul Domnului a oprit de la el vânatul curat, și a găsit un câine și l-a ucis; și a făcut și el din el mâncăruri și le-a adus tatălui său și a zis tatălui său: „Să se ridice tata și să mănânce din vânatul fiului său, ca să mă binecuvânteze sufletul tău.”"},{"v":32,"t":"Și i-a zis Isaac, tatăl său, și i-a zis: „Cine ești tu?” Și el a zis: „Eu sunt fiul tău, întâiul tău născut, Esau.”"},{"v":33,"t":"Și Isaac s-a cutremurat cu mare cutremur când a auzit glasul lui Esau, și mirosul mâncării lui a intrat în nările lui ca mirosul arderii Gheenei; și a zis: „Cine este, deci, acela care a vânat vânat și mi l-a adus, și am mâncat din tot ce a adus înainte să intri tu, și l-am binecuvântat? Și chiar așa, binecuvântat să fie!”","notes":["Rosen: „Atunci cine?... Unde e cel care a vânat vânat”; Targumul citește ebraicul ʾefo („deci”)."]},{"v":34,"t":"Când a auzit Esau cuvintele tatălui său, a strigat cu un strigăt mare și amar peste măsură și a zis tatălui său: „Binecuvântează-mă și pe mine, tată!”"},{"v":35,"t":"Și a zis: „A venit fratele tău cu înțelepciune și a primit de la mine binecuvântarea ta.”"},{"v":36,"t":"Și a zis: „Cu adevărat i s-a pus numele Iacov, căci m-a înșelat de două ori: dreptul meu de întâi născut l-a luat, și iată, acum a primit binecuvântarea mea.” Și a zis: „Oare nu mi-ai lăsat o binecuvântare?”"},{"v":37,"t":"Și Isaac a răspuns și a zis lui Esau: „Iată, l-am rânduit stăpân peste tine și pe toți frații lui i-am pus înaintea lui ca robi, și cu grâne și vin l-am sprijinit; și tu du-te și vei fi alungat de la mine; ce să-ți fac, fiul meu?”"},{"v":38,"t":"Și a zis Esau către tatăl său: „Oare ai numai o binecuvântare, tată? Binecuvântează-mă și pe mine, tată!” Și Esau și-a ridicat glasul și a plâns."},{"v":39,"t":"Și Isaac a răspuns și a zis lui Esau: „Iată, în binele roadelor pământului va fi locuința ta, și din roua cerurilor de sus."},{"v":40,"t":"Și pe sabia ta te vei sprijini; vei intra în orice loc, plecându-te și venind, și fratelui tău îi vei fi supus. Și va fi, când fiii lui se vor nelegiui și vor părăsi păzirea poruncilor Torei, atunci vei rupe jugul robiei lui de pe gâtul tău.”","notes":["Rosen: „Prin sabia ta vei trăi și pe fratele tău îl vei sluji; dar va fi, când vei fi îndurerat, vei putea să-i îndepărtezi jugul de pe grumazul tău.” „plecându-te și venind” (u-markhikh ve-tai): sensul cuvintelor din sursă este nesigur; redat literal."]},{"v":41,"t":"Și Esau a păstrat ură în inima lui împotriva lui Iacov, fratele lui, pentru rânduiala binecuvântărilor cu care îl binecuvântase tatăl lui; și Esau a zis în inima lui: „Nu voi face cum a făcut Cain, care l-a ucis pe Abel în viața tatălui său, iar tatăl său s-a întors și l-a născut pe Set; ci voi aștepta până vor veni zilele doliului după moartea tatălui meu, și atunci îl voi ucide pe Iacov, fratele meu, și voi fi găsit ucigaș și moștenitor.”"},{"v":42,"t":"Și i s-au vestit Rebecăi, prin duhul sfințeniei, cuvintele lui Esau, fiul ei cel mare, care plănuia în inima lui să-l ucidă pe Iacov; și a trimis și l-a chemat pe Iacov, fiul ei cel mic, și i-a zis: „Iată, Esau, fratele tău, îți întinde o cursă și uneltește împotriva ta ca să te ucidă."},{"v":43,"t":"Și acum, fiul meu, ascultă-mă: ridică-te, fugi și scapă-ți viața și du-te la Laban, fratele meu, la Haran."},{"v":44,"t":"Și locuiește cu el câteva zile, până se va potoli furia fratelui tău,"},{"v":45,"t":"până se va potoli mânia fratelui tău împotriva ta și va uita ce i-ai făcut; și voi trimite și te voi aduce de acolo. De ce să fiu lipsită de amândoi într-o singură zi, când tu ai fi ucis și el ar fi alungat, așa cum a fost lipsită Eva de Abel, pe care l-a ucis Cain, și amândoi au fost alungați dinaintea lui Adam și a Evei, în toate zilele vieții lui Adam și ale Evei?”"},{"v":46,"t":"Și a zis Rebeca către Isaac: „Mi s-a urât viața din pricina fiicelor lui Het; dacă Iacov ia o soție nelegiuită dintre fiicele lui Het, ca acestea, dintre fiicele poporului țării, la ce-mi mai este viața?”"}]},{"num":28,"title":"Capitolul 28","verses":[{"v":1,"t":"Și Isaac l-a chemat pe Iacov și l-a binecuvântat și i-a poruncit și i-a zis: „Să nu iei soție dintre fiicele canaaniților."},{"v":2,"t":"Ridică-te, du-te la Padan-Aram, la casa lui Betuel, tatăl mamei tale, și ia-ți de acolo o soție dintre fiicele lui Laban, fratele mamei tale."},{"v":3,"t":"Și Dumnezeul Atotputernic să te binecuvânteze cu averi multe și să te facă roditor și să te înmulțească în douăsprezece seminții, și să fii vrednic de adunarea fiilor Sanhedrinului, al căror număr este șaptezeci, ca numărul popoarelor.","notes":["Rosen: „Și Dumnezeul Atotputernic să te binecuvânteze și să te facă roditor și să te înmulțească”; Targumul leagă „adunare de popoare” de cele douăsprezece seminții și de Sanhedrin."]},{"v":4,"t":"Și să-ți dea binecuvântarea lui Avraam, ție și fiilor tăi cu tine, și să te aducă înapoi ca să moștenești țara în care locuiești ca străin, pe care Domnul a dat-o lui Avraam.”"},{"v":5,"t":"Și Isaac l-a trimis pe Iacov, și s-a dus la Padan-Aram, la Laban, fiul lui Betuel arameul, fratele Rebecăi, mama lui Iacov și a lui Esau."},{"v":6,"t":"Și Esau a văzut că Isaac îl binecuvântase pe Iacov și îl trimisese la Padan-Aram ca să-și ia de acolo o soție, când l-a binecuvântat și i-a poruncit, spunând: „Să nu iei soție dintre fiicele canaaniților”,"},{"v":7,"t":"și că Iacov ascultase de cuvântul tatălui său și de cuvântul mamei sale și se dusese la Padan-Aram."},{"v":8,"t":"Și Esau a văzut că fiicele canaaniților erau rele înaintea lui Isaac, tatăl său."},{"v":9,"t":"Și Esau s-a dus la Ismael și a luat-o pe Mahalat — aceasta este Basmat —, fiica lui Ismael, fiul lui Avraam, sora lui Nebaiot după mamă, pe lângă soțiile lui, ca să-i fie soție.","notes":["Mahalat – Basmat: Targumul o identifică pe Mahalat cu Basmat (vezi 36:3)."]},{"v":10,"t":"A ieșit: cinci minuni i s-au făcut lui Iacov când a ieșit din Beer-Șeba. Minunea dintâi: s-au scurtat ceasurile zilei, și soarele a apus înainte de vreme, pentru că Cuvântul dorea să vorbească cu el. Minunea a doua: cele patru pietre pe care le pusese la căpătâi le-a găsit dimineața o singură piatră. Minunea a treia: piatra pentru care se adunau toate turmele ca s-o rostogolească de pe gura fântânii, el a rostogolit-o cu un singur braț. Minunea a patra: fântâna a dat pe dinafară și apa a urcat înaintea lui și a dat pe dinafară în toate zilele cât a fost în Haran. Minunea a cincea: pământul s-a strâns înaintea lui, și în aceeași zi în care a ieșit a ajuns în Haran.","notes":["Ediția sursă începe versetul cu cuvântul ebraic al Torei („A ieșit”), urmat de textul aramaic. Rosen: „Iacov a ieșit din Beer Șeba și a mers către Haran.” „Cuvântul” (dibbera): vorbirea divină."]},{"v":11,"t":"Și s-a rugat în locul Casei Sanctuarului și a înnoptat acolo, căci apusese soarele; și a luat patru dintre pietrele locului sfânt și le-a pus la căpătâi și s-a culcat în locul acela."},{"v":12,"t":"Și a visat, și iată, o scară înfiptă în pământ, și vârful ei ajungea până la înălțimea cerurilor; și iată, cei doi îngeri care se duseseră la Sodoma și fuseseră alungați din despărțitura lor, pentru că descoperiseră tainele Stăpânului lumii, umblau alungați până când a ieșit Iacov din casa tatălui său; și ei l-au însoțit cu bunătate până la Betel, și în ziua aceea urcau la cerurile de sus și au răspuns și au zis: „Veniți, vedeți-l pe Iacov cel evlavios, al cărui chip este întipărit în Tronul slavei, pe care doreați să-l vedeți.” Atunci ceilalți îngeri sfinți ai Domnului coborau ca să privească la el.","notes":["Rosen: „și iată, îngeri ai lui Dumnezeu urcau și coborau pe ea.” Îngerii alungați pentru că „descoperiseră tainele”: cf. 19:13 („Domnul ne-a trimis să-l nimicim”, spus ca de la ei înșiși)."]},{"v":13,"t":"Și iată, slava Domnului stătea deasupra lui și i-a zis: „Eu sunt Domnul, Dumnezeul lui Avraam, tatăl tău, și Dumnezeul lui Isaac; țara pe care stai culcat ți-o voi da ție și fiilor tăi."},{"v":14,"t":"Și fiii tăi vor fi mulți ca țărâna pământului, și te vei întări spre apus și spre răsărit, spre miazănoapte și spre miazăzi; și se vor binecuvânta pentru meritele tale toate neamurile pământului, și pentru meritele fiilor tăi."},{"v":15,"t":"Și iată, Cuvântul Meu este în ajutorul tău, și te voi păzi în orice loc în care vei merge și te voi aduce înapoi în țara aceasta, căci nu te voi părăsi până nu voi face ce ți-am vorbit.”"},{"v":16,"t":"Și Iacov s-a trezit din somnul lui și a zis: „Cu adevărat slava Șechinei Domnului sălășluiește în locul acesta, și eu nu știam.”"},{"v":17,"t":"Și s-a temut și a zis: „Cât de înfricoșător și de lăudat este locul acesta! Acesta nu este un loc obișnuit, ci o Casă a Sanctuarului pentru Numele Domnului, și acesta este potrivit pentru rugăciune, așezat drept în fața porții cerurilor, întemeiat sub Tronul slavei.”","notes":["Rosen: „Nu-i altceva decât casa lui Dumnezeu și aceasta este poarta cerurilor!”"]},{"v":18,"t":"Și Iacov s-a sculat devreme dimineața și a luat piatra pe care o pusese la căpătâi și a pus-o stâlp și a turnat untdelemn pe vârful ei.","notes":["Rosen: „stelă”."]},{"v":19,"t":"Și a numit locul acela Betel, dar Luz era numele cetății mai înainte."},{"v":20,"t":"Și Iacov a făcut un jurământ, spunând: „Dacă va fi Cuvântul Domnului în ajutorul meu și mă va păzi de vărsarea sângelui nevinovat, de slujirea străină și de dezgolirea goliciunii, pe drumul acesta pe care merg, și îmi va da pâine de mâncat și haină de îmbrăcat,"},{"v":21,"t":"și mă voi întoarce în pace la casa tatălui meu, atunci Domnul îmi va fi Dumnezeu."},{"v":22,"t":"Și piatra aceasta pe care am pus-o stâlp va fi așezată în Casa Sanctuarului Domnului, și generațiile se vor închina pe ea Numelui Domnului; și din tot ce îmi vei da, una din zece o voi pune deoparte înaintea Ta.”"}]},{"num":29,"title":"Capitolul 29","verses":[{"v":1,"t":"Și Iacov și-a ridicat cu ușurință picioarele ca să meargă și s-a dus în țara fiilor răsăritului."},{"v":2,"t":"Și a privit, și iată, o fântână în câmp, și iată, acolo erau trei turme de oi culcate lângă ea, căci din fântâna aceea adăpau turmele; și piatra cea mare era pusă pe gura fântânii."},{"v":3,"t":"Și se adunau acolo toate turmele și rostogoleau piatra de pe gura fântânii și adăpau oile și puneau iarăși piatra pe gura fântânii, la locul ei."},{"v":4,"t":"Și Iacov le-a zis: „Frații mei, de unde sunteți?” Și au zis: „Din Haran suntem.”"},{"v":5,"t":"Și le-a zis: „Îl cunoașteți pe Laban, fiul lui Nahor?” Și au zis: „Îl cunoaștem.”"},{"v":6,"t":"Și le-a zis: „Este sănătos?” Și au zis: „Este sănătos; și iată, Rahela, fiica lui, vine cu oile.”"},{"v":7,"t":"Și a zis: „Iată, mai este mult din zi, nu este vremea să se adune vitele; adăpați oile și duceți-vă de le pășteți.”"},{"v":8,"t":"Și au zis: „Nu putem, până nu se adună toate turmele și rostogolesc piatra de pe gura fântânii, și atunci adăpăm oile.”"},{"v":9,"t":"Pe când el vorbea cu ei, Rahela a venit cu oile tatălui ei, căci ea era păstoriță în vremea aceea; pentru că venise urgia Domnului asupra oilor lui Laban și nu rămăseseră din ele decât puține, și el își alungase păstorii, iar pe cele care rămăseseră le-a pus în grija Rahelei, fiica lui."},{"v":10,"t":"Și a fost, când Iacov a văzut-o pe Rahela, fiica lui Laban, fratele mamei lui, Iacov s-a apropiat și a rostogolit piatra cu un singur braț de pe gura fântânii, și fântâna a dat pe dinafară și apa a urcat înaintea lui; și a adăpat oile lui Laban, fratele mamei lui; și a dat pe dinafară douăzeci de ani."},{"v":11,"t":"Și Iacov a sărutat-o pe Rahela și și-a ridicat glasul și a plâns."},{"v":12,"t":"Și Iacov i-a spus Rahelei că venise să se înrudească cu tatăl ei și să ia una dintre fiicele lui. A răspuns Rahela și a zis: „Nu-ți este cu putință să locuiești cu el, căci este un om înșelător.” I-a zis Iacov: „Eu sunt mai înșelător și mai înțelept decât el, și nu are putere să-mi facă rău, căci Cuvântul Domnului este în ajutorul meu.” Și când a aflat că el este fiul Rebecăi, a alergat și i-a spus tatălui ei."},{"v":13,"t":"Și a fost, când a auzit Laban vestea vitejiei și a evlaviei lui Iacov, fiul surorii lui, cum luase dreptul de întâi născut și rânduiala binecuvântărilor din mâna fratelui său, și cum i Se descoperise Domnul la Betel, și cum rostogolise piatra, și cum fântâna dăduse pe dinafară și urcase înaintea lui, a alergat în întâmpinarea lui și l-a îmbrățișat și l-a sărutat și l-a adus în casa lui; și el i-a povestit lui Laban toate aceste lucruri."},{"v":14,"t":"Și Laban i-a zis: „Cu adevărat ești ruda mea și îmi semeni.” Și a locuit cu el o lună de zile."},{"v":15,"t":"Și a zis Laban către Iacov: „Pentru că ești fratele meu, se cuvine oare să mă slujești pe degeaba? Spune-mi care va fi plata ta.”"},{"v":16,"t":"Și Laban avea două fiice: numele celei mari era Lea, iar numele celei mici, Rahela."},{"v":17,"t":"Și ochii Leei erau slăbiți, pentru că plângea și cerea dinaintea Domnului să nu i-l rânduiască pe Esau cel nelegiuit; iar Rahela era frumoasă la chip și frumoasă la înfățișare.","notes":["Rosen: „Și ochii Leei erau plăpânzi, iar Rahela era frumoasă la înfățișare și frumoasă la privit.”"]},{"v":18,"t":"Și Iacov a iubit-o pe Rahela și a zis: „Te voi sluji șapte ani pentru Rahela, fiica ta cea mică.”"},{"v":19,"t":"Și a zis Laban: „Este mai bine să ți-o dau ție decât să o dau altui bărbat; locuiește cu mine.”"},{"v":20,"t":"Și Iacov a slujit pentru Rahela șapte ani, și i s-au părut în ochii lui ca niște zile puține, pentru că o iubea."},{"v":21,"t":"Și a zis Iacov către Laban: „Dă-mi soția, căci s-au împlinit zilele slujbei mele, și voi intra la ea.”"},{"v":22,"t":"Și Laban i-a adunat pe toți oamenii locului și le-a făcut un ospăț; și le-a zis: „Iată, de șapte ani, de când a venit Iacov la noi, fântânile n-au lipsit și adăpătorile noastre s-au înmulțit; și acum, veniți să ne sfătuim împotriva lui un sfat înșelător, ca să rămână la noi.” Și i-au făcut un sfat înșelător, ca să i-o dea pe Lea în locul Rahelei."},{"v":23,"t":"Și a fost seara, și a luat-o pe Lea, fiica lui, și a adus-o la el, și el a intrat la ea."},{"v":24,"t":"Și Laban i-a dat-o pe Zilpa, fiica lui, pe care i-o născuse concubina lui, și a dat-o Leei, fiica lui, ca roabă."},{"v":25,"t":"Și a fost în zorii dimineții, s-a uitat la ea, și iată, era Lea; căci toată noaptea crezuse că este Rahela, pentru că Rahela îi spusese toate semnele pe care i le dăduse Iacov. Și când a văzut aceasta, i-a zis lui Laban: „Ce este aceasta ce mi-ai făcut? Oare nu pentru Rahela am slujit la tine? De ce m-ai înșelat?”"},{"v":26,"t":"Și a zis Laban: „Nu se face așa în locurile noastre, să se dea cea mică înaintea celei mari."},{"v":27,"t":"Împlinește acum cele șapte zile de ospăț ale acesteia, și îți vom da și pe aceasta, pentru slujba pe care o vei sluji la mine încă șapte ani.”"},{"v":28,"t":"Și Iacov a făcut așa și a împlinit cele șapte zile de ospăț ale Leei, și el i-a dat-o pe Rahela, fiica lui, de soție."},{"v":29,"t":"Și Laban i-a dat Rahelei, fiica lui, pe Bilha, fiica lui, pe care i-o născuse concubina lui, și i-a dat-o ca roabă."},{"v":30,"t":"Și a intrat și la Rahela, și a iubit-o pe Rahela mai mult decât pe Lea; și a slujit la el pentru ea încă șapte ani."},{"v":31,"t":"Și s-a descoperit înaintea Domnului că Lea nu era iubită în ochii lui Iacov, și a zis prin Cuvântul Său să-i dea fii; iar Rahela era stearpă."},{"v":32,"t":"Și Lea a rămas însărcinată și a născut un fiu și i-a pus numele Ruben, căci a zis: „S-a descoperit înaintea Domnului umilința mea; căci acum mă va iubi bărbatul meu. Și așa cum s-a descoperit înaintea Domnului umilința mea, așa va fi descoperită înaintea Lui umilința fiilor mei când vor fi robiți în țara egiptenilor.”","notes":["Targumul leagă numele Ruben de raʾah („a văzut”), Simeon de șamaʿ („a auzit”), Levi de lawah („a se alipi”), Iuda de hodah („a mulțumi”)."]},{"v":33,"t":"Și a rămas din nou însărcinată și a născut un fiu și a zis: „Pentru că s-a auzit înaintea Domnului că sunt urâtă, mi l-a dat și pe acesta; și tot așa se va auzi înaintea Lui glasul fiilor mei când vor fi robiți în Egipt („Mițrayim”).” Și i-a pus numele Simeon."},{"v":34,"t":"Și a rămas din nou însărcinată și a născut un fiu și a zis: „De data aceasta se va alipi de mine bărbatul meu, căci i-am născut trei fii; și tot așa fiii lui vor fi alipiți ca să slujească înaintea Domnului.” De aceea i-a pus numele Levi."},{"v":35,"t":"Și a rămas din nou însărcinată și a născut un fiu și a zis: „De data aceasta voi mulțumi înaintea Domnului, căci din fiul acesta vor ieși regi, și din el va ieși regele David, care va mulțumi înaintea Domnului.” De aceea i-a pus numele Iuda; și a încetat să nască."}]},{"num":30,"title":"Capitolul 30","verses":[{"v":1,"t":"Și Rahela a văzut că nu-i născuse lui Iacov copii, și Rahela a fost geloasă pe sora ei și i-a zis lui Iacov: „Roagă-te înaintea Domnului să-mi dea fii; iar dacă nu, sunt socotită ca o moartă.”"},{"v":2,"t":"Și mânia lui Iacov s-a aprins împotriva Rahelei, și a zis: „În loc să-mi ceri mie, cere dinaintea Domnului, căci de la El sunt fiii, și El a oprit de la tine rodul pântecelui.”"},{"v":3,"t":"Și ea a zis: „Iată, roaba mea Bilha: intră la ea, și ea va naște, iar eu voi crește copiii și voi fi zidită și eu prin ea.”"},{"v":4,"t":"Și i-a eliberat-o pe Bilha, roaba ei, și i-a dat-o de soție; și Iacov a intrat la ea."},{"v":5,"t":"Și Bilha a rămas însărcinată și i-a născut lui Iacov un fiu."},{"v":6,"t":"Și a zis Rahela: „Domnul m-a judecat în îndurările Lui cele bune și chiar a auzit glasul rugăciunii mele și mi-a dat un fiu; și tot așa va judeca prin mâna lui Samson, fiul lui Manoah, care este din seminția lui, și va da în mâna lui poporul filistenilor.” De aceea i-a pus numele Dan.","notes":["Targumul leagă numele Dan de dan („a judecat”), Neftali (30:8) de „zbatere”, Gad (30:11) de „noroc”, Așer (30:13) de „laudă”, Isahar (30:18) de sakhar („plată”), Zabulon (30:20) de „dar”."]},{"v":7,"t":"Și a rămas din nou însărcinată și Bilha, roaba Rahelei, i-a născut lui Iacov un al doilea fiu."},{"v":8,"t":"Și a zis Rahela: „M-am zbătut înaintea Domnului în rugăciune, iar El mi-a primit cererea, ca să am un fiu ca sora mea, și chiar mi-a dat doi; și tot așa fiii lui vor fi răscumpărați din mâna dușmanilor lor când se vor zbate în rugăciune înaintea Domnului.” Și i-a pus numele Neftali."},{"v":9,"t":"Și Lea a văzut că încetase să nască, și a eliberat-o pe Zilpa, roaba ei, și i-a dat-o lui Iacov de soție."},{"v":10,"t":"Și Zilpa, roaba Leei, i-a născut lui Iacov un fiu."},{"v":11,"t":"Și a zis Lea: „A venit noroc bun; și fiii lui vor moșteni moștenirea lor cei dintâi, dincolo de Iordan.” Și i-a pus numele Gad."},{"v":12,"t":"Și Zilpa, roaba Leei, i-a născut lui Iacov un al doilea fiu."},{"v":13,"t":"Și a zis Lea: „Laudă am avut, căci m-au lăudat fiicele lui Israel; și tot așa fiii lui vor aduce laudă înaintea Domnului pentru roadele bune ale țării lor.” Și i-a pus numele Așer."},{"v":14,"t":"Și Ruben s-a dus în zilele lui Sivan, la vremea secerișului grâului, și a găsit mandragore în câmp și le-a adus Leei, mama lui; și a zis Rahela către Lea: „Dă-mi, te rog, din mandragorele fiului tău.”"},{"v":15,"t":"Și ea i-a zis: „Puțin lucru este că mi-ai luat bărbatul, și vrei să iei și mandragorele fiului meu?” Și a zis Rahela: „De aceea să se culce cu tine în noaptea aceasta, în schimbul mandragorelor fiului tău.”"},{"v":16,"t":"Și Iacov a venit de la câmp seara, și Lea a auzit glasul răgetului măgarului și a știut că venise Iacov; și Lea a ieșit în întâmpinarea lui și a zis: „La mine să intri, căci te-am tocmit cu mandragorele fiului meu de la Rahela, sora mea.” Și s-a culcat cu ea în noaptea aceea."},{"v":17,"t":"Și Domnul a primit rugăciunea Leei, și ea a rămas însărcinată și i-a născut lui Iacov un al cincilea fiu."},{"v":18,"t":"Și a zis Lea: „Domnul mi-a dat plata mea, pentru că am dat-o pe roaba mea bărbatului meu; și tot așa fiii lui vor primi plată bună pentru că se îndeletnicesc cu Tora.” Și i-a pus numele Isahar."},{"v":19,"t":"Și Lea a rămas din nou însărcinată și i-a născut lui Iacov un al șaselea fiu."},{"v":20,"t":"Și a zis Lea: „Domnul m-a înzestrat cu daruri bune de fii; de data aceasta locuința bărbatului meu va fi cu mine, căci i-am născut șase fii; și tot așa fiii lui vor primi o parte bună.” Și i-a pus numele Zabulon."},{"v":21,"t":"Și după aceea a născut o fiică și i-a pus numele Dina, căci a zis: „Este o judecată dinaintea Domnului să fie din mine jumătate dintre seminții; dar din Rahela, sora mea, vor ieși două seminții, așa cum au ieșit din fiecare dintre roabe.” Și s-a auzit dinaintea Domnului rugăciunea Leei, și pruncii s-au schimbat în pântecele lor: și a fost dat Iosif în pântecele Rahelei și Dina în pântecele Leei.","notes":["Rosen: „Și apoi a născut o fată și i-a pus numele Dina.” Targumul leagă numele Dina de din („judecată”)."]},{"v":22,"t":"Și a intrat amintirea Rahelei înaintea Domnului, și s-a auzit înaintea Lui glasul rugăciunii ei, și a zis prin Cuvântul Său să-i dea fii."},{"v":23,"t":"Și a rămas însărcinată și a născut un fiu și a zis: „Domnul a adunat ocara mea; și tot așa Iehoșua, fiul lui Iosif, va aduna ocara Egiptului („Mițrayim”) de pe fiii lui Israel și îi va circumcide dincolo de Iordan.”","notes":["Iehoșua: circumcizia de la Ghilgal (Iosua 5:2–9). Iehoșua era din seminția lui Efraim, fiul lui Iosif."]},{"v":24,"t":"Și i-a pus numele Iosif, spunând: „Domnul să-mi mai adauge, pe lângă acesta, un alt fiu.”"},{"v":25,"t":"Și a fost, când Rahela l-a născut pe Iosif, Iacov a zis prin duhul sfințeniei că cei din casa lui Iosif vor fi ca o flacără care să-i mistuie pe cei din casa lui Esau; a zis: „De acum nu mă mai tem de Esau și de legiunile lui.” Și i-a zis lui Laban: „Lasă-mă să plec și să mă duc la locul meu și în țara mea."},{"v":26,"t":"Dă-mi soțiile și copiii mei, pentru care te-am slujit, și mă voi duce; căci tu știi slujba cu care te-am slujit.”"},{"v":27,"t":"Și Laban i-a zis: „Dacă am găsit acum îndurare în ochii tăi… am cercetat prin ghicit, și Domnul m-a binecuvântat din pricina ta.”"},{"v":28,"t":"Și a zis: „Hotărăște-ți plata în sarcina mea, și o voi da.”"},{"v":29,"t":"Și el i-a zis: „Tu știi cum te-am slujit și cum a fost păzită la mine vita ta."},{"v":30,"t":"Căci puțin era ce aveai înainte de mine, și a crescut din belșug, și Domnul te-a binecuvântat prin venirea mea, care ți-a adus folos de când am intrat în casa ta; și acum, când voi face și eu ceva, căci sunt dator să întrețin oamenii casei mele?”"},{"v":31,"t":"Și a zis: „Ce să-ți dau?” Și a zis Iacov: „Să nu-mi dai nimic altceva; dacă îmi faci lucrul acesta, mă voi întoarce, voi paște turma ta și o voi păzi."},{"v":32,"t":"Voi trece astăzi prin toată turma ta; voi scoate de acolo orice miel tărcat și pestriț și orice miel maroniu dintre miei, și pe cel pestriț și tărcat dintre capre; și aceasta va fi plata mea.","notes":["Termenii pentru oi sunt redați ca la Rosen: tărcat (Targum namor), pestriț (qeruaḥ), maroniu (laḥuș); „însemnat la picioare” (de-simana be-ragleihon, 30:35, 30:39–40) corespunde lui ʿaqod (la Rosen redat „bălțat”, 30:35)."]},{"v":33,"t":"Și să mărturisească pentru mine meritele mele în ziua de mâine, când vei veni la plata mea înaintea ta: tot ce nu este tărcat și pestriț dintre capre și maroniu dintre miei va fi furat, dacă va fi la mine.”"},{"v":34,"t":"Și a zis Laban: „Bine; o, de-ar fi după cuvântul tău!”"},{"v":35,"t":"Și a despărțit în ziua aceea țapii însemnați la picioare și pe cei pestriți și toate caprele tărcate și pestrițe, tot ce avea semn alb pe el, și tot ce era maroniu dintre miei, și le-a dat în mâna fiilor lui."},{"v":36,"t":"Și a pus o depărtare de trei zile de mers între turma lui și Iacov; iar Iacov păștea oile lui Laban, pe cele bătrâne și bolnave, care rămăseseră."},{"v":37,"t":"Și Iacov și-a luat nuiele înmugurite de plop și de alun și de ardafoi și a decojit pe ele fâșii albe, ca să descopere albul care era pe nuiele.","notes":["Rosen: „nuiele verzi de plop, alun și castan”. Al treilea nume de copac din sursă (ardafoi) este transcris; sensul este nesigur."]},{"v":38,"t":"Și a înfipt nuielele pe care le decojise în jgheaburi, în adăpătorile de apă, unde veneau oile să bea, le-a pus în fața oilor; și ele intrau în călduri când veneau să bea."},{"v":39,"t":"Și oile intrau în călduri în fața nuielelor și fătau oi însemnate la picioare, pestrițe și cu spinarea albă."},{"v":40,"t":"Și mieii i-a despărțit Iacov și a pus în fruntea turmei de la locul de culcare tot ce era însemnat la picioare și tot ce era maroniu în turma lui Laban; și și-a făcut turme numai pentru el și nu le-a amestecat cu turma lui Laban.","notes":["Rosen: „a pus oile să privească la cele bălțate”. „de la locul de culcare” (mișkuvita): sensul cuvântului din sursă este nesigur."]},{"v":41,"t":"Și era, în orice vreme când intrau în călduri oile timpurii, Iacov punea nuielele în fața ochilor oilor, în jgheaburi, ca să intre în călduri în fața nuielelor.","notes":["„timpurii” (mevakkerata) și „târzii” (laqișaya, 30:42): Targumul are sensul „timpuriu/târziu”; Rosen: „viguroase/plăpânde”."]},{"v":42,"t":"Iar la oile târzii nu le punea; și cele târzii erau ale lui Laban, iar cele timpurii ale lui Iacov."},{"v":43,"t":"Și omul a crescut foarte, foarte mult, și a avut oi multe și roabe și robi și cămile și măgari."}]},{"num":31,"title":"Capitolul 31","verses":[{"v":1,"t":"Și a auzit cuvintele fiilor lui Laban, care ziceau: „Iacov a luat tot ce era al tatălui nostru, și din ce era al tatălui nostru și-a făcut toată această bogăție de averi.”"},{"v":2,"t":"Și Iacov a văzut înfățișarea feței lui Laban, și iată, nu mai era senină față de el, ca ieri și alaltăieri."},{"v":3,"t":"Și a zis Domnul către Iacov: „Întoarce-te în țara părinților tăi și la rudenia ta, și Cuvântul Meu va fi în ajutorul tău.”"},{"v":4,"t":"Și Iacov l-a trimis pe Neftali, care era un sol iute, și le-a chemat pe Rahela și pe Lea, și au venit la câmp, la turma lui."},{"v":5,"t":"Și le-a zis: „Văd înfățișarea feței tatălui vostru, și iată, nu mai este senină cu mine ca ieri și alaltăieri; dar Dumnezeul tatălui meu, Cuvântul Lui a fost în ajutorul meu."},{"v":6,"t":"Și voi știți că din toată puterea mea l-am slujit pe tatăl vostru."},{"v":7,"t":"Iar tatăl vostru m-a înșelat și mi-a schimbat plata de zece ori; dar Domnul nu i-a dat putere să-mi facă rău.","notes":["Paranteza „(Ierușalmi: u-farag)” este în ediția sursă: o variantă din Targumul Ierușalmi, transcrisă; sensul cuvântului este nesigur. Rosen: „și mi-a schimbat plata de zeci de ori”."]},{"v":8,"t":"Dacă zicea așa: «Cele pestrițe vor fi plata ta», toate oile fătau pestrițe; iar dacă zicea așa: «Cele cu semn la picioare vor fi plata ta», toate oile fătau cu semn la picioare."},{"v":9,"t":"Și Domnul a golit casa tatălui vostru și mi-a dat-o mie."},{"v":10,"t":"Și a fost, la vremea când intrau în călduri oile, mi-am ridicat ochii și am văzut în vis, și iată, țapii care urcau pe oi erau cu semn la picioare și pestriți și cu spinarea albă."},{"v":11,"t":"Și mi-a zis îngerul Domnului în vis: «Iacov!» Și am zis: «Iată-mă.»"},{"v":12,"t":"Și a zis: «Ridică-ți, te rog, ochii și vezi: toți țapii care urcă pe oi sunt cu semn la picioare și pestriți și cu spinarea albă; căci este descoperită înaintea Mea toată asuprirea pe care ți-o face Laban."},{"v":13,"t":"Eu sunt Dumnezeul care M-am descoperit ție la Betel, unde ai uns un stâlp, unde Mi-ai făcut acolo un jurământ. Acum ridică-te, ieși din țara aceasta și întoarce-te în țara nașterii tale.»”","notes":["Rosen: „Eu sunt Dumnezeul din Betel, unde ai turnat libație pe o stelă”."]},{"v":14,"t":"Și Rahela a răspuns cu învoirea Leei, și i-au zis: „Mai este oare cu putință să avem parte și moștenire în casa tatălui nostru?"},{"v":15,"t":"Oare nu suntem socotite străine pentru el? Căci ne-a vândut și a mâncat chiar banii noștri."},{"v":16,"t":"Căci toată bogăția pe care a golit-o Domnul de la tatăl nostru este a noastră și a copiilor noștri; și acum, tot ce ți-a zis Domnul, fă.”"},{"v":17,"t":"Și Iacov s-a ridicat și i-a urcat pe fiii lui și pe soțiile lui pe cămile."},{"v":18,"t":"Și a luat toate vitele și toate averile lui pe care le agonisise, turmele și averile pe care le agonisise în Padan-Aram, ca să vină la Isaac, tatăl lui, în țara Canaanului."},{"v":19,"t":"Și Laban se dusese să-și tundă oile; și Rahela a furat chipurile, căci ei înjunghiau un om întâi născut și îi tăiau capul și îl sărau cu sare și cu mirodenii, și scriau descântece pe o plăcuță de aur și o puneau sub limba lui și îl așezau în perete, și el vorbea cu ei; și acestora li se închina tatăl ei.","notes":["Rosen: „Rahela a furat idolii casei, care aparțineau tatălui ei.” Targumul descrie, după tradiția agadică, cum erau făcuți terafimii."]},{"v":20,"t":"Și Iacov a furat mintea lui Laban arameul, pentru că nu i-a spus că pleacă.","notes":["Rosen: „Iar Iacov l-a păcălit pe Laban arameul”; Targumul păstrează expresia „a furat mintea”."]},{"v":21,"t":"Și a plecat el cu tot ce era al lui și s-a ridicat și a trecut Eufratul și și-a îndreptat fața să urce la muntele Galaad, căci a văzut prin duhul sfințeniei că acolo avea să fie izbăvirea pentru fiii lui în zilele lui Iftah, care era din Galaad.","notes":["Iftah: Judecătorii 11."]},{"v":22,"t":"Și după ce a plecat Iacov, păstorii s-au dus la fântână și n-au găsit apă; și au așteptat trei zile, poate va da pe dinafară, dar n-a dat pe dinafară; și atunci i s-a spus lui Laban, în ziua a treia, și a știut că Iacov fugise, căci prin meritul lui dăduse ea pe dinafară douăzeci de ani."},{"v":23,"t":"Și i-a luat pe rudele lui cu el și l-a urmărit cale de șapte zile și l-a ajuns, când el își așezase tabăra pe muntele Galaad, mulțumind și rugându-se înaintea Dumnezeului său."},{"v":24,"t":"Și a venit un înger, prin Cuvântul de la Domnul, și a scos sabia asupra lui Laban înșelătorul, în visul nopții, și i-a zis: „Păzește-te să nu vorbești cu Iacov nici bine, nici rău.”"},{"v":25,"t":"Și Laban l-a ajuns pe Iacov; iar Iacov își întinsese cortul pe munte, și Laban și-a așezat frații pe muntele acela al Galaadului."},{"v":26,"t":"Și a zis Laban către Iacov: „Ce ai făcut? Mi-ai furat mintea și mi-ai dus fiicele ca pe niște prizoniere de sabie."},{"v":27,"t":"De ce te-ai ascuns ca să pleci și mi-ai furat mintea și nu mi-ai spus? Căci dacă mi-ai fi spus, te-aș fi trimis cu bucurie și cu cântări de laudă, cu tobe și cu harfe."},{"v":28,"t":"Și nu m-ai lăsat să-i sărut pe fiii fiicelor mele și pe fiicele mele; acum ai lucrat fără minte în ce ai făcut."},{"v":29,"t":"Este în puterea mâinii mele să vă fac rău; dar Dumnezeul tatălui vostru mi-a zis aseară, spunând: «Păzește-te să vorbești cu Iacov nici bine, nici rău.»"},{"v":30,"t":"Și acum, dacă ai plecat, pentru că ți-era foarte dor de casa tatălui tău, de ce ai furat chipurile idolilor mei?”"},{"v":31,"t":"Și Iacov a răspuns și a zis lui Laban: „Pentru că m-am temut și am zis: «Poate îmi vei lua cu sila fiicele tale»."},{"v":32,"t":"Cel la care vei găsi chipurile idolilor tăi să moară înainte de vremea lui. În fața fraților noștri, cercetează ce este al tău la mine și ia-ți.” Și Iacov nu știa că Rahela le furase."},{"v":33,"t":"Și Laban a intrat în cortul lui Iacov și în cortul Leei și în corturile celor două roabe și n-a găsit; și a ieșit din cortul Leei și a intrat în cortul Rahelei."},{"v":34,"t":"Iar Rahela luase chipurile și le pusese în samarul cămilei și ședea pe ele; și el a scotocit tot cortul și n-a găsit."},{"v":35,"t":"Și ea a zis: „Să nu se aprindă mânia în ochii stăpânului meu că nu pot să mă ridic înaintea ta, căci am rânduiala femeilor.” Și a scotocit și n-a găsit chipurile."},{"v":36,"t":"Și mânia lui Iacov s-a aprins, și s-a certat cu Laban; și Iacov a răspuns și a zis lui Laban: „Care este vina mea și care este greșeala mea, că te-ai grăbit să vii după mine?"},{"v":37,"t":"Căci ai scotocit toate lucrurile mele: ce ai găsit din toate lucrurile casei tale? Pune-ți acum pricina în fața fraților mei și a fraților tăi, și să judece cu dreptate între noi doi."},{"v":38,"t":"Iată, douăzeci de ani am fost la tine: oile tale și caprele tale n-au lepădat, și berbecii turmei tale nu i-am mâncat."},{"v":39,"t":"Pe cea sfâșiată de fiarele câmpului nu ți-am adus-o; căci, dacă eu greșeam cu ea, din mâna mea o cereai; ce era furat ziua de oameni, eu trebuia să plătesc, și ce era furat noaptea de fiarele câmpului, eu trebuia să plătesc."},{"v":40,"t":"Ziua eram la câmp, mă mânca arșița, și gerul noaptea, și somnul fugea de la mine."},{"v":41,"t":"Iată, douăzeci de ani am fost în casa ta: te-am slujit paisprezece ani pentru cele două fiice ale tale și șase ani pentru turma ta, și mi-ai schimbat plata de zece ori."},{"v":42,"t":"Dacă Dumnezeul tatălui meu, Dumnezeul lui Avraam, și Cel de care se teme Isaac n-ar fi fost în ajutorul meu, acum m-ai fi trimis cu mâna goală; suferința mea și osteneala mâinilor mele sunt descoperite înaintea Domnului; de aceea te-a mustrat aseară.”"},{"v":43,"t":"Și Laban a răspuns și a zis lui Iacov: „Fetele pe care le-ai luat de soții sunt fiicele mele, și copiii pe care i-au născut sunt socotiți ca fiii mei, și oile sunt din oile mele, și tot ce vezi este al meu. Și fiicelor mele ce le-aș putea face astăzi, lor sau copiilor lor pe care i-au născut?"},{"v":44,"t":"Și acum, vino să încheiem un legământ, eu și tu, și să fie martor între mine și tine.”"},{"v":45,"t":"Și Iacov a luat o piatră și a ridicat-o stâlp."},{"v":46,"t":"Și a zis Iacov către fiii lui, pe care îi numea frații lui: „Strângeți pietre”; și au strâns pietre și au făcut o movilă, și au mâncat acolo pe movilă."},{"v":47,"t":"Și Laban a numit-o Ogar Sahid, iar Iacov a numit-o în limba Casei Sfințeniei Galed.","notes":["Rosen: „Laban a numit-o Iegar-Sahaduta și Iacov a numit-o Galed.” Targumul redă numele aramaic dat de Laban prin forma aramaică a vremii sale (Ogar Sahid, „movila-martor”), iar Galed este numit „în limba Casei Sfințeniei”, adică în ebraică."]},{"v":48,"t":"Și a zis Laban: „Movila aceasta este martor între mine și tine astăzi.” De aceea i-a pus numele Galed;"},{"v":49,"t":"și s-a numit Sekhuta, pentru că a zis: „Să privească Domnul între mine și tine când vom fi ascunși unul de altul.","notes":["Rosen: „și Mițpa”; Targumul: Sekhuta („locul de pază”), de la verbul yistekhei („să privească”)."]},{"v":50,"t":"Dacă le vei asupri pe fiicele mele, făcându-le umilință, și dacă vei lua soții pe lângă fiicele mele, nu este om care să ne judece: vezi, Cuvântul Domnului este martor între mine și tine.”"},{"v":51,"t":"Și a zis Laban către Iacov: „Iată movila aceasta și iată stâlpul pe care l-am ridicat între mine și tine."},{"v":52,"t":"Martoră este movila aceasta și martor este stâlpul, că nici eu nu voi trece la tine dincolo de movila aceasta, nici tu nu vei trece la mine dincolo de movila aceasta și de stâlpul acesta, ca să facem rău."},{"v":53,"t":"Dumnezeul lui Avraam și dumnezeul lui Nahor să judece între noi, dumnezeul tatălui lor.” Și Iacov a jurat pe Dumnezeul de care se temea tatăl său, Isaac.","notes":["Rosen: „Dumnezeul lui Avraam și dumnezeul lui Nahor, dumnezeii părinților lor, să judece între noi.”"]},{"v":54,"t":"Și Iacov a înjunghiat o jertfă pe munte și i-a chemat pe rudele lui, care veniseră cu Laban, să mănânce pâine; și au mâncat și au înnoptat pe munte."}]},{"num":32,"title":"Capitolul 32","verses":[{"v":1,"t":"Și Laban s-a sculat devreme dimineața și i-a sărutat pe fiii lui Iacov și pe fiicele lui, ale Leei, și i-a binecuvântat; și Laban a plecat și s-a întors la locul lui."},{"v":2,"t":"Și Iacov a mers în drumul lui, și l-au întâmpinat îngerii Domnului."},{"v":3,"t":"Și Iacov a zis, când i-a văzut: „Nu sunt oștile lui Esau care vin în întâmpinarea mea, nici oștile lui Laban care s-au întors să mă urmărească, ci sunt oștile îngerilor sfinți care au fost trimiși dinaintea Domnului.” De aceea a numit numele locului aceluia, în limba Casei Sfințeniei, Mahanaim.","notes":["Rosen: „Aceasta este tabăra lui Dumnezeu!” și a numit locul acela Mahanaim."]},{"v":4,"t":"A trimis: și Iacov a trimis soli înaintea lui la Esau, fratele lui, în țara Gavla, în câmpul edomiților.","notes":["Ediția sursă începe versetul cu cuvântul ebraic al Torei („A trimis”), urmat de textul aramaic. Rosen: „în ținutul Seir, câmpul Edom”; Gavla = Seir (ca la 14:6)."]},{"v":5,"t":"Și le-a poruncit, spunând: „Așa să-i spuneți stăpânului meu, lui Esau: Așa zice robul tău Iacov: Cu Laban am locuit ca străin și am zăbovit până acum."},{"v":6,"t":"Și din tot ce m-a binecuvântat tata nu am în mână decât puțin; am boi și măgari, oi și robi și roabe; și am trimis să-i spun stăpânului meu că nu mi-a folosit binecuvântarea aceea, ca să găsesc îndurare în ochii tăi, ca să nu păstrezi dușmănie împotriva mea pentru ea.”"},{"v":7,"t":"Și solii s-au întors la Iacov, spunând: „Am ajuns la fratele tău, la Esau, și vine și el în întâmpinarea ta, și patru sute de oameni, căpetenii de oaste, sunt cu el.”"},{"v":8,"t":"Și Iacov s-a temut foarte mult, pentru că douăzeci de ani nu se îndeletnicise cu cinstirea tatălui său, și era strâmtorat; și a împărțit poporul care era cu el și oile și boii și cămilele în două tabere, ca dar pentru Lea și ca dar pentru Rahela.","notes":["„ca dar pentru Lea și ca dar pentru Rahela” (le-mohavut): sensul exact al cuvântului este nesigur; redat literal."]},{"v":9,"t":"Și a zis: „Dacă vine Esau la una dintre tabere și o lovește, tabăra care rămâne va scăpa.”"},{"v":10,"t":"Și a zis Iacov: „Dumnezeul tatălui meu Avraam, El este Dumnezeul tatălui meu Isaac, Doamne, care mi-ai zis: «Întoarce-te în țara ta și la rudenia ta, și îți voi face bine»,"},{"v":11,"t":"nu sunt vrednic, și sunt prea mic pentru toate binefacerile și pentru tot adevărul pe care le-ai făcut cu robul Tău; căci numai cu toiagul meu am trecut Iordanul acesta, și acum am ajuns două tabere."},{"v":12,"t":"Scapă-mă, Te rog, din mâna fratelui meu cel mare, din mâna lui Esau, căci mă tem de el, pentru că el s-a îndeletnicit cu cinstirea tatălui său, ca nu cumva să vină și să mă lovească, pe mamă împreună cu copiii."},{"v":13,"t":"Iar Tu mi-ai făgăduit: «Îți voi face bine negreșit și îi voi face pe fiii tăi mulți ca nisipul mării, care nu se poate număra de mulțime.»”"},{"v":14,"t":"Și a înnoptat acolo în noaptea aceea și a luat din ce i se afla în mână un dar pentru Esau, fratele lui:"},{"v":15,"t":"două sute de capre și douăzeci de țapi, două sute de oi și douăzeci de berbeci,"},{"v":16,"t":"treizeci de cămile care alăptau, cu puii lor, patruzeci de vaci și zece tauri, douăzeci de măgărițe și zece mânji mici."},{"v":17,"t":"Și le-a dat în mâna slujitorilor lui, fiecare turmă deosebi, și a zis slujitorilor lui: „Treceți înaintea mea și lăsați o depărtare între turmă și turmă.”"},{"v":18,"t":"Și i-a poruncit celui dintâi, spunând: „Când te va întâlni Esau, fratele meu, și te va întreba, spunând: «Al cui ești și unde te duci și ale cui sunt acestea dinaintea ta?»,"},{"v":19,"t":"să spui: «Ale robului tău Iacov; este un dar trimis stăpânului meu, lui Esau; și iată, vine și el după noi.»”"},{"v":20,"t":"Și a poruncit și celui de-al doilea și celui de-al treilea și tuturor celor care mergeau după turme, spunând: „După cuvântul acesta să vorbiți cu Esau când îl veți găsi."},{"v":21,"t":"Și să spuneți: «Iată, și robul tău Iacov vine după noi»”, căci a zis: „Îi voi îmbuna fața cu darul care merge înaintea mea, și după aceea îi voi vedea fața; poate mă va primi cu față bună.”"},{"v":22,"t":"Și darul a trecut înaintea lui, iar el a înnoptat în noaptea aceea în tabără."},{"v":23,"t":"Și s-a sculat în noaptea aceea și le-a luat pe cele două soții ale lui și pe cele două roabe ale lui și pe cei unsprezece copii ai lui și a trecut vadul Iabocului."},{"v":24,"t":"Și i-a luat și i-a trecut pârâul și a trecut ce era al lui."},{"v":25,"t":"Și Iacov a rămas singur dincolo de Iaboc, și un înger s-a luptat cu el în chip de om și a zis: „Oare nu ai zis că vei da zeciuială din tot ce este al tău? Și iată, ai doisprezece fii și o fiică și nu ai dat zeciuială din ei.” Îndată a pus deoparte pe cei patru întâi născuți ai celor patru mame, și au rămas opt; și a început să numere de la Simeon, și Levi a ieșit ca zeciuială. A răspuns Mihail și a zis: „Stăpânul lumii, acesta este partea Ta.” Și din pricina acestor lucruri a zăbovit dincolo de pârâu până la ridicarea stâlpului zorilor.","notes":["Rosen: „Iacov a rămas singur și un bărbat s-a luptat cu el până la revărsatul zorilor.” Zeciuiala din fii: fără cei patru întâi născuți ai celor patru mame (Ruben, Dan, Gad, Iosif) rămân opt; numărând de la Simeon și reluând numărătoarea, al zecelea este Levi (cf. Pirkei de-Rabbi Eliezer 37). Mihail: arhanghelul."]},{"v":26,"t":"Și a văzut că nu avea putere să-i facă rău, și s-a atins de încheietura coapsei lui, și încheietura coapsei lui Iacov s-a clătinat când se lupta cu el."},{"v":27,"t":"Și a zis: „Lasă-mă să plec, căci s-a ridicat stâlpul zorilor și a sosit ceasul în care îngerii de sus Îl laudă pe Stăpânul lumii; și eu sunt unul dintre îngerii care laudă, și din ziua în care a fost creată lumea nu mi-a venit vremea să laud decât de data aceasta.” Și a zis: „Nu te las să pleci până nu mă binecuvântezi.”"},{"v":28,"t":"Și i-a zis: „Care este numele tău?” Și el a zis: „Iacov.”"},{"v":29,"t":"Și a zis: „Nu se va mai spune numele tău Iacov, ci Israel, căci te-ai arătat mare cu îngerii Domnului și cu oamenii și i-ai biruit.”","notes":["Rosen: „căci ai luptat cu Dumnezeu și cu oamenii și ai învins.”"]},{"v":30,"t":"Și Iacov l-a întrebat și a zis: „Spune-mi, te rog, numele tău.” Și el a zis: „De ce întrebi de numele meu?” Și l-a binecuvântat pe Iacov acolo."},{"v":31,"t":"Și Iacov a numit locul Peniel, căci a zis: „Am văzut îngerii Domnului față în față, și viața mi-a fost scăpată.”","notes":["Rosen: „L-am văzut pe Dumnezeu față în față și viața mi-a fost cruțată.”"]},{"v":32,"t":"Și soarele i-a strălucit înainte de vremea lui, el care apusese pentru el înainte de vremea lui când a ieșit din Beer-Șeba, când a trecut de Penuel; și a început să meargă, și șchiopăta din coapsă.","notes":["Rosen: „Soarele răsărea asupra lui când a trecut de Penuel”; vezi 28:10 (soarele apus înainte de vreme)."]},{"v":33,"t":"De aceea fiii lui Israel nu mănâncă nervul sciatic, care este la încheietura coapsei, din vite și din fiare, până în ziua aceasta, căci îngerul s-a atins și a apucat încheietura coapsei drepte a lui Iacov, în locul nervului sciatic."}]},{"num":33,"title":"Capitolul 33","verses":[{"v":1,"t":"Și Iacov și-a ridicat ochii și a văzut, și iată, Esau venea, și cu el patru sute de oameni, căpetenii de oaste; și i-a împărțit pe copii între Lea și Rahela și cele două roabe."},{"v":2,"t":"Și le-a pus pe roabe și pe copiii lor întâi, căci a zis: „Dacă vine Esau să-i nimicească pe copii și să facă desfrânare cu femeile, să facă cu acestea, iar între timp noi ne vom ridica și vom purta război cu el”; și pe Lea și pe copiii ei după ele, și pe Rahela și pe Iosif la urmă."},{"v":3,"t":"Iar el a trecut înaintea lor, rugându-se și cerând îndurare dinaintea Domnului, și s-a plecat până la pământ de șapte ori, până s-a apropiat de fratele lui."},{"v":4,"t":"Și Esau a alergat în întâmpinarea lui și l-a îmbrățișat și s-a aplecat pe gâtul lui și l-a sărutat; și au plâns: Esau a plâns de durerea dinților lui, care se clătinaseră, iar Iacov a plâns de durerea gâtului lui.","notes":["Explicația plânsului: după tradiția agadică, Esau a vrut să-l muște pe Iacov de gât, iar gâtul acestuia s-a făcut tare ca marmura (Bereșit Rabba 78:9)."]},{"v":5,"t":"Și și-a ridicat ochii și a văzut femeile și copiii și a zis: „Cine sunt aceștia pentru tine?” Și el a zis: „Sunt fiii care mi-au fost dați în dar dinaintea Domnului, robului tău.”"},{"v":6,"t":"Și s-au apropiat roabele, ele și copiii lor, și s-au plecat."},{"v":7,"t":"Și s-a apropiat și Lea cu copiii ei, și s-au plecat; și după aceea s-a apropiat Iosif și a stat în fața Rahelei și a acoperit-o cu statura lui; și s-au plecat.","notes":["Rosen: „Apoi s-au apropiat Iosif și Rahela și s-au prosternat.”"]},{"v":8,"t":"Și a zis: „Ce înseamnă pentru tine toată tabăra aceasta pe care am întâlnit-o?” Și el a zis: „Este un dar pe care l-am trimis ca să găsesc îndurare în ochii stăpânului meu.”"},{"v":9,"t":"Și a zis Esau: „Am averi multe, frate; să-ți rămână ce ai.”"},{"v":10,"t":"Și a zis Iacov: „Nu spune așa, te rog; dacă am găsit acum îndurare în ochii tăi, primește darul meu din mâna mea; căci de aceea am văzut înfățișarea feței tale, și mi s-a părut ca și cum aș vedea fața îngerului tău, căci ai binevoit față de mine.","notes":["Rosen: „căci ți-am văzut fața ca și cum aș vedea fața lui Dumnezeu și mi-ai fost binevoitor.”"]},{"v":11,"t":"Primește, te rog, darul care ți-a fost adus, căci mi-a fost dat în dar dinaintea Domnului și pentru că am averi multe.” Și a stăruit pe lângă el, și el a primit."},{"v":12,"t":"Și a zis: „Să pornim și să mergem, și eu voi merge în fața ta până vei ajunge la casa așezării tale.”"},{"v":13,"t":"Și el i-a zis: „Stăpânul meu știe că copiii sunt plăpânzi, iar oile și boii care alăptează sunt în grija mea; și dacă îi zoresc o singură zi, vor muri toate oile.","notes":["„plăpânzi” (ḥaṭin): sensul cuvântului din sursă este nesigur."]},{"v":14,"t":"Să treacă, te rog, stăpânul meu înaintea robului său, iar eu voi merge încet, de unul singur, după pasul turmelor care sunt înaintea mea și după pasul creșterii copiilor, până voi ajunge la stăpânul meu în Gavla.”","notes":["Rosen: „până ce voi ajunge la stăpânul meu în Seir”; Gavla = Seir."]},{"v":15,"t":"Și a zis Esau: „Să las, te rog, cu tine din oștenii care sunt cu mine.” Și el a zis: „De ce aceasta? Să găsesc îndurare înaintea stăpânului meu.”"},{"v":16,"t":"Și i s-a făcut o minune lui Iacov: Esau s-a întors în ziua aceea pe drumul lui spre Gavla."},{"v":17,"t":"Și Iacov a pornit spre Sucot și a zăbovit acolo douăsprezece luni ale anului; și și-a construit o casă de studiu, iar pentru vitele lui a făcut colibe; de aceea a numit numele locului Sucot.","notes":["Rosen: „Și Iacov a plecat către Sucot și și-a construit o casă”."]},{"v":18,"t":"Și Iacov a venit întreg în tot ce era al lui la cetatea Sihem, care este în țara Canaanului, când a venit din Padan-Aram, și și-a așezat tabăra în fața cetății."},{"v":19,"t":"Și a cumpărat moștenirea câmpului unde își întinsese acolo cortul, de la fiii lui Hamor, tatăl lui Sihem, cu o sută de mărgăritare.","notes":["Rosen: „pentru o sută de kesita”; Targumul: „o sută de mărgăritare”."]},{"v":20,"t":"Și a ridicat acolo un altar, și acolo a dat zeciuielile pe care le pusese deoparte din tot ce avea, înaintea lui Dumnezeu, Dumnezeul lui Israel.","notes":["Rosen: „și l-a numit El-Elohei-Israel.”"]}]},{"num":34,"title":"Capitolul 34","verses":[{"v":1,"t":"Și Dina, fiica Leei, pe care i-o născuse lui Iacov, a ieșit să vadă obiceiul fiicelor popoarelor țării."},{"v":2,"t":"Și a văzut-o Sihem, fiul lui Hamor hivitul, căpetenia țării, și a luat-o cu sila și s-a culcat cu ea și a necinstit-o."},{"v":3,"t":"Și sufletul lui a îndrăgit-o pe Dina, fiica lui Iacov, și a iubit-o pe fată și a vorbit cuvinte de împăcare la inima fetei."},{"v":4,"t":"Și a zis Sihem către Hamor, tatăl lui, spunând: „Ia-mi pe fata aceasta de soție.”"},{"v":5,"t":"Și Iacov a auzit că o pângărise pe Dina, fiica lui; iar fiii lui erau cu vitele lui în câmp, și Iacov a tăcut până la venirea lor."},{"v":6,"t":"Și Hamor, tatăl lui Sihem, a ieșit la Iacov ca să vorbească cu el."},{"v":7,"t":"Și fiii lui Iacov au venit de la câmp când au auzit, și oamenii s-au mâhnit, și i-a mâniat foarte tare, căci Sihem făcuse o rușine în Israel, culcându-se cu fiica lui Iacov, și așa nu se cuvenea să se facă."},{"v":8,"t":"Și Hamor a vorbit cu ei, spunând: „Sihem, fiul meu, sufletul lui a îndrăgit-o pe fiica voastră; dați-i-o, vă rog, de soție."},{"v":9,"t":"Și încuscriți-vă cu noi: fiicele voastre să ni le dați nouă, și fiicele noastre să le luați pentru voi."},{"v":10,"t":"Și cu noi veți locui, și țara va fi înaintea voastră; locuiți unde vă place și faceți negoț în ea și luați moștenire în ea.”"},{"v":11,"t":"Și a zis Sihem către tatăl ei și către frații ei: „Să găsesc îndurare în ochii voștri, și ce-mi veți spune voi da."},{"v":12,"t":"Măriți-mi foarte mult zestrea și darul, și voi da cum îmi veți spune; numai dați-mi fata de soție.”"},{"v":13,"t":"Și fiii lui Iacov le-au răspuns lui Sihem și lui Hamor, tatăl lui, cu înțelepciune și au vorbit, pentru că o pângărise pe Dina, sora lor."},{"v":14,"t":"Și le-au zis: „Nu putem face lucrul acesta, să o dăm pe sora noastră unui om care are prepuț, căci aceasta este o rușine pentru noi."},{"v":15,"t":"Numai cu aceasta ne vom învoi cu voi: dacă veți fi ca noi, circumcizându-se la voi orice bărbat."},{"v":16,"t":"Și vă vom da pe fiicele noastre, și pe fiicele voastre le vom lua pentru noi, și vom locui cu voi și vom fi un singur popor."},{"v":17,"t":"Iar dacă nu ne veți asculta să vă circumcideți, o vom lua cu putere pe fiica noastră și vom pleca.”"},{"v":18,"t":"Și cuvintele lor au fost plăcute în ochii lui Hamor și în ochii lui Sihem, fiul lui Hamor."},{"v":19,"t":"Și tânărul n-a zăbovit să facă lucrul acesta, căci o dorea pe fiica lui Iacov; și el era cel mai cinstit din toată casa tatălui său."},{"v":20,"t":"Și Hamor și Sihem, fiul lui, au venit la poarta cetății lor și au vorbit cu oamenii porții cetății lor, spunând:"},{"v":21,"t":"„Oamenii aceștia sunt pașnici cu noi; să locuiască în țară și să facă negoț în ea; și țara, iată, este largă în hotare înaintea lor; pe fiicele lor să le luăm de soții, și pe fiicele noastre să le dăm lor."},{"v":22,"t":"Numai cu aceasta se vor învoi oamenii cu noi să locuiască cu noi, ca să fim un singur popor: dacă se va circumcide la noi orice bărbat, cum se circumcid ei."},{"v":23,"t":"Turmele lor și averile lor și toate vitele lor, oare nu vor fi ale noastre? Numai să ne învoim cu ei, și vor locui cu noi.”"},{"v":24,"t":"Și i-au ascultat pe Hamor și pe Sihem, fiul lui, toți cei care ieșeau pe poarta cetății lui, și s-a circumcis orice bărbat, toți cei care ieșeau pe poarta cetății lui."},{"v":25,"t":"Și a fost, în ziua a treia, când erau slăbiți de durerea circumciziei lor, doi dintre fiii lui Iacov, Simeon și Levi, frații Dinei, și-au luat fiecare sabia și au venit asupra cetății, care locuia fără grijă, și au ucis pe orice bărbat."},{"v":26,"t":"Și pe Hamor și pe Sihem, fiul lui, i-au ucis cu ascuțișul sabiei și au luat-o pe Dina din casa lui Sihem și au ieșit."},{"v":27,"t":"Ceilalți fii ai lui Iacov au intrat să-i despoaie pe cei uciși și au prădat cetatea în care o pângăriseră pe sora lor."},{"v":28,"t":"Oile lor și boii lor și măgarii lor, și ce era în cetate și ce era în câmp, au prădat."},{"v":29,"t":"Și toate averile lor și toți copiii lor și pe femeile lor i-au luat prizonieri și i-au prădat, și tot ce era în casă."},{"v":30,"t":"Și a zis Iacov către Simeon și către Levi: „M-ați tulburat, ca să-mi iasă nume rău printre locuitorii țării, printre canaaniți și printre periziți; iar eu sunt un popor puțin la număr, și se vor aduna împotriva mea și mă vor lovi, și voi fi nimicit, eu și oamenii casei mele.”"},{"v":31,"t":"Au răspuns Simeon și Levi: „Nu se cuvine să se spună în adunările lui Israel: «Niște necircumciși au pângărit o fecioară și niște închinători la idoli au întinat-o pe fiica lui Iacov»; ci așa se cuvine să se spună: «Niște necircumciși au fost uciși din pricina unei fecioare, și niște închinători la idoli din pricina fiicei lui Iacov.» Și să nu-și bată joc Sihem, fiul lui Hamor, cu vorbele lui de noi; și ca de o femeie rătăcită, care iese pe drum și nu are cine s-o apere, să facă cu sora noastră, dacă nu făceam lucrul acesta?”","notes":["Rosen: „Să se poarte oare cu sora noastră precum cu o prostituată?”"]}]},{"num":35,"title":"Capitolul 35","verses":[{"v":1,"t":"Și a zis Domnul către Iacov: „Ridică-te, urcă la Betel și locuiește acolo și fă acolo un altar Dumnezeului care ți S-a descoperit când fugeai dinaintea lui Esau, fratele tău.”"},{"v":2,"t":"Și a zis Iacov către oamenii casei lui și către toți cei care erau cu el: „Îndepărtați idolii popoarelor care sunt în mijlocul vostru, pe care i-ați adus din casa idolilor Sihemului, și curățiți-vă de pângărirea celor uciși de care v-ați atins, și schimbați-vă hainele."},{"v":3,"t":"Și să ne ridicăm și să urcăm la Betel, și voi face acolo un altar Dumnezeului care mi-a primit rugăciunea în ziua strâmtorării mele și al cărui Cuvânt a fost în ajutorul meu pe drumul pe care am mers.”"},{"v":4,"t":"Și i-au dat în mâna lui Iacov toți idolii popoarelor care erau în mâinile lor, pe care îi aduseseră din idolii Sihemului, și cerceii care erau în urechile locuitorilor cetății Sihem, pe care era zugrăvit chipul idolului lor; și Iacov i-a ascuns sub terebintul care este lângă cetatea Sihem."},{"v":5,"t":"Și au pornit de acolo, mulțumind și rugându-se înaintea Domnului; și a fost groază de la Domnul asupra popoarelor din cetățile dimprejurul lor, și nu i-au urmărit pe fiii lui Iacov."},{"v":6,"t":"Și Iacov a venit la Luz, în țara Canaanului, adică Betel, el și tot poporul care era cu el."},{"v":7,"t":"Și a construit acolo un altar și a numit locul acela: „Dumnezeu, care Și-a sălășluit Șechina la Betel”, căci acolo i se descoperiseră îngerii Domnului când fugea dinaintea lui Esau, fratele lui.","notes":["Rosen: „și a numit locul El-Betel, căci acolo i Se dezvăluise Dumnezeu pe când fugea dinaintea fratelui său.”"]},{"v":8,"t":"Și a murit Debora, doica Rebecăi, și a fost îngropată mai jos de Betel, la poalele câmpiei; și acolo i s-a vestit lui Iacov moartea Rebecăi, mama lui, și a numit numele locului „Altă plângere”.","notes":["Rosen: „și Iacov a numit locul Alon-Bahut.” Targumul înțelege numele ca „altă plângere” (alon = „altul” în greacă), legându-l de vestea morții Rebecăi."]},{"v":9,"t":"Și Domnul i S-a arătat din nou lui Iacov când venea din Padan-Aram, și Domnul l-a binecuvântat în Numele Cuvântului Său, după ce murise mama lui."},{"v":10,"t":"Și i-a zis Domnul: „Până acum numele tău a fost Iacov; nu se va mai numi numele tău Iacov, ci Israel va fi numele tău.” Și i-a pus numele Israel."},{"v":11,"t":"Și i-a zis Domnul: „Eu sunt Dumnezeul Atotputernic: fii roditor și înmulțește-te; un popor sfânt și adunări de profeți și de preoți vor fi din fiii tăi pe care i-ai născut, și încă doi regi vor ieși din tine."},{"v":12,"t":"Și țara pe care am dat-o lui Avraam și lui Isaac ți-o voi da ție, și fiilor tăi după tine le voi da țara.”"},{"v":13,"t":"Și Șechina Domnului S-a înălțat de la el, în locul în care vorbise cu el."},{"v":14,"t":"Și a ridicat acolo un stâlp în locul în care vorbise cu el, un stâlp de piatră, și a turnat pe el turnare de vin și turnare de apă, căci așa aveau să facă la Sărbătoarea Corturilor, și a vărsat pe el untdelemn de măsline."},{"v":15,"t":"Și Iacov a numit numele locului în care vorbise Domnul cu el acolo Betel."},{"v":16,"t":"Și au pornit de la Betel, și mai era o întindere cât un câmp al roadelor pământului până să ajungă la Efrata; și Rahela a născut și a avut o naștere grea.","notes":["Rosen: „și când mai era o bucată de drum până la Efrata”. Expresia din sursă (sugeʿei așwan ʿalalta de-arʿa) are un sens nesigur; redată literal."]},{"v":17,"t":"Și a fost, când avea naștere grea, moașa i-a zis: „Nu te teme, căci și acesta îți este fiu.”"},{"v":18,"t":"Și a fost, când îi ieșea sufletul, căci venise asupra ei moartea, i-a pus numele Bar-Dewai, iar tatăl lui i-a pus numele Beniamin.","notes":["Rosen: „ea i-a pus numele Ben-Oni”; Targumul are forma aramaică Bar-Dewai („fiul durerii mele”)."]},{"v":19,"t":"Și a murit Rahela și a fost îngropată pe drumul spre Efrata, adică Betleem."},{"v":20,"t":"Și Iacov a ridicat un stâlp pe mormântul ei: acesta este stâlpul mormântului Rahelei până în ziua aceasta."},{"v":21,"t":"Și Iacov a pornit și și-a întins cortul dincolo de Migdal-Eder, locul de unde avea să Se descopere Regele Mesia la sfârșitul zilelor."},{"v":22,"t":"Și a fost, când Israel locuia în țara aceea, Ruben s-a dus și a răvășit patul Bilhei, concubina tatălui său, care era așezat în fața patului Leei, mama mea; și i s-a socotit ca și cum s-ar fi culcat cu ea. Și Israel a auzit, și i-a fost rău, și a zis: „Vai, poate a ieșit din mine un cusur, așa cum a ieșit din Avraam Ismael și din tatăl meu a ieșit Esau.” A răspuns duhul sfințeniei și așa i-a zis: „Nu te teme, căci toți sunt drepți și nu este în ei niciun cusur.” Căci, după ce s-a născut Beniamin, fiii lui Iacov au fost doisprezece.","notes":["Rosen: „Ruben a mers și s-a culcat cu Bilha, concubina tatălui său”. „mama mea”: așa în sursă (cuvintele lui Ruben, fără introducere)."]},{"v":23,"t":"Fiii Leei: întâiul născut al lui Iacov, Ruben, și Simeon și Levi și Iuda, Isahar și Zabulon."},{"v":24,"t":"Fiii Rahelei: Iosif și Beniamin."},{"v":25,"t":"Și fiii Bilhei, roaba Rahelei: Dan și Neftali."},{"v":26,"t":"Și fiii Zilpei, roaba Leei: Gad și Așer. Aceștia sunt fiii lui Iacov, care i s-au născut în Padan-Aram."},{"v":27,"t":"Și Iacov a venit la Isaac, tatăl său, la Mamre, la Chiriat-Arba, adică Hebron, unde locuiseră ca străini Avraam și Isaac."},{"v":28,"t":"Și zilele lui Isaac au fost o sută optzeci de ani."},{"v":29,"t":"Și Isaac și-a dat sufletul și a fost adunat la poporul său, bătrân și sătul de zile; și l-au îngropat Esau și Iacov, fiii lui."}]},{"num":36,"title":"Capitolul 36","verses":[{"v":1,"t":"Și acestea sunt spițele lui Esau, care este numit Edom."},{"v":2,"t":"Esau și-a luat soțiile dintre fiicele Canaanului: pe Ada, fiica lui Elon hititul, și pe Oholibama, fiica lui Ana, fiica lui Țibeon hivitul,"},{"v":3,"t":"și pe Basmat, fiica lui Ismael, pe care i-o dăduse de soție Nebaiot, fratele ei.","notes":["Rosen: „și pe Basmat, fiica lui Ismael, sora lui Nebaiot.”"]},{"v":4,"t":"Și Ada i l-a născut lui Esau pe Elifaz, iar Basmat l-a născut pe Reuel."},{"v":5,"t":"Și Oholibama i-a născut pe Ieuș și pe Ialam și pe Core. Aceștia sunt fiii lui Esau, care i s-au născut în țara Canaanului."},{"v":6,"t":"Și Esau și-a luat soțiile și fiii și fiicele și toate sufletele casei lui și turmele și vitele și toate averile pe care le agonisise în țara Canaanului și s-a dus în altă țară, căci căzuse asupra lui frica de Iacov, fratele lui."},{"v":7,"t":"Căci averile lor erau prea multe ca să locuiască împreună, și țara în care locuiau ca străini nu-i putea purta din pricina turmelor lor."},{"v":8,"t":"Și Esau a locuit în muntele Gavla; Esau este căpetenia edomiților."},{"v":9,"t":"Și acestea sunt spițele lui Esau, căpetenia edomiților, a căror locuință era în muntele Gavla."},{"v":10,"t":"Acestea sunt numele fiilor lui Esau: Elifaz, fiul Adei, soția lui Esau; Reuel, fiul Basmatei, soția lui Esau."},{"v":11,"t":"Și fiii lui Elifaz au fost: Teman, Omar, Țefo și Gaetam și Chenaz."},{"v":12,"t":"Și Timna era concubina lui Elifaz, fiul lui Esau, și i l-a născut lui Elifaz pe Amalec; el este Elifaz, prietenul lui Iov. Aceștia sunt fiii Adei, soția lui Esau.","notes":["Iov: personajul cărții Iov (Iov 2:11)."]},{"v":13,"t":"Și aceștia sunt fiii lui Reuel: Nahat și Zerah, Șama și Miza; aceștia au fost fiii Basmatei, soția lui Esau."},{"v":14,"t":"Și aceștia au fost fiii Oholibamei, fiica lui Ana, fiica lui Țibeon, soția lui Esau: i-a născut lui Esau pe Ieuș și pe Ialam și pe Core."},{"v":15,"t":"Acestea sunt căpeteniile fiilor lui Esau: fiii lui Elifaz, întâiul născut al lui Esau: căpetenia Teman, căpetenia Omar, căpetenia Țefo, căpetenia Chenaz,"},{"v":16,"t":"căpetenia Core, căpetenia Gaetam, căpetenia Amalec; acestea sunt căpeteniile lui Elifaz, a căror locuință era în țara Edomului; aceștia sunt fiii Adei."},{"v":17,"t":"Și aceștia sunt fiii lui Reuel, fiul lui Esau: căpetenia Nahat, căpetenia Zerah, căpetenia Șama, căpetenia Miza; acestea sunt căpeteniile lui Reuel, a căror locuință era în țara Edomului; aceștia sunt fiii Basmatei, soția lui Esau."},{"v":18,"t":"Și aceștia sunt fiii Oholibamei, soția lui Esau: căpetenia Ieuș, căpetenia Ialam, căpetenia Core; acestea sunt căpeteniile Oholibamei, fiica lui Ana, soția lui Esau."},{"v":19,"t":"Aceștia sunt fiii lui Esau și acestea sunt căpeteniile lor; el este tatăl edomiților."},{"v":20,"t":"Aceștia sunt fiii lui Gavla, ginusaya, care locuiau mai înainte în țara aceea: Lotan și Șobal și Țibeon și Ana,","notes":["Rosen: „Aceștia sunt fiii lui Seir horitul, locuitorii țării”. Gavla = Seir; ginusaya (în loc de „horiți”) este transcris; sensul probabil: „cei de neam vechi”."]},{"v":21,"t":"și Dișon și Ețer și Dișan; acestea sunt căpeteniile ginusaya, fiii lui Gavla, a căror locuință era din vechime în țara edomiților."},{"v":22,"t":"Și fiii lui Lotan au fost Hori și Hemam; și sora lui Lotan era Timna."},{"v":23,"t":"Și aceștia sunt fiii lui Șobal: Alvan și Manahat și Ebal, Șefo și Onam."},{"v":24,"t":"Și aceștia sunt fiii lui Țibeon: Aia și Ana; el este Ana care a împerecheat turmele cu măgărițele, și cu vremea a găsit catârii care au ieșit din ele, pe când păștea măgarii lui Țibeon, tatăl său.","notes":["Rosen: „el este acel Ana care a descoperit catârii în deșert”. După „turmele” ediția sursă are o corectură între paranteze drepte: „trebuie citit: ʿarodayya” („măgarii sălbatici”), adică „a împerecheat măgarii sălbatici cu măgărițele”."]},{"v":25,"t":"Și aceștia sunt fiii lui Ana: Dișon și Oholibama, fiica lui Ana."},{"v":26,"t":"Și aceștia sunt fiii lui Dișan: Hemdan și Eșban și Itran și Cheran."},{"v":27,"t":"Aceștia sunt fiii lui Ețer: Bilhan și Zaavan și Acan."},{"v":28,"t":"Aceștia sunt fiii lui Dișan: Uț și Aran."},{"v":29,"t":"Acestea sunt căpeteniile ginusaya: căpetenia Lotan, căpetenia Șobal, căpetenia Țibeon, căpetenia Ana,"},{"v":30,"t":"căpetenia Dișon, căpetenia Ețer, căpetenia Dișan; acestea sunt căpeteniile ginusaya, după căpeteniile lor, a căror locuință era mai înainte în țara Gavla."},{"v":31,"t":"Și aceștia sunt regii care au domnit în țara Edomului înainte să domnească un rege peste fiii lui Israel."},{"v":32,"t":"Și a domnit în Edom Bela, fiul lui Beor, și numele cetății casei lui regale era Dinhaba."},{"v":33,"t":"Și a murit Bela, și a domnit în locul lui Iobab, fiul lui Zerah din Boțra."},{"v":34,"t":"Și a murit Iobab, și a domnit în locul lui Hușam din țara de miazăzi.","notes":["Rosen: „din țara temaniților”."]},{"v":35,"t":"Și a murit Hușam, și a domnit în locul lui Hadad, fiul lui Bedad, care i-a ucis pe madianiți când s-a rânduit la luptă cu ei în câmpiile Moabului; și numele cetății casei lui regale era Avit."},{"v":36,"t":"Și a murit Hadad, și a domnit în locul lui Samla din Masreca."},{"v":37,"t":"Și a murit Samla, și a domnit în locul lui Saul, care era din Rehobot de pe Eufrat."},{"v":38,"t":"Și a murit Saul, și a domnit în locul lui Baal-Hanan, fiul lui Acbor."},{"v":39,"t":"Și a murit Baal-Hanan, fiul lui Acbor, și a domnit în locul lui Hadar; și numele cetății casei lui regale era Pau, și numele soției lui era Meheitavel, fiica lui Matred; el este omul care se ostenea cu goana și cu plasa, iar după ce s-a îmbogățit și a agonisit averi, s-a întors să se mândrească în inima lui, zicând: „Ce este argintul și ce este aurul?”","notes":["Rosen: „fiica lui Matred, fiica lui Mei-Zahav.” „cu goana și cu plasa” (be-maṭreda u-ve-sardita): sensul cuvintelor este nesigur; Targumul explică numele Matred și Mei-Zahav („ape de aur”)."]},{"v":40,"t":"Și acestea sunt numele căpeteniilor lui Esau, după spițele lor, după locul așezărilor lor, după numele lor: căpetenia Timna, căpetenia Alva, căpetenia Ietet,"},{"v":41,"t":"căpetenia Oholibama, căpetenia Ela, căpetenia Pinon,"},{"v":42,"t":"căpetenia Chenaz, căpetenia Teman, căpetenia Mibțar,","notes":["Rosen: „căpetenia Teman”."]},{"v":43,"t":"căpetenia Magdiel — el era numit Magdiel după numele cetății lui, Migdal Taqif —, căpetenia Iram. Acestea sunt căpeteniile Edomului, după locuințele lor, în țara moștenirii lor; el este Esau, tatăl edomiților.","notes":["Migdal Taqif: „turnul tare”."]}]},{"num":37,"title":"Capitolul 37","verses":[{"v":1,"t":"S-a așezat: și Iacov a locuit în liniște în țara în care locuise ca străin tatăl său, în țara Canaanului.","notes":["Ediția sursă începe versetul cu cuvântul ebraic al Torei („S-a așezat”), urmat de textul aramaic. Rosen: „Iacov s-a așezat în țara peregrinărilor tatălui său”."]},{"v":2,"t":"Acestea sunt spițele lui Iacov: Iosif avea șaptesprezece ani când a ieșit din casa de studiu, și el era un tânăr crescut împreună cu fiii Bilhei și cu fiii Zilpei, soțiile tatălui său; și Iosif aducea vestea lor rea, pe care o văzuse: că mâncau carne tăiată dintr-un animal viu, urechile și cozile; și a venit și i-a spus tatălui lor."},{"v":3,"t":"Și Israel îl iubea pe Iosif mai mult decât pe toți fiii lui, căci chipul lui Iosif semăna cu chipul lui; și i-a făcut o manta împodobită.","notes":["Rosen: „căci îi era fiu al bătrâneților lui; și i-a făcut o tunică de lână fină.” Targumul înțelege ben zequnim ca „asemănarea chipului”."]},{"v":4,"t":"Și frații lui au văzut că pe el îl iubea tatăl lor mai mult decât pe toți frații lui, și i-au purtat dușmănie și nu voiau să-i vorbească cu pace."},{"v":5,"t":"Și Iosif a visat un vis și le-a spus fraților lui, și i-au purtat și mai multă dușmănie."},{"v":6,"t":"Și le-a zis: „Ascultați, vă rog, visul acesta pe care l-am visat:"},{"v":7,"t":"iată, noi legam snopi în mijlocul câmpului, și iată, snopul meu s-a ridicat și chiar a stat drept; și iată, snopii voștri s-au strâns împrejur și s-au plecat înaintea snopului meu.”"},{"v":8,"t":"Și frații lui i-au zis: „Oare te închipui că vei domni peste noi? Sau speri că vei stăpâni peste noi?” Și i-au purtat și mai multă dușmănie pentru visele lui și pentru cuvintele lui."},{"v":9,"t":"Și a mai visat un alt vis și l-a povestit fraților lui și a zis: „Iată, am mai visat un vis: și iată, soarele și luna și unsprezece stele se plecau înaintea mea.”"},{"v":10,"t":"Și l-a povestit tatălui său și fraților lui, și tatăl său l-a mustrat și i-a zis: „Ce este visul acesta pe care l-ai visat? Oare vom veni noi, eu și mama ta și frații tăi, să ne plecăm înaintea ta până la pământ?”"},{"v":11,"t":"Și frații lui l-au invidiat, iar tatăl lui a păstrat cuvântul în inima lui."},{"v":12,"t":"Și frații lui s-au dus să pască oile tatălui lor la Sihem."},{"v":13,"t":"Și a fost, după o vreme, și a zis Israel către Iosif: „Oare frații tăi nu pasc la Sihem? Și mă tem să nu vină hiviții și să-i lovească, din pricină că i-au lovit pe Hamor și pe Sihem și pe locuitorii cetății. Vino acum, și te voi trimite la ei.” Și el i-a zis: „Iată-mă.”"},{"v":14,"t":"Și i-a zis: „Du-te, te rog, vezi de sănătatea fraților tăi și de sănătatea oilor și adu-mi vești.” Și l-a trimis din pricina sfatului adânc care fusese grăit cu Avraam la Hebron; și în ziua aceea a fost începutul exilului din Egipt („Mițrayim”). Și s-a ridicat și Iosif a venit la Sihem.","notes":["„sfatul adânc… cu Avraam la Hebron”: legământul dintre bucăți și vestirea exilului (15:13)."]},{"v":15,"t":"Și l-a găsit Gabriel în chip de om, și iată, rătăcea prin câmp; și omul l-a întrebat, spunând: „Ce cauți?”","notes":["Gabriel: îngerul Gabriel."]},{"v":16,"t":"Și a zis: „Pe frații mei îi caut; spune-mi, te rog, unde pasc ei.”"},{"v":17,"t":"Și a zis omul: „Au plecat de aici, căci am auzit de după perdea că de astăzi a început robia egiptenilor, și li s-a spus prin profeție că hiviții vor să se rânduiască la luptă cu ei; de aceea ziceau: «Să mergem la Dotan».” Și Iosif a mers după frații lui și i-a găsit în Dotan.","notes":["„de după perdea” (pargod): expresie agadică pentru hotărârile auzite din cer."]},{"v":18,"t":"Și l-au văzut de departe, și înainte să se apropie de ei s-au sfătuit împotriva lui să-l ucidă."},{"v":19,"t":"Și Simeon și Levi, care erau frați în sfat, au zis unul către altul: „Iată, vine stăpânul viselor acela."},{"v":20,"t":"Și acum, veniți să-l ucidem și să-l aruncăm într-una din gropi, și vom zice: «O fiară rea l-a mâncat»; și vom vedea ce se va alege de visele lui.”"},{"v":21,"t":"Și Ruben a auzit și l-a scăpat din mâinile lor și a zis: „Să nu-l ucidem, ca să nu ne facem vinovați de sângele lui.”"},{"v":22,"t":"Și Ruben le-a zis: „Nu vărsați sânge nevinovat; aruncați-l în groapa aceasta din pustiu, dar mână ucigașă să nu întindeți asupra lui”, ca să-l scape din mâinile lor și să-l ducă înapoi la tatăl său."},{"v":23,"t":"Și a fost, când a venit Iosif la frații lui, l-au dezbrăcat pe Iosif de mantaua lui, de mantaua împodobită care era pe el."},{"v":24,"t":"Și l-au luat și l-au aruncat în groapă; și groapa era goală, nu era apă în ea, dar erau în ea șerpi și scorpioni."},{"v":25,"t":"Și s-au întors să mănânce pâine și și-au ridicat ochii și au văzut, și iată, o caravană de arabi venea din Galaad, și cămilele lor erau încărcate cu ceară și rășină de balsam și lotus, mergând să le coboare în Egipt („Mițrayim”).","notes":["Rosen: „o caravană de ismaeliți venea din Galaad”; Targumul are „arabi” (ʿarvaʾin), aici și la 37:27–28."]},{"v":26,"t":"Și a zis Iuda către frații lui: „Ce folos de bani vom avea dacă îl ucidem pe fratele nostru și ascundem sângele lui?"},{"v":27,"t":"Veniți să-l vindem arabilor, și mâna noastră să nu fie asupra lui ca să-l ucidem, căci este fratele nostru, carnea noastră.” Și frații lui au ascultat."},{"v":28,"t":"Și au trecut niște oameni madianiți, negustori, și l-au tras și l-au scos pe Iosif din groapă și l-au vândut pe Iosif arabilor pentru douăzeci de maʿa de argint; și au cumpărat cu ei sandale; și l-au adus pe Iosif în Egipt („Mițrayim”).","notes":["maʿa: monedă mică de argint (Rosen: „pentru douăzeci de arginți”). Sandalele: cf. Amos 2:6."]},{"v":29,"t":"Și Ruben s-a întors la groapă, căci nu fusese cu ei la masă când l-au vândut, pentru că ședea în post, pentru că răvășise patul tatălui său; și se dusese și ședea printre munți, ca să se întoarcă la groapă să-l scoată pentru tatăl său, poate îl va primi cu față bună; și când s-a întors și a văzut, și iată, Iosif nu era în groapă, și-a sfâșiat hainele."},{"v":30,"t":"Și s-a întors la frații lui și a zis: „Copilul nu mai este, iar eu unde să mă duc? Și cum voi privi fața tatălui meu?”"},{"v":31,"t":"Și au luat mantaua lui Iosif și au înjunghiat un țap dintre capre, pentru că sângele lui seamănă cu al omului, și au muiat mantaua în sânge."},{"v":32,"t":"Și au trimis mantaua împodobită prin mâna fiilor Zilpei și prin mâna fiilor Bilhei, și au adus-o tatălui lor și au zis: „Iată ce am găsit; recunoaște, te rog: este mantaua fiului tău sau nu?”"},{"v":33,"t":"Și a recunoscut-o și a zis: „Este mantaua fiului meu; nu o fiară a câmpului l-a mâncat și nici nu a fost ucis de mâna oamenilor, ci văd prin duhul sfințeniei că o femeie rea stă împotriva lui.”","notes":["Rosen: „O sălbăticiune l-a devorat! Iosif a fost negreșit sfâșiat!” „o femeie rea”: soția lui Potifar (cap. 39)."]},{"v":34,"t":"Și Iacov și-a sfâșiat hainele și și-a legat sac pe coapse și l-a jelit pe fiul său multe zile."},{"v":35,"t":"Și s-au ridicat toți fiii lui și toate soțiile fiilor lui și s-au dus să-l mângâie, dar el n-a voit să primească mângâiere și a zis: „Căci voi coborî jelind la fiul meu în mormânt.” Și l-a plâns numai Isaac, tatăl lui.","notes":["„mormânt” (bei qevurta): Rosen: „în sălașul morților”. „numai Isaac, tatăl lui”: așa în sursă."]},{"v":36,"t":"Și madianiții l-au vândut în Egipt („Mițrayim”) lui Potifar, dregătorul lui Faraon, căpetenia călăilor.","notes":["Rosen: „Iar medaniții l-au vândut în Egipt”."]}]},{"num":38,"title":"Capitolul 38","verses":[{"v":1,"t":"Și a fost în vremea aceea, Iuda a coborât din averile lui și s-a despărțit de frații lui și s-a abătut la un om adulamit, al cărui nume era Hira.","notes":["Rosen: „Iuda a coborât de la frații săi”; Targumul: „din averile lui”."]},{"v":2,"t":"Și Iuda a văzut acolo fiica unui om negustor, al cărui nume era Șua, și a convertit-o și a intrat la ea."},{"v":3,"t":"Și a rămas însărcinată și a născut un fiu și i-a pus numele Er, căci avea să moară fără copii.","notes":["Targumul explică numele: Er – „fără copii” (ʿariri), Onan – „jale” (aninut), Șela – „a uitat” (șali). Rosen 38:5: „iar Iuda era în Chezib când ea l-a născut”; Targumul înțelege Chezib ca „a încetat”."]},{"v":4,"t":"Și a rămas din nou însărcinată și a născut un fiu și i-a pus numele Onan, căci tatăl lui avea să-l jelească."},{"v":5,"t":"Și a mai născut un fiu și i-a pus numele Șela, căci bărbatul ei o uitase; și ea a încetat să nască după ce l-a născut."},{"v":6,"t":"Și Iuda i-a luat lui Er, întâiul lui născut, o soție, fiica lui Sem cel Mare, și numele ei era Tamar."},{"v":7,"t":"Și Er, întâiul născut al lui Iuda, era rău înaintea Domnului, pentru că nu-și dădea sămânța soției lui; și mânia Domnului s-a aprins împotriva lui, și Domnul l-a ucis."},{"v":8,"t":"Și a zis Iuda către Onan: „Intră la soția fratelui tău și ia-o de soție prin levirat și ridică urmași pe numele fratelui tău.”"},{"v":9,"t":"Și Onan a știut că nu pe numele lui se vor numi fiii; și era, când intra la soția fratelui său, își strica faptele pe pământ, ca să nu ridice fii pe numele fratelui său."},{"v":10,"t":"Și a fost rău înaintea Domnului ce făcea, și i-a tăiat și lui zilele."},{"v":11,"t":"Și a zis Iuda către Tamar, nora lui: „Rămâi văduvă în casa tatălui tău până va crește Șela, fiul meu”, căci a zis: „Să nu moară și el ca frații lui.” Și Tamar s-a dus și a locuit în casa tatălui ei."},{"v":12,"t":"Și s-au înmulțit zilele, și a murit fiica lui Șua, soția lui Iuda; și Iuda s-a mângâiat și a urcat la tunsul oilor lui, el și Hira, prietenul lui, adulamitul, la Timna."},{"v":13,"t":"Și i s-a spus Tamarei, zicându-se: „Iată, socrul tău urcă la Timna să-și tundă oile.”"},{"v":14,"t":"Și și-a scos hainele de văduvie de pe ea și s-a acoperit cu un voal și s-a înfășurat și a șezut la răscrucea drumurilor unde se uită toți ochii, care este pe drumul spre Timna; căci a văzut că Șela crescuse, iar ea nu-i fusese dată de soție.","notes":["Rosen: „la răscrucea care este pe drumul către Timna”; Targumul explică Petaḥ-ʿEinayim („deschiderea ochilor”)."]},{"v":15,"t":"Și Iuda a văzut-o, și i s-a părut în fața lui ca una care iese afară, căci în casa lui Iuda fusese posomorâtă la față, și Iuda nu o iubea.","notes":["Rosen: „și a crezut-o prostituată, pentru că își acoperise fața.” „posomorâtă la față” (keʿisat appin): sensul exact este nesigur; redat literal."]},{"v":16,"t":"Și s-a abătut la ea pe drum și a zis: „Lasă-mă, te rog, să intru la tine”, căci nu știa că este nora lui. Și ea a zis: „Ce-mi vei da ca să intri la mine?”"},{"v":17,"t":"Și el a zis: „Îți voi trimite un ied dintre capre din turmă.” Și ea a zis: „Dacă îmi dai un gaj până îl vei trimite.”"},{"v":18,"t":"Și el a zis: „Ce gaj să-ți dau?” Și ea a zis: „Pecetea ta și șnururile tale și toiagul tău, care este în mâna ta.” Și i le-a dat și a intrat la ea, și a rămas însărcinată cu el."},{"v":19,"t":"Și s-a ridicat și s-a dus și și-a scos voalul de pe ea și s-a îmbrăcat cu hainele văduviei ei."},{"v":20,"t":"Și Iuda a trimis iedul dintre capre prin mâna prietenului lui, adulamitul, ca să ia gajul din mâna femeii; dar nu a găsit-o."},{"v":21,"t":"Și i-a întrebat pe oamenii locului ei, spunând: „Unde este femeia rătăcită care era la locul unde se uită ochii, lângă drum?” Și au zis: „Nu a fost aici nicio femeie rătăcită.”","notes":["„femeia rătăcită” (maṭʿita): Targumul evită cuvântul ebraic qedeșa (Rosen: „prostituată”)."]},{"v":22,"t":"Și s-a întors la Iuda și a zis: „Nu am găsit-o, și chiar oamenii locului au zis: «Nu a fost aici nicio femeie rătăcită».”"},{"v":23,"t":"Și a zis Iuda: „Să-și ia gajurile, ca să nu ajungem de râs; iată, am trimis iedul acesta, iar tu nu ai găsit-o.”"},{"v":24,"t":"Și a fost, după trei luni, s-a recunoscut că este însărcinată; și i s-a spus lui Iuda, zicându-se: „Tamar, nora ta, s-a desfrânat, și iată, a rămas chiar însărcinată din desfrânare.” Și a zis Iuda: „Oare nu este ea fiica unui preot? Scoateți-o și să fie arsă.”"},{"v":25,"t":"Tamar era scoasă ca să fie arsă, și a căutat cele trei gajuri și nu le-a găsit; și-a ridicat ochii spre cerurile de sus și așa a zis: „Te rog, cu îndurare dinaintea Ta, Doamne, răspunde-mi în ceasul acesta al strâmtorării mele și luminează-mi ochii, și voi găsi cei trei martori; și Îți voi ridica din coapsele mele trei sfinți care vor sfinți Numele Tău și vor coborî în cuptorul de foc din valea Dura.” În ceasul acela Sfântul, binecuvântat fie El, i-a făcut semn lui Mihail, și el i-a luminat ochii, și le-a găsit; și le-a luat și le-a aruncat înaintea picioarelor judecătorilor și a zis: „Bărbatul căruia îi aparțin aceste gajuri, de la el sunt însărcinată; și chiar dacă voi fi arsă, nu-l voi da în vileag; dar Stăpânul lumii îi va pune în inimă să le recunoască și mă va scăpa de judecata aceasta mare.” Și când Iuda le-a văzut, le-a recunoscut; atunci a zis în inima lui: „Mai bine pentru mine să fiu rușinat în lumea aceasta, care este o lume trecătoare, decât să fiu rușinat înaintea părinților mei cei drepți în lumea care vine; mai bine pentru mine să fiu ars în lumea aceasta cu foc care se stinge, decât să fiu ars în lumea care vine cu focul care mistuie foc. Este măsură pentru măsură: pentru că i-am zis lui Iacov, tatăl meu: «Recunoaște, te rog, mantaua fiului tău», de aceea trebuie să aud la judecată: «Ale cui sunt pecetea și șnururile și toiagul acestea?»”","notes":["„trei sfinți… valea Dura”: Hanania, Mișael și Azaria (Daniel 3). Rosen: „Identifică, te rog, ale cui sunt pecetea și pelerina și toiagul acestea.”"]},{"v":26,"t":"Și Iuda a recunoscut și a zis: „Tamar este nevinovată; de la mine a rămas însărcinată.” Și un glas ceresc a căzut din ceruri și a zis: „De la Mine a fost lucrul”, și amândoi au fost scăpați de la judecată. Și a zis: „Pentru că nu am dat-o lui Șela, fiul meu, mi s-a întâmplat aceasta.” Și nu a mai cunoscut-o în culcare.","notes":["Rosen: „Are dreptate, este de la mine”."]},{"v":27,"t":"Și a fost, la vremea nașterii ei, și iată, erau gemeni în pântecele ei."},{"v":28,"t":"Și a fost, când năștea, pruncul și-a întins mâna, și moașa a luat și i-a legat de mână un fir stacojiu, spunând: „Acesta a ieșit întâi.”"},{"v":29,"t":"Și a fost, când pruncul și-a tras mâna înapoi, și iată, a ieșit fratele lui; și ea a zis: „Ce putere mare ai avut! Și asupra ta este să fii tare, căci vei moșteni împărăția.” Și i-a pus numele Pereț.","notes":["Rosen: „Ce mai spărtură ți-ai făcut!” și Iuda i-a pus numele Pereț."]},{"v":30,"t":"Și după aceea a ieșit fratele lui, pe a cărui mână era legat firul stacojiu, și i-a pus numele Zerah."}]},{"num":39,"title":"Capitolul 39","verses":[{"v":1,"t":"Și Iosif a fost coborât în Egipt („Mițrayim”), și l-a cumpărat Potifar, pentru că l-a văzut frumos, ca să facă cu el culcare de bărbat; dar îndată s-a hotărât împotriva lui, și i s-au uscat testiculele și a fost castrat. Și el era dregătorul lui Faraon, căpetenia călăilor, un om egiptean, pe garanție, de la arabii care îl coborâseră acolo.","notes":["Rosen: „l-a cumpărat din mâna ismaeliților care îl coborâseră acolo.” „pe garanție” (be-ʿarbanuta): sensul cuvântului în acest loc este nesigur; Targumul îi numește pe ismaeliți „arabi” (vezi 37:25)."]},{"v":2,"t":"Și Cuvântul Domnului a fost în ajutorul lui Iosif, și a fost un om căruia îi izbuteau toate, și era în casa stăpânului său, egipteanul."},{"v":3,"t":"Și stăpânul lui a văzut că Cuvântul Domnului era în ajutorul lui și că tot ce făcea, Domnul îi făcea să izbutească în mâna lui."},{"v":4,"t":"Și Iosif a găsit îndurare în ochii lui și îl slujea; și l-a numit administrator peste casa lui, și tot ce avea l-a dat în mâna lui."},{"v":5,"t":"Și a fost, de când l-a numit administrator peste casa lui și peste tot ce avea, Domnul a binecuvântat casa egipteanului pentru meritul lui Iosif; și binecuvântarea Domnului a fost în tot ce avea, în casă și în câmp."},{"v":6,"t":"Și a lăsat tot ce avea în mâna lui Iosif și nu știa nimic la el, decât pe soția lui, cu care se culca. Și Iosif era frumos la chip și frumos la înfățișare.","notes":["Rosen: „în afară de pâinea pe care o mânca”; Targumul explică „pâinea” ca soția lui."]},{"v":7,"t":"Și a fost după aceste lucruri, soția stăpânului său și-a ridicat ochii spre Iosif și a zis: „Culcă-te cu mine.”"},{"v":8,"t":"Dar el n-a voit să se apropie de ea și a zis soției stăpânului său: „Iată, stăpânul meu nu știe nimic la mine din ce este în casă, și tot ce are a dat în mâna mea."},{"v":9,"t":"Nu este nimeni mai mare în casa aceasta decât mine, și nu mi-a oprit nimic, decât pe tine, pentru că tu ești soția lui; și cum să fac răul acesta mare și să păcătuiesc înaintea Domnului?”"},{"v":10,"t":"Și a fost, când îi vorbea lui Iosif zi de zi, el nu o asculta să se culce cu ea, ca să nu fie vinovat împreună cu ea în ziua judecății celei mari, în lumea care vine."},{"v":11,"t":"Și a fost, în ziua aceasta, a intrat în casă să cerceteze registrele socotelilor lui, și nu era nimeni dintre oamenii casei acolo, în casă.","notes":["Rosen: „el a intrat în casă să-și facă treaba”."]},{"v":12,"t":"Și l-a apucat de haina lui, spunând: „Culcă-te cu mine”; și el și-a lăsat haina în mâna ei și a ieșit afară."},{"v":13,"t":"Și a fost, când a văzut că își lăsase haina în mâna ei și ieșise afară,"},{"v":14,"t":"a aruncat albuș de ou pe pat și i-a chemat pe oamenii casei ei și a zis: „Vedeți sămânța pe care a aruncat-o acesta pe care ni l-a adus stăpânul vostru, un om evreu, ca să-și bată joc de noi: a intrat la mine să se culce cu mine, și am strigat cu glas tare."},{"v":15,"t":"Și a fost, când a auzit că mi-am ridicat glasul și am strigat, și-a lăsat haina lângă mine și a ieșit afară.”"},{"v":16,"t":"Și i-a pus haina lângă ea până a venit stăpânul lui acasă."},{"v":17,"t":"Și i-a vorbit după cuvintele acestea, spunând: „A intrat la mine robul evreu pe care ni l-ai adus, ca să-și bată joc de mine."},{"v":18,"t":"Și a fost, când mi-am ridicat glasul și am strigat, și-a lăsat haina lângă mine și a fugit afară.”"},{"v":19,"t":"Și a fost, când a auzit stăpânul lui cuvintele soției lui, pe care i le-a vorbit, spunând: „Așa mi-a făcut robul tău”, mânia lui s-a aprins."},{"v":20,"t":"Și stăpânul lui Iosif a luat sfat de la preoți, care au cercetat că era albuș de ou, și nu l-a ucis; și l-a pus în temniță, locul unde erau închiși prizonierii regelui; și a fost acolo, în temniță."},{"v":21,"t":"Și Cuvântul Domnului a fost în ajutorul lui Iosif și a întins asupra lui bunătate și i-a dat îndurare în ochii mai-marelui temniței."},{"v":22,"t":"Și mai-marele temniței a dat în mâna lui Iosif pe toți prizonierii care erau în temniță, și tot ce se făcea acolo, el poruncea să se facă."},{"v":23,"t":"Mai-marele temniței nu avea nevoie să-l păzească pe Iosif ca pe toți prizonierii, căci nu vedea nicio vină în mâna lui, pentru că Cuvântul Domnului era în ajutorul lui, și ce făcea, Domnul făcea să izbutească."}]},{"num":40,"title":"Capitolul 40","verses":[{"v":1,"t":"Și a fost după aceste lucruri, și s-a vestit, zicându-se: mai-marele paharnicilor regelui Egiptului („Mițrayim”) și mai-marele brutarilor au greșit și s-au sfătuit să arunce otravă de moarte în mâncarea lui și în băutura lui, ca să-l ucidă pe stăpânul lor, regele Egiptului.","notes":["Rosen: „că paharnicul regelui Egiptului și brutarul au greșit împotriva stăpânului lor”."]},{"v":2,"t":"Și Faraon s-a mâniat, când a auzit, pe cei doi dregători ai lui, pe mai-marele paharnicilor și pe mai-marele brutarilor."},{"v":3,"t":"Și i-a pus sub pază în casa căpeteniei călăilor, în temniță, locul unde era închis Iosif."},{"v":4,"t":"Și căpetenia călăilor l-a rânduit pe Iosif cu ei, și el i-a slujit; și au fost zile în casa de pază."},{"v":5,"t":"Și au visat amândoi un vis, fiecare visul lui, într-o singură noapte, fiecare visul lui și tălmăcirea visului celuilalt, paharnicul și brutarul regelui Egiptului („Mițrayim”), care erau închiși în temniță."},{"v":6,"t":"Și Iosif a venit la ei dimineața și i-a văzut, și iată, erau mâhniți."},{"v":7,"t":"Și i-a întrebat pe dregătorii lui Faraon, care erau cu el în paza casei stăpânului său, spunând: „De ce este înfățișarea feței voastre rea astăzi, mai mult decât în toate zilele în care ați fost aici?”"},{"v":8,"t":"Și i-au zis: „Am visat un vis, și nu este cine să-l tălmăcească.” Și le-a zis Iosif: „Oare nu de la Domnul sunt tălmăcirile viselor? Povestiți-mi, vă rog.”"},{"v":9,"t":"Și mai-marele paharnicilor i-a povestit lui Iosif visul lui și i-a zis: „Vedeam în visul meu, și iată, o viță înaintea mea."},{"v":10,"t":"Și în viță erau trei mlădițe; și ea, când a înflorit, și-a scos mugurii, și îndată i s-au copt ciorchinii, s-au făcut struguri."},{"v":11,"t":"Vedeam până ce mi-au dat paharul lui Faraon în mână, și am luat strugurii și i-am stors în paharul lui Faraon și am dat paharul în mâna lui Faraon.”"},{"v":12,"t":"Și i-a zis Iosif: „Acesta este sfârșitul tălmăcirii visului: cele trei mlădițe sunt cei trei părinți ai lumii, Avraam, Isaac și Iacov, ai căror strănepoți vor fi robiți în Egipt („Mițrayim”) cu lut și cu cărămizi și cu toată munca de pe fața câmpului, și după aceea vor fi răscumpărați prin mâna a trei păstori. Iar ce ai zis: «Am luat strugurii și i-am stors în paharul lui Faraon și am dat paharul în mâna lui Faraon», acesta este potirul mâniei pe care îl va bea Faraon la sfârșit. Iar tu, mai-marele paharnicilor, vei primi plată bună pentru visul tău cel bun pe care l-ai visat; și tălmăcirea lui pentru tine este aceasta: cele trei mlădițe sunt trei zile până la răscumpărarea ta.","notes":["„trei păstori”: Moise, Aaron și Miriam (după tradiție)."]},{"v":13,"t":"La sfârșitul a trei zile va intra pomenirea ta înaintea lui Faraon, și îți va ridica capul cu cinste și te va pune înapoi în slujba ta, și vei da paharul lui Faraon în mâna lui, după rânduiala dintâi, când îi erai paharnic."},{"v":14,"t":"Iosif și-a lăsat încrederea în Cel de sus și și-a pus încrederea într-un om, și a zis mai-marelui paharnicilor: „Numai să-ți amintești de mine când îți va fi bine, și să-mi faci, te rog, un bine și să mă pomenești înaintea lui Faraon și să mă scoți din temnița aceasta."},{"v":15,"t":"Căci am fost furat din țara evreilor, și nici aici n-am făcut nimic rău, ca să mă pună în temniță.”"},{"v":16,"t":"Și mai-marele brutarilor a văzut că tălmăcise bine, căci el văzuse tălmăcirea visului celuilalt; și a început să vorbească în limbaj de mânie și a zis lui Iosif: „Și eu vedeam în visul meu, și iată, trei coșuri de pâine albă pe capul meu.","notes":["Rosen: „erau trei coșuri de nuiele pe capul meu.” „în limbaj de mânie”: sensul expresiei din sursă este nesigur; redat literal."]},{"v":17,"t":"Și în coșul de sus era din toate bunătățile de mâncare ale lui Faraon, lucrare de brutar; și păsările le mâncau din coș, de pe capul meu.”"},{"v":18,"t":"Și Iosif a răspuns și a zis: „Aceasta este tălmăcirea lui: cele trei coșuri sunt trei robii, pe care casa lui Israel va trebui să le îndure; iar tu, mai-marele brutarilor, vei primi plată rea pentru visul tău cel rău pe care l-ai visat.” Căci Iosif i-a tălmăcit ceea ce era plăcut în ochii lui; și i-a zis: „Aceasta este pentru tine tălmăcirea lui: cele trei coșuri sunt trei zile până la uciderea ta."},{"v":19,"t":"La sfârșitul a trei zile Faraon îți va lua cu sabia capul de pe trup și te va spânzura pe lemn, și păsările îți vor mânca carnea de pe tine.”"},{"v":20,"t":"Și a fost, în ziua a treia, ziua de naștere a lui Faraon, el a făcut un ospăț pentru toți slujitorii lui și a ridicat capul mai-marelui paharnicilor și capul mai-marelui brutarilor în mijlocul slujitorilor lui."},{"v":21,"t":"Și l-a pus înapoi pe mai-marele paharnicilor în slujba lui de paharnic, căci s-a aflat că nu fusese în sfatul acela; și el a dat paharul în mâna lui Faraon."},{"v":22,"t":"Iar pe mai-marele brutarilor l-a spânzurat, pentru că se sfătuise să-l ucidă, după cum le tălmăcise Iosif."},{"v":23,"t":"Și pentru că Iosif lăsase bunătatea Celui de sus și se încrezuse în mai-marele paharnicilor, în carne trecătoare, de aceea mai-marele paharnicilor nu și-a amintit de Iosif și l-a uitat, până când a sosit sfârșitul hotărât de Domnul ca să fie răscumpărat.","notes":["Rosen: „Însă căpetenia paharnicilor nu și-a adus aminte de Iosif și l-a uitat.”"]}]},{"num":41,"title":"Capitolul 41","verses":[{"v":1,"t":"A fost: și a fost, la sfârșitul a doi ani, a intrat pomenirea lui Iosif înaintea Cuvântului Domnului. Și Faraon visa, și iată, stătea lângă râu.","notes":["Ediția sursă începe versetul cu cuvântul ebraic al Torei („A fost”), urmat de textul aramaic. Rosen: „Și a fost la sfârșitul a doi ani de zile: și Faraon visa și iată, stătea deasupra Fluviului.”"]},{"v":2,"t":"Și iată, din râu urcau șapte vaci frumoase la vedere și grase la carne, și pășteau în mijlocul stufărișului."},{"v":3,"t":"Și iată, alte șapte vaci urcau din râu, rele la vedere și slabe la carnea lor, și au stat în fața vacilor, pe malul râului."},{"v":4,"t":"Și vacile cele rele la vedere și slabe la carnea lor au mâncat cele șapte vaci frumoase la vedere și grase; și Faraon s-a trezit din somnul lui."},{"v":5,"t":"Și a adormit și a văzut un al doilea vis, și iată, șapte spice urcau pe o singură tulpină, grase și bune."},{"v":6,"t":"Și iată, șapte spice slabe și pârjolite de vântul de răsărit răsăreau după ele."},{"v":7,"t":"Și spicele cele slabe au înghițit cele șapte spice grase și pline; și Faraon s-a trezit, și iată, era un vis."},{"v":8,"t":"Și a fost dimineața, și duhul lui era tulburat; și a trimis și i-a chemat pe toți vrăjitorii egiptenilor și pe toți înțelepții lor, și Faraon le-a povestit visele lui; dar n-a fost cu putință pentru niciun om să-l tălmăcească, căci de la Domnul fusese pricinuit aceasta, pentru că sosise vremea lui Iosif să iasă din temniță."},{"v":9,"t":"Și mai-marele paharnicilor a vorbit înaintea lui Faraon, zicând: „Păcatele mele le pomenesc eu astăzi."},{"v":10,"t":"De la Domnul a fost pricinuit ca Faraon să se mânie pe slujitorii lui; și m-a pus sub pază în casa căpeteniei călăilor, pe mine și pe mai-marele brutarilor."},{"v":11,"t":"Și am visat un vis într-o singură noapte, eu și el; fiecare visul lui și tălmăcirea visului celuilalt am visat."},{"v":12,"t":"Și acolo, cu noi, era un tânăr evreu, rob al căpeteniei călăilor; și i-am povestit, și ne-a tălmăcit visele; fiecăruia după tălmăcirea visului lui i-a tălmăcit."},{"v":13,"t":"Și a fost: cum ne-a tălmăcit, așa a fost; pe mine m-a pus înapoi, prin cuvântul lui, în rânduiala slujbei mele, iar pe el l-a spânzurat.”","notes":["„prin cuvântul lui” (be-mileh): sensul exact din sursă este nesigur; redat literal."]},{"v":14,"t":"Și Faraon a trimis și l-a chemat pe Iosif, și l-au scos în grabă din temniță; și l-a bărbierit, și și-a schimbat hainele și a intrat la Faraon."},{"v":15,"t":"Și Faraon i-a zis lui Iosif: „Un vis am visat, și nu este cine să-l tălmăcească; și eu am auzit despre tine spunându-se că, dacă auzi un vis, tu îl tălmăcești.”"},{"v":16,"t":"Și Iosif i-a răspuns lui Faraon, zicând: „Nu de la mine: nu este om care să tălmăcească vise; ci de la Domnul i se va răspunde lui Faraon cu pace.”"},{"v":17,"t":"Și Faraon a vorbit cu Iosif, zicând: „Vedeam în visul meu: iată, eu stăteam pe malul râului."},{"v":18,"t":"Și iată, din râu urcau șapte vaci grase la carne și frumoase la vedere, și pășteau în mijlocul stufărișului."},{"v":19,"t":"Și iată, alte șapte vaci urcau după ele, slabe și foarte rele la vedere și sărace la carnea lor; n-am văzut ca ele de rele în toată țara Egiptului („Mițrayim”)."},{"v":20,"t":"Și vacile cele slabe și rele au mâncat cele dintâi șapte vaci, cele grase."},{"v":21,"t":"Și au intrat în măruntaiele lor, dar nu se cunoștea că intraseră în măruntaiele lor, și înfățișarea lor era rea, ca la început; și m-am trezit."},{"v":22,"t":"Și am văzut în visul meu, și iată, șapte spice urcau pe o singură tulpină, pline și bune."},{"v":23,"t":"Și iată, șapte spice seci, slabe, pârjolite de vântul de răsărit, răsăreau după ele."},{"v":24,"t":"Și spicele cele slabe au înghițit cele șapte spice bune; și le-am spus vrăjitorilor, dar nu este cine să mi-l lămurească.”"},{"v":25,"t":"Și Iosif i-a zis lui Faraon: „Visul lui Faraon este unul; ceea ce Domnul urmează să facă i-a vestit lui Faraon."},{"v":26,"t":"Cele șapte vaci bune, șapte ani vestesc ele; și cele șapte spice bune, acești șapte ani vestesc ele: visul este unul."},{"v":27,"t":"Și cele șapte vaci slabe și rele care urcau după ele, alți șapte ani vestesc ele; și cele șapte spice slabe, pârjolite de vântul de răsărit, așa vestesc ele: că vor fi șapte ani de foamete."},{"v":28,"t":"Acesta este cuvântul pe care l-am vorbit cu Faraon: ceea ce Domnul urmează să facă i-a arătat lui Faraon."},{"v":29,"t":"Iată, vin șapte ani, belșug mare în toată țara Egiptului („Mițrayim”)."},{"v":30,"t":"Și se vor ridica după ei șapte ani de foamete, și va fi uitat tot belșugul care a fost în țara Egiptului („Mițrayim”), și foametea îi va nimici pe locuitorii țării."},{"v":31,"t":"Și nu se va cunoaște belșugul care a fost în țară din pricina foametei aceleia care va fi după aceea, căci va fi foarte grea."},{"v":32,"t":"Și pentru că visul i s-a repetat lui Faraon de două ori, este pentru că lucrul este întărit de la Domnul, și Domnul se grăbește să-l facă."},{"v":33,"t":"Și acum, să vadă Faraon un bărbat priceput și înțelept și să-l numească peste țara Egiptului („Mițrayim”)."},{"v":34,"t":"Să facă Faraon și să numească supraveghetori peste țară, și să scoată una din cinci din tot grânul țării Egiptului („Mițrayim”) în cei șapte ani de belșug."},{"v":35,"t":"Și să strângă tot grânul acestor ani buni care vin, și să adune grânul sub mâna supraveghetorilor lui Faraon, și să pună grânul în cetăți și să-l păzească."},{"v":36,"t":"Și grânul să fie ascuns în peșteri, în țară, ca hrană din el în cei șapte ani de foamete care vor fi în țara Egiptului („Mițrayim”), ca poporul țării să nu piară de foamete.”"},{"v":37,"t":"Și lucrul a fost plăcut înaintea lui Faraon și înaintea tuturor slujitorilor lui."},{"v":38,"t":"Și Faraon a zis slujitorilor lui: „Vom găsi oare un om ca acesta, în care este duh de profeție de la Domnul?”"},{"v":39,"t":"Și Faraon i-a zis lui Iosif: „După ce Domnul ți-a făcut cunoscute toate acestea, nu este nimeni priceput și înțelept ca tine."},{"v":40,"t":"Tu vei fi supraveghetor peste casa mea, și după hotărârea cuvântului gurii tale se va hrăni tot poporul meu; numai cu tronul domniei voi fi mai mare decât tine.”","notes":["„se va hrăni” (yitzanun): poate fi înțeles și „se va înarma”."]},{"v":41,"t":"Și Faraon i-a zis lui Iosif: „Vezi, te-am numit dregător peste toată țara Egiptului („Mițrayim”).”"},{"v":42,"t":"Și Faraon și-a scos inelul de pe mâna lui și l-a pus pe mâna lui Iosif, și l-a îmbrăcat cu haine de in subțire și i-a pus un lanț de aur la gât."},{"v":43,"t":"Și l-a pus să călărească în carul al doilea al lui Faraon, și aduceau laude înaintea lui: „Acesta este tatăl regelui, mare în înțelepciune și fraged în ani!” Și l-a numit dregător peste toată țara Egiptului („Mițrayim”).","notes":["Rosen: „au proclamat înaintea lui: „Îngenunchiați!”” Targumul explică avrekh ca „tată (av) al regelui, fraged (rakh) în ani”."]},{"v":44,"t":"Și Faraon i-a zis lui Iosif: „Eu sunt Faraon regele, iar tu ești căpetenia (alqafṭa); și fără cuvântul tău niciun om nu-și va ridica mâna ca să-și încingă armele, nici piciorul ca să încalece pe cal, în toată țara Egiptului („Mițrayim”).”","notes":["alqafṭa: titlu de mare dregător; Rosen: „Eu sunt Faraon; și fără încuviințarea ta niciun om nu-și va ridica mâna sau piciorul în toată țara Egiptului.”"]},{"v":45,"t":"Și Faraon i-a pus lui Iosif numele „Bărbatul care descoperă cele ascunse”, și i-a dat de soție pe Asenat, pe care Dina o născuse lui Sihem și pe care o crescuse soția lui Poti-Fera, mai-marele din Tanis; și Iosif a ieșit stăpânitor peste țara Egiptului („Mițrayim”).","notes":["Rosen: „Faraon i-a pus lui Iosif numele Țafnat-Paneah și i-a dat de soție pe Asenat, fiica lui Poti-Fera, preotul lui On”. Targumul explică numele Țafnat-Paneah și o face pe Asenat fiica Dinei și a lui Sihem, crescută în casa lui Poti-Fera; On = Tanis."]},{"v":46,"t":"Și Iosif era de treizeci de ani când a stat înaintea lui Faraon, regele Egiptului („Mițrayim”); și Iosif a ieșit de la Faraon și a trecut, mare și stăpânitor, prin toată țara Egiptului."},{"v":47,"t":"Și țara a rodit: fiecare spic a făcut cât umplu doi pumni, în cei șapte ani de belșug, până ce s-au umplut toate grânarele."},{"v":48,"t":"Și a strâns tot grânul celor șapte ani de belșug care au fost în țara Egiptului („Mițrayim”) și a pus grânul în cetăți; grânul câmpurilor cetății, care erau de jur împrejurul ei, l-a strâns înăuntrul ei.","notes":["În ediția sursă lipsește versetul 41:49; numerotarea urmează sursa."]},{"v":50,"t":"Și lui Iosif i s-au născut doi fii înainte să vină anul foametei, pe care i i-a născut Asenat, care fusese crescută în casa lui Poti-Fera, mai-marele din Tanis."},{"v":51,"t":"Și Iosif i-a pus întâiului-născut numele Manase, căci: „Domnul m-a făcut să uit toată osteneala mea și toată casa tatălui meu.”"},{"v":52,"t":"Și celui de-al doilea i-a pus numele Efraim, căci a zis: „Domnul m-a întărit în țara suferinței mele, și tot așa va fi întărită casa tatălui meu aici, în suferințele lor.”"},{"v":53,"t":"Și s-au sfârșit cei șapte ani de belșug care au fost în țara Egiptului („Mițrayim”)."},{"v":54,"t":"Și au început să vină cei șapte ani de foamete, cum spusese Iosif; și a fost foamete în toate țările, dar în toată țara Egiptului („Mițrayim”) era pâine."},{"v":55,"t":"Și toată țara Egiptului („Mițrayim”) a flămânzit, căci nu scotea grâne; și poporul a strigat înaintea lui Faraon pentru pâine, și Faraon le-a zis tuturor egiptenilor: „Mergeți la Iosif; ce vă va spune, să faceți.”"},{"v":56,"t":"Și foametea era peste toată fața țării; și Iosif a deschis toate grânarele în care era grâu și le-a vândut egiptenilor; și foametea s-a întărit în țara Egiptului („Mițrayim”)."},{"v":57,"t":"Și toți locuitorii țării au venit în Egipt („Mițrayim”) să cumpere grâne de la Iosif, căci foametea se întărise în toată țara."}]},{"num":42,"title":"Capitolul 42","verses":[{"v":1,"t":"Și Iacov a văzut că neguțătorii cumpărau și aduceau grâne din Egipt („Mițrayim”); și Iacov le-a zis fiilor lui: „De ce vă temeți să coborâți în Egipt?”","notes":["Rosen: „De ce vă faceți remarcați?” Targumul redă: „De ce vă temeți să coborâți în Egipt?”"]},{"v":2,"t":"Și a zis: „Iată, am auzit că se vând grâne în Egipt („Mițrayim”); coborâți acolo și cumpărați-ne de acolo, ca să trăim și să nu murim.”"},{"v":3,"t":"Și frații lui Iosif, zece, au coborât să cumpere grâne din Egipt („Mițrayim”)."},{"v":4,"t":"Dar pe Beniamin, fratele lui Iosif, Iacov nu l-a trimis cu frații lui, căci a zis: „Iată, el este tânăr, și mă tem să nu-l întâmpine moartea.”"},{"v":5,"t":"Și fiii lui Israel au venit, fiecare pe câte o poartă, ca să nu-i stăpânească ochiul cel rău când ar intra împreună să cumpere, printre canaaniții care veneau să cumpere; căci era foamete în țara Canaanului."},{"v":6,"t":"Și Iosif era stăpânitor peste țară; și știa că frații lui vor veni să cumpere; a pus paznici la porțile cetății, ca să scrie pe oricine intra în ziua aceea: numele lui și numele tatălui lui. Și el vindea grâne la tot poporul țării. Și frații lui Iosif au venit și au căutat pe ulițe și prin piețe și prin hanuri, și nu l-au găsit; și au intrat în casa lui și s-au plecat înaintea lui cu fața la pământ."},{"v":7,"t":"Și Iosif i-a văzut pe frații lui și i-a recunoscut, și s-a făcut în ochii lor ca un străin și le-a vorbit cuvinte aspre și le-a zis: „De unde ați venit?” Și ei au zis: „Din țara Canaanului, să cumpărăm grâne.”"},{"v":8,"t":"Și Iosif și-a recunoscut frații, căci, când se despărțise de ei, ei aveau semn de barbă; dar ei nu l-au recunoscut, căci el nu avea semn de barbă, iar în ceasul acela avea."},{"v":9,"t":"Și Iosif și-a amintit visele pe care le visase despre ei și le-a zis: „Iscoade sunteți! Să vedeți goliciunea rătăcirii țării ați venit!”","notes":["„goliciunea rătăcirii țării” (ʿeryat maṭʿayat arʿa): sensul exact este nesigur (probabil „locurile neapărate ale țării”); redat literal. Rosen: „Să vedeți goliciunea țării ați venit!”"]},{"v":10,"t":"Și i-au zis: „Nu, stăpâne; slujitorii tăi au venit să cumpere grâne."},{"v":11,"t":"Noi toți suntem fiii unui singur om; suntem cinstiți; slujitorii tăi n-au fost iscoade.”"},{"v":12,"t":"Și le-a zis: „Nu; ci goliciunea rătăcirii țării ați venit s-o vedeți.”"},{"v":13,"t":"Și au zis: „Noi, slujitorii tăi, suntem doisprezece frați, fiii unui singur om în țara Canaanului; și iată, cel mic este astăzi cu tatăl nostru, iar unul a plecat de la noi și nu știm ce s-a întâmplat la sfârșitul lui.”"},{"v":14,"t":"Și Iosif le-a zis: „Este ceea ce v-am vorbit, zicând: «Iscoade sunteți!»"},{"v":15,"t":"Prin aceasta veți fi încercați: pe viața lui Faraon, nu veți ieși de aici decât dacă va veni aici fratele vostru cel mic."},{"v":16,"t":"Trimiteți dintre voi pe unul să-l aducă pe fratele vostru, iar voi veți fi legați, și se vor încerca vorbele voastre, dacă adevărul este cu voi; iar dacă nu, pe viața lui Faraon, sunteți iscoade!”"},{"v":17,"t":"Și i-a strâns în casa de pază trei zile."},{"v":18,"t":"Și Iosif le-a zis în ziua a treia: „Faceți aceasta și rămâneți în viață: de Domnul mă tem eu."},{"v":19,"t":"Dacă sunteți cinstiți, unul din frații voștri să fie legat în casa voastră de pază, iar voi mergeți, duceți grânele pe care le-ați cumpărat pentru cei flămânzi din casele voastre."},{"v":20,"t":"Și pe fratele vostru cel mic aduceți-l la mine, și se vor adeveri vorbele voastre și nu veți muri.” Și au făcut așa."},{"v":21,"t":"Și au zis unul către altul: „Cu adevărat suntem vinovați pentru fratele nostru, căci am văzut strâmtorarea sufletului lui când ne implora, și nu l-am ascultat; de aceea a venit asupra noastră necazul acesta.”"},{"v":22,"t":"Ruben le-a răspuns și a zis: „Nu v-am spus eu, zicând: «Nu păcătuiți față de băiat»? Și nu m-ați ascultat; și iată, și sângele lui se cere de la noi.”"},{"v":23,"t":"Și ei nu știau că Iosif înțelegea limba Casei Sfințeniei, căci Manase era tălmaci între ei.","notes":["„limba Casei Sfințeniei”: limba ebraică. Rosen: „căci între ei era tălmaciul.” Targumul îl identifică pe tălmaci cu Manase."]},{"v":24,"t":"Și s-a întors de la ei și a plâns; și s-a întors la ei și le-a vorbit, și l-a luat dintre ei pe Simeon, care se sfătuise să-l ucidă, și l-a legat înaintea lor."},{"v":25,"t":"Și Iosif a poruncit slujitorilor lui, și au umplut vasele lor cu grâne, și să le pună înapoi argintul, al fiecăruia în sacul lui, și să le dea merinde pentru drum; și le-a făcut așa."},{"v":26,"t":"Și și-au ridicat grânele pe măgarii lor și au plecat de acolo."},{"v":27,"t":"Și Levi, care rămăsese singur, fără Simeon, tovarășul lui, și-a deschis sacul ca să dea nutreț măgarului lui la han, și și-a văzut argintul, și iată, era la gura poverii lui.","notes":["Rosen: „Unul și-a deschis sacul”; Targumul îl identifică cu Levi."]},{"v":28,"t":"Și a zis fraților lui: „Mi s-a întors argintul, și iată, este chiar în povara mea.” Și i-a părăsit mintea, și s-au uimit unul către altul, zicând: „Ce este aceasta pe care ne-a făcut-o Domnul, și nu pentru vina noastră?”"},{"v":29,"t":"Și au venit la Iacov, tatăl lor, în țara Canaanului și i-au povestit tot ce li se întâmplase, zicând:"},{"v":30,"t":"„Omul, stăpânul țării, ne-a vorbit cuvinte aspre și ne-a disprețuit ca pe niște iscoade ale țării."},{"v":31,"t":"Și i-am zis: «Suntem cinstiți, n-am fost iscoade."},{"v":32,"t":"Doisprezece frați suntem, fiii unui singur tată; nu știm ce s-a întâmplat la sfârșitul lui, iar cel mic este astăzi cu tatăl nostru în țara Canaanului.»"},{"v":33,"t":"Și omul, stăpânul țării, ne-a zis: «Prin aceasta voi ști că sunteți cinstiți: lăsați-l cu mine pe unul din frații voștri, iar ce trebuie pentru foametea caselor voastre luați și mergeți."},{"v":34,"t":"Și aduceți-l la mine pe fratele vostru cel mic, și voi ști că nu sunteți iscoade, ci că sunteți cinstiți; pe fratele vostru vi-l voi da, iar în țară veți face negoț cu mărfuri.»”"},{"v":35,"t":"Și a fost, pe când își goleau sacii, iată, fiecare avea legătura argintului lui în sacul lui; și au văzut legăturile argintului lor, ei și tatăl lor, și s-au temut pentru Simeon, pe care îl lăsaseră acolo."},{"v":36,"t":"Și Iacov, tatăl lor, le-a zis: „Pe mine m-ați lipsit de copii: despre Iosif ați zis: «L-a mâncat o fiară rea»; și despre Simeon ați zis: «Regele țării l-a legat»; și pe Beniamin vreți să-l luați. Asupra mea a venit strâmtorarea tuturor acestora.”"},{"v":37,"t":"Și Ruben i-a zis tatălui lui, zicând: „Pe cei doi fii ai mei să-i omori prin anatemă, dacă nu ți-l aduc; dă-l în mâinile mele și eu ți-l voi aduce înapoi.”","notes":["„prin anatemă” (be-šamta): sensul exact al expresiei este nesigur; redat literal."]},{"v":38,"t":"Și a zis: „Fiul meu nu va coborî cu voi, căci fratele lui a murit, și el singur a rămas de la mama lui; și dacă îl va întâmpina moartea pe drumul pe care veți merge, veți coborî bătrânețea mea cu durere la casa mormântului.”"}]},{"num":43,"title":"Capitolul 43","verses":[{"v":1,"t":"Și foametea era grea în țară."},{"v":2,"t":"Și a fost, când au isprăvit de mâncat grânele pe care le aduseseră din Egipt („Mițrayim”), tatăl lor le-a zis: „Întoarceți-vă, cumpărați-ne puține grâne.”"},{"v":3,"t":"Și Iuda i-a zis, spunând: „Omul ne-a mărturisit cu tărie, zicând: «Să nu vedeți fața mea dacă fratele vostru cel mic nu este cu voi.»"},{"v":4,"t":"Dacă îl trimiți pe fratele nostru cu noi, vom coborî și îți vom cumpăra grâne."},{"v":5,"t":"Iar dacă nu-l trimiți, nu vom coborî, căci omul ne-a zis: «Să nu vedeți fața mea dacă fratele vostru nu este cu voi.»”"},{"v":6,"t":"Și Israel a zis: „De ce mi-ați făcut rău, spunându-i omului că mai aveți un frate?”"},{"v":7,"t":"Și au zis: „Omul ne-a întrebat cu stăruință despre noi și despre neamul nostru, zicând: «Mai trăiește tatăl vostru? Aveți un frate?» Și i-am spus după cuvântul acestor vorbe. Puteam oare să știm că va zice: «Coborâți-l pe fratele vostru»?”"},{"v":8,"t":"Și Iuda i-a zis lui Israel, tatăl lui: „Trimite băiatul cu mine, și să ne sculăm și să mergem, ca să trăim și să nu murim, și noi, și tu, și pruncii noștri."},{"v":9,"t":"Eu sunt chezaș pentru el; din mâna mea să-l ceri. Dacă nu ți-l aduc și nu-l pun înaintea ta, voi fi vinovat înaintea ta în toate zilele."},{"v":10,"t":"Căci dacă n-am fi zăbovit, până acum ne-am fi întors de două ori.”"},{"v":11,"t":"Și Israel, tatăl lor, le-a zis: „Dacă este așa, faceți aceasta: luați din ce este lăudat în țară în vasele voastre și coborâți-i omului un dar: puțină rășină de balsam și puțină miere de ceară și lotus, ulei de fistic și ulei de migdale.","notes":["„miere de ceară”: sensul exact al expresiei din sursă este nesigur (poate miere în fagure); redat literal."]},{"v":12,"t":"Și argint îndoit luați în mâinile voastre; iar argintul care v-a fost pus înapoi la gura poverilor voastre duceți-l înapoi în mâinile voastre; poate a fost din greșeală."},{"v":13,"t":"Și pe fratele vostru luați-l, și sculați-vă, întoarceți-vă la om."},{"v":14,"t":"Și Dumnezeul Atotputernic să vă dea îndurare înaintea omului, ca să vi-l slobozească pe celălalt frate al vostru și pe Beniamin. Iar eu, iată, mi s-a vestit deja prin duhul sfințeniei că, dacă am rămas lipsit de Iosif, voi rămâne lipsit și de Simeon și de Beniamin.”"},{"v":15,"t":"Și oamenii au luat darul acesta, și argint îndoit au luat în mâinile lor, și l-au luat pe Beniamin; și au coborât în Egipt („Mițrayim”) și au stat înaintea lui Iosif."},{"v":16,"t":"Și Iosif l-a văzut pe Beniamin cu ei și i-a zis lui Manase, care era numit supraveghetor peste casa lui: „Du-i pe oameni în casă, și deschide casa de înjunghiere, și scoate vâna coapsei, și pregătește mâncarea înaintea lor, căci cu mine vor mânca oamenii la vremea prânzului de amiază.”","notes":["Rosen: „i-a spus celui care era peste casa lui”; Targumul îl identifică cu Manase. „vâna coapsei”: nervul sciatic (vezi 32:33)."]},{"v":17,"t":"Și omul a făcut cum zisese Iosif, și omul i-a dus pe oameni în casa lui Iosif."},{"v":18,"t":"Și oamenii s-au temut că au fost duși în casa lui Iosif și au zis: „Din pricina argintului care s-a întors în poverile noastre data trecută suntem duși, ca să se ridice cu vicleșug împotriva noastră și să ne judece și să ne ia ca robi, și să ne ia măgarii.”"},{"v":19,"t":"Și s-au apropiat de omul care era numit supraveghetor peste casa lui Iosif și i-au vorbit la ușa casei."},{"v":20,"t":"Și au zis: „Rogu-te, stăpâne, am coborât data trecută să cumpărăm grâne."},{"v":21,"t":"Și a fost, când am ajuns la han și ne-am deschis poverile, iată, argintul fiecăruia era la gura poverii lui, argintul nostru după greutatea lui; și l-am adus înapoi în mâinile noastre."},{"v":22,"t":"Și alt argint am coborât în mâinile noastre ca să cumpărăm grâne; nu știm cine ne-a pus argintul în poverile noastre.”"},{"v":23,"t":"Și a zis: „Pace vouă din partea stăpânului meu, nu vă temeți: Dumnezeul vostru și Dumnezeul tatălui vostru v-a dat o comoară în poverile voastre; argintul vostru a venit la mine.” Și l-a scos la ei pe Simeon."},{"v":24,"t":"Și omul i-a dus pe oameni în casa lui Iosif și a dat apă, și și-au spălat picioarele, și a dat nutreț măgarilor lor."},{"v":25,"t":"Și au pregătit darul până la venirea lui Iosif, la prânzul de amiază, căci auziseră de la el că acolo vor mânca pâine."},{"v":26,"t":"Și Iosif a intrat în casă, și i-au adus în casă darul care era în mâinile lor și s-au plecat înaintea lui până la pământ."},{"v":27,"t":"Și i-a întrebat de pace și a zis: „Este în pace tatăl vostru, bătrânul despre care mi-ați vorbit? Mai trăiește?”"},{"v":28,"t":"Și au zis: „Pace slujitorului tău, tatăl nostru; încă trăiește.” Și s-au înclinat și s-au plecat."},{"v":29,"t":"Și și-a ridicat ochii și l-a văzut pe Beniamin, fratele lui, fiul mamei lui, și a zis: „Acesta este fratele vostru cel mic, despre care mi-ați vorbit?” Și a zis: „De la Domnul să ți se facă milă, fiul meu.”"},{"v":30,"t":"Și Iosif s-a grăbit, căci i se înfierbântase mila pentru fratele lui și voia să plângă; și a intrat în odaia de dormit și a plâns acolo."},{"v":31,"t":"Și și-a spălat fața de lacrimi și a ieșit, și s-a stăpânit și a zis: „Puneți pâinea.”"},{"v":32,"t":"Și i-au pus lui deosebi, și lor deosebi, și egiptenilor care mâncau cu el deosebi; căci nu le este îngăduit egiptenilor să mănânce pâine cu iudeii, pentru că animalul de care se tem egiptenii îl mănâncă iudeii.","notes":["Rosen: „căci egiptenii nu puteau să ia masa cu evreii, căci aceasta era o oroare pentru egipteni.”"]},{"v":33,"t":"Și i-au așezat înaintea lui, pe cel mare după rânduiala întâietății lui și pe cel mic după rânduiala tinereții lui. Și el ținea în mână paharul de argint și bătea în el ca unul care ghicește, și a așezat pe fiii Leei de o parte, și pe fiii Zilpei de o parte, și pe fiii Bilhei de o parte, iar pe Beniamin, fiul Rahelei, l-a așezat lângă el; și oamenii se mirau unul către altul.","notes":["Rosen: „întâiul-născut după vârsta sa și mezinul după tinerețea sa; și oamenii se uitau unii la alții cu uimire.”"]},{"v":34,"t":"Și a ridicat porții de pe masa lui și le-a trimis de dinaintea lui înaintea lor; și porția lui Beniamin a fost mai mare decât porțiile tuturor, cinci porții: o porție a lui, o porție de la el, o porție de la soția lui și două porții de la cei doi fii ai lui. Și au băut și s-au îmbătat cu el, căci din ziua în care se despărțiseră de el nu băuseră vin, nici el, nici ei, până în ziua aceea.","notes":["În sursă, „o porție de la el” se referă la Iosif. Rosen: „Ei au băut și s-au îmbătat cu el.”"]}]},{"num":44,"title":"Capitolul 44","verses":[{"v":1,"t":"Și i-a poruncit lui Manase, care era numit supraveghetor peste casa lui, zicând: „Umple sacii oamenilor cu grâne, cât pot duce, și pune argintul fiecăruia la gura poverii lui.","notes":["Rosen: „Apoi a poruncit celui care era mai-mare peste casa sa”; Targumul îl identifică cu Manase (la fel la 44:4)."]},{"v":2,"t":"Și cupa mea, cupa de argint, pune-o la gura poverii celui mic, împreună cu argintul grânelor lui.” Și a făcut după cuvântul pe care îl vorbise Iosif."},{"v":3,"t":"Dimineața s-a luminat, și oamenii au fost lăsați să plece, ei și măgarii lor."},{"v":4,"t":"Ei ieșiseră din cetate, nu se depărtaseră, și Iosif i-a zis lui Manase, care era numit supraveghetor peste casa lui: „Scoală-te, aleargă după oameni, și să-i ajungi și să le zici: «De ce ați răsplătit binele cu rău?"},{"v":5,"t":"Oare nu este aceasta din care bea stăpânul meu și cu care el ghicește întruna? Rău ați făcut ce ați făcut.»”"},{"v":6,"t":"Și i-a ajuns și le-a vorbit toate cuvintele acestea."},{"v":7,"t":"Și i-au zis: „De ce vorbește stăpânul meu cuvinte ca acestea? Departe fie de slujitorii tăi să facă un lucru ca acesta!"},{"v":8,"t":"Iată, argintul pe care l-am găsit la gura poverilor noastre ți l-am adus înapoi din țara Canaanului; și cum am putea fura din casa stăpânului tău vase de argint sau vase de aur?"},{"v":9,"t":"Acela dintre slujitorii tăi la care se va găsi să fie vinovat de moarte, și chiar noi vom fi robi stăpânului meu.”"},{"v":10,"t":"Și a zis: „Și acum, după cuvintele voastre așa să fie: cel la care se va găsi să-mi fie rob, iar voi veți fi nevinovați.”"},{"v":11,"t":"Și s-au grăbit și și-au coborât fiecare povara la pământ și și-au deschis fiecare povara."},{"v":12,"t":"Și a cercetat: cu Ruben a început și cu Beniamin a sfârșit; și cupa s-a găsit în povara lui Beniamin.","notes":["Rosen: „a început cu cel mai mare și a isprăvit cu cel mai tânăr”."]},{"v":13,"t":"Și și-au sfâșiat hainele, și li s-a dat tărie de vitejie, și și-au încărcat fiecare măgarul și s-au întors în cetate."},{"v":14,"t":"Și Iuda și frații lui au intrat în casa lui Iosif, iar el era încă acolo; și au căzut înaintea lui la pământ."},{"v":15,"t":"Și Iosif le-a zis: „Ce faptă este aceasta pe care ați făcut-o? Nu știați că un om ca mine ghicește cu adevărat?”"},{"v":16,"t":"Și Iuda a zis: „Ce să-i spunem stăpânului meu despre argintul dintâi, și ce să vorbim despre argintul de pe urmă, și cum să ne dezvinovățim pentru cupă? De la Domnul s-a găsit vina asupra slujitorilor tăi. Iată, suntem robi ai stăpânului meu, și noi, și cel în mâna căruia s-a găsit potirul.”","notes":["Sursa folosește aici două cuvinte diferite: „cupa” (ʾugbin) și „potirul” (kelida)."]},{"v":17,"t":"Și a zis: „Departe fie de mine să fac aceasta! Omul în mâna căruia s-a găsit potirul, acela să-mi fie rob, iar voi suiți-vă în pace la tatăl vostru.”"},{"v":18,"t":"S-a apropiat: și Iuda a venit lângă el și a zis: „Rogu-te, stăpâne, să vorbească, rogu-te, slujitorul tău un cuvânt în auzul stăpânului meu, și să nu se aprindă mânia ta asupra slujitorului tău; căci din ceasul în care am venit la tine ne spuneai: «De Domnul mă tem eu», iar acum judecățile tale s-au întors să fie asemenea cu ale mai-marilor lui Faraon.","notes":["Rosen: „căci tu ești ca Faraon.”","Ediția sursă începe versetul cu cuvântul ebraic al Torei („S-a apropiat”), urmat de textul aramaic."]},{"v":19,"t":"Stăpânul meu i-a întrebat pe slujitorii lui, zicând: «Aveți tată sau frate?»"},{"v":20,"t":"Și i-am zis stăpânului meu: «Avem un tată bătrân și un fiu al bătrâneților, mic; și fratele lui a murit, și el singur a rămas de la mama lui, și de aceea tatăl lui îl iubește.»"},{"v":21,"t":"Și le-ai zis slujitorilor tăi: «Coborâți-l la mine, și îmi voi pune ochii spre bine asupra lui.»"},{"v":22,"t":"Și i-am zis stăpânului meu: «Nu este cu putință ca băiatul să-și părăsească tatăl, căci, dacă își părăsește tatăl, acesta va muri.»"},{"v":23,"t":"Și le-ai zis slujitorilor tăi: «Dacă fratele vostru cel mic nu coboară cu voi, să nu mai vedeți fața mea.»"},{"v":24,"t":"Și a fost, când ne-am suit la slujitorul tău, tatăl meu, i-am spus cuvintele stăpânului meu."},{"v":25,"t":"Și tatăl nostru a zis: «Întoarceți-vă, cumpărați-ne puține grâne.»"},{"v":26,"t":"Și am zis: «Nu ne este cu putință să coborâm; dacă fratele nostru cel mic este cu noi, vom coborî, căci nu ne este cu putință să vedem fața omului dacă fratele nostru cel mic nu este cu noi.»"},{"v":27,"t":"Și slujitorul tău, tatăl meu, ne-a zis: «Voi știți că doi fii mi-a născut soția mea."},{"v":28,"t":"Și unul a ieșit de la mine, și am zis: ‘Cu adevărat a fost ucis’, și nu l-am mai văzut până acum.","notes":["Rosen: „‘Vai, cu siguranță a fost sfâșiat’”."]},{"v":29,"t":"Și dacă îl luați și pe acesta dinaintea mea și îl întâmpină moartea, veți coborî bătrânețea mea cu durere la casa mormântului.»"},{"v":30,"t":"Și acum, când voi veni la slujitorul tău, tatăl meu, și băiatul nu este cu noi, iar sufletul lui îi este drag ca sufletul lui,"},{"v":31,"t":"va fi că, atunci când va vedea că băiatul nu este, va muri; și slujitorii tăi vor coborî bătrânețea slujitorului tău, tatăl nostru, cu durere la casa mormântului."},{"v":32,"t":"Căci slujitorul tău s-a pus chezaș pentru băiat înaintea tatălui meu, zicând: «Dacă nu ți-l aduc, voi fi vinovat înaintea tatălui meu în toate zilele.»"},{"v":33,"t":"Și acum, să rămână, rogu-te, slujitorul tău în locul băiatului, rob la stăpânul meu, iar băiatul să se suie cu frații lui."},{"v":34,"t":"Căci cum mă voi sui la tatăl meu, dacă băiatul nu este cu mine? Ca nu cumva să văd răul care îl va lovi pe tatăl meu.”"}]},{"num":45,"title":"Capitolul 45","verses":[{"v":1,"t":"Și Iosif n-a putut să îndure să nu plângă, din pricina tuturor celor care stăteau înaintea lui; și a zis: „Scoateți pe toți oamenii dinaintea mea!” Și n-a rămas nimeni cu el când Iosif s-a făcut cunoscut fraților lui."},{"v":2,"t":"Și și-a ridicat glasul cu plâns, și au auzit egiptenii și au auzit oamenii casei lui Faraon."},{"v":3,"t":"Și Iosif le-a zis fraților lui: „Eu sunt Iosif. Mai trăiește tatăl meu?” Și frații lui n-au putut să-i răspundă un cuvânt, căci se înspăimântaseră dinaintea lui."},{"v":4,"t":"Și Iosif le-a zis fraților lui: „Apropiați-vă, vă rog, de mine și vedeți tăietura circumciziei mele.” Și s-au apropiat, și a zis: „Eu sunt Iosif, fratele vostru, pe care m-ați vândut în Egipt („Mițrayim”)."},{"v":5,"t":"Și acum, nu vă întristați și să nu vă fie greu în ochii voștri că m-ați vândut aici, căci ca să vă țină în viață m-a trimis Domnul înaintea voastră."},{"v":6,"t":"Căci iată, de doi ani este foamete în mijlocul țării, și mai sunt cinci ani în care nu se ară și nu se seceră."},{"v":7,"t":"Și Domnul m-a trimis înaintea voastră ca să vă pună o rămășiță în țară și să vă țină în viață pentru o mare izbăvire."},{"v":8,"t":"Și acum, nu voi m-ați trimis aici, ci de la Domnul a fost pricinuit lucrul; și m-a pus mai-mare pentru Faraon și mai-mare peste toată casa lui și stăpânitor în toată țara Egiptului („Mițrayim”).","notes":["Rosen: „El m-a făcut ca părinte pentru Faraon”."]},{"v":9,"t":"Grăbiți-vă și suiți-vă la tatăl meu și spuneți-i: «Așa a zis fiul tău Iosif: Domnul m-a pus mai-mare peste toți egiptenii; coboară la mine, nu zăbovi."},{"v":10,"t":"Și vei locui în țara Goșen și vei fi aproape de mine, tu și fiii tăi și fiii fiilor tăi, și oile tale și vitele tale și tot ce este al tău."},{"v":11,"t":"Și te voi hrăni acolo, căci mai sunt încă cinci ani de foamete, ca să nu sărăcești, tu și oamenii casei tale și tot ce este al tău.»"},{"v":12,"t":"Și iată, ochii voștri văd, și ochii fratelui meu Beniamin, că gura mea vă vorbește în limba Casei Sfințeniei.","notes":["Rosen: „că gura mea este cea care vă vorbește.” „limba Casei Sfințeniei”: limba ebraică (vezi 42:23)."]},{"v":13,"t":"Și să-i povestiți tatălui meu toată cinstea pe care o am în Egipt („Mițrayim”) și toată mărirea mea pe care ați văzut-o, și să-l coborâți pe tatăl meu aici.”"},{"v":14,"t":"Și s-a plecat pe grumazul lui Beniamin, fratele lui, și a plâns, pentru că avea să fie zidită Casa Sanctuarului în partea lui Beniamin și avea să fie dărâmată de două ori; și Beniamin a plâns pe grumazul lui Iosif, pentru că a văzut Tabernacolul din Silo, care avea să fie în partea lui Iosif și avea să fie dărâmat."},{"v":15,"t":"Și i-a sărutat pe toți frații lui și a plâns asupra lor, căci a văzut că vor fi robiți printre popoare; și după aceea frații lui au vorbit cu el."},{"v":16,"t":"Și vestea s-a auzit în casa regală a lui Faraon, zicându-se: „Au venit frații lui Iosif!” Și lucrul a fost plăcut în ochii lui Faraon și în ochii slujitorilor lui."},{"v":17,"t":"Și Faraon i-a zis lui Iosif: „Spune fraților tăi: «Faceți aceasta: încărcați-vă vitele și mergeți, duceți-vă în țara Canaanului."},{"v":18,"t":"Și luați-l pe tatăl vostru și pe oamenii caselor voastre și veniți la mine, și vă voi da ce este mai bun din bunurile țării Egiptului („Mițrayim”), și veți mânca grăsimea țării.»"},{"v":19,"t":"Iar ție, Iosif, ți se poruncește să-l cinstești pe tatăl tău; de aceea spune fraților tăi: «Faceți aceasta: luați-vă din țara Egiptului („Mițrayim”) care trase de boi, ca să-i purtați în ele pe pruncii voștri și pe soțiile voastre, și să-l ridicați pe tatăl vostru și să veniți.","notes":["Rosen: „Iar ție îți este poruncit să le spui”; Targumul înțelege porunca drept cinstirea tatălui."]},{"v":20,"t":"Și ochiul vostru să nu se îndure de lucrurile voastre, căci ce este mai bun din bunurile întregii țări a Egiptului („Mițrayim”) al vostru este.»”"},{"v":21,"t":"Și fiii lui Israel au făcut așa, și Iosif le-a dat care, după cuvântul lui Faraon, și le-a dat merinde pentru drum."},{"v":22,"t":"Tuturor le-a dat, fiecăruia, veșminte de îmbrăcat; iar lui Beniamin i-a dat trei sute de sela de argint și cinci veșminte de îmbrăcat."},{"v":23,"t":"Și tatălui lui i-a trimis un dar astfel: zece măgari încărcați cu vin și din bunătățile Egiptului („Mițrayim”), și zece măgărițe încărcate cu grâne și pâine și merinde pentru tatăl lui, pentru drum.","notes":["Rosen: „zece măgari purtând ceea ce era mai bun în Egipt”; Targumul adaugă „vin”."]},{"v":24,"t":"Și și-a trimis frații, și au plecat; și le-a zis: „Nu vă certați din pricina vânzării mele, ca nu cumva să se mânie pe voi trecătorii de pe drum.”","notes":["Rosen: „Să nu vă agitați pe drum!”"]},{"v":25,"t":"Și s-au suit din Egipt („Mițrayim”) și au venit în țara Canaanului, la Iacov, tatăl lor."},{"v":26,"t":"Și i-au povestit, zicând: „Iosif încă trăiește, și el este stăpânitor peste toată țara Egiptului („Mițrayim”).” Și inima lui s-a împărțit, căci nu i-a crezut."},{"v":27,"t":"Și i-au vorbit toate cuvintele lui Iosif pe care li le vorbise, și a văzut carele pe care le trimisese Iosif ca să-l poarte; și duhul profeției, care se depărtase de la el în vremea când îl vânduseră pe Iosif, a poposit și s-a întors asupra lui Iacov, tatăl lor.","notes":["Rosen: „și duhul tatălui lor Iacov a revenit la viață.”"]},{"v":28,"t":"Și Israel a zis: „Multe bunătăți mi-a făcut Domnul: m-a izbăvit din mâinile lui Esau și din mâinile lui Laban și din mâinile canaaniților care m-au urmărit; și multe mângâieri am văzut și am nădăjduit să văd, dar aceasta n-am nădăjduit: că Iosif, fiul meu, încă trăiește. Voi merge acum și îl voi vedea înainte să mor.”"}]},{"num":46,"title":"Capitolul 46","verses":[{"v":1,"t":"Și Israel a pornit, cu tot ce era al lui, și a venit la Beer-Șeba și a jertfit jertfe Dumnezeului tatălui lui, Isaac."},{"v":2,"t":"Și Domnul i-a zis lui Israel în profeție, noaptea, și a zis: „Iacov, Iacov!” Și a zis: „Iată-mă.”"},{"v":3,"t":"Și a zis: „Eu sunt Dumnezeu, Dumnezeul tatălui tău; nu te teme să cobori în Egipt („Mițrayim”) din pricina robiei pe care am hotărât-o cu Avraam, căci un popor mare te voi face acolo."},{"v":4,"t":"Eu sunt Cel care, prin Cuvântul Meu, voi coborî cu tine în Egipt („Mițrayim”) și voi vedea suferința fiilor tăi; și Cuvântul Meu te va sui de acolo, și îi voi scoate și pe fiii tăi de acolo; și Iosif își va pune mâna pe ochii tăi.”"},{"v":5,"t":"Și Iacov s-a sculat din Beer-Șeba; și fiii lui Israel l-au purtat pe Iacov, tatăl lor, și pe pruncii lor și pe soțiile lor în carele pe care le trimisese Faraon ca să-l poarte."},{"v":6,"t":"Și și-au luat turmele și averile pe care le dobândiseră în țara Canaanului și au venit în Egipt („Mițrayim”), Iacov și toți fiii lui cu el."},{"v":7,"t":"Pe fiii lui și pe fiii fiilor lui cu el, pe fiicele lui și pe fiicele fiilor lui și toată sămânța lui i-a adus cu el în Egipt („Mițrayim”)."},{"v":8,"t":"Și acestea sunt numele fiilor lui Israel care au intrat în Egipt („Mițrayim”): Iacov și fiii lui; întâiul-născut al lui Iacov, Ruben."},{"v":9,"t":"Și fiii lui Ruben: Enoh și Palu și Hețron și Carmi."},{"v":10,"t":"Și fiii lui Simeon: Iemuel și Iamin și Ohad și Iachin și Țohar, și Saul – acesta este Zimri, care a făcut fapta canaaniților în Șitim.","notes":["Rosen: „și Saul, fiul canaanitei.” Targumul îl identifică pe Saul cu Zimri (Numeri 25:14), iar „fapta canaaniților” cu desfrânarea din Șitim (Numeri 25:1)."]},{"v":11,"t":"Și fiii lui Levi: Gherșon și Chehat și Merari."},{"v":12,"t":"Și fiii lui Iuda: Er și Onan și Șela și Pereț și Zerah; și Er și Onan au murit din pricina faptelor lor rele în țara Canaanului; și Șela și Zerah n-au născut fii în țara Canaanului; iar fiii lui Pereț care au coborât în Egipt („Mițrayim”) au fost Hețron și Hamul."},{"v":13,"t":"Și fiii lui Isahar, înțelepți și stăpâni ai socotelii, și numele lor: Tola și Puva și Iov și Șimron."},{"v":14,"t":"Și fiii lui Zabulon, negustori, stăpâni ai negoțului, care îi hrăneau pe frații lor, fiii lui Isahar, și primeau o plată asemenea lor; și numele lor: Sered și Elon și Iahleel."},{"v":15,"t":"Aceștia sunt fiii Leei, pe care i-a născut lui Iacov în Padan-Aram, și pe Dina, fiica lui; toate sufletele fiilor lui și ale fiicelor lui: treizeci și trei."},{"v":16,"t":"Și fiii lui Gad: Țifion și Haghi, Șuni și Ețbon, Eri și Arodi și Areli."},{"v":17,"t":"Și fiii lui Așer: Imna și Ișva și Ișvi și Beria, și Serah, sora lor, care a fost dusă, încă vie, în Grădină, pentru că îi vestise lui Iacov că Iosif trăiește; ea i-a izbăvit pe locuitorii din Abel de osânda morții în zilele lui Ioab. Și fiii lui Beria, care au coborât în Egipt („Mițrayim”): Heber și Malchiel.","notes":["„Grădina”: grădina Edenului. Episodul cu locuitorii din Abel: 2 Samuel 20."]},{"v":18,"t":"Aceștia sunt fiii Zilpei, pe care o dăduse Laban Leei, fiica lui; și ea i-a născut pe aceștia lui Iacov, șaisprezece suflete."},{"v":19,"t":"Fiii Rahelei, soția lui Iacov: Iosif și Beniamin."},{"v":20,"t":"Și lui Iosif i s-au născut fii în țara Egiptului („Mițrayim”), pe care i i-a născut Asenat, fiica Dinei, care fusese crescută în casa lui Poti-Fera, mai-marele din Tanis: pe Manase și pe Efraim."},{"v":21,"t":"Și fiii lui Beniamin, zece, și numele lor sunt după despărțirea de Iosif, fratele lui: Bela, pentru că fusese înghițit de la el; și Becher, pentru că era întâiul-născut al mamei lui; și Așbel, pentru că plecase în robie; Ghera, pentru că locuise ca străin într-o țară străină; și Naaman, pentru că era plăcut și cinstit; Ehi, pentru că era fratele lui, fiul mamei lui; și Roș, pentru că era cap în casa tatălui lui; Mupim, pentru că fusese vândut în Mof; Hupim, pentru că, în vremea când se despărțise de el, era de optsprezece ani și potrivit pentru baldachinul nunții; și Ard, pentru că coborâse în Egipt („Mițrayim”).","notes":["Targumul explică numele prin jocuri de cuvinte: Bela – itbelaʿ („a fost înghițit”), Becher – bukhra („întâiul-născut”), Așbel – šivya („robie”), Ghera – itgar („a locuit ca străin”), Naaman – naʿim („plăcut”), Ehi – aḥ („frate”), Roș – reš („cap”), Mupim – Mof, Hupim – ḥuppa („baldachin de nuntă”), Ard – naḥat („a coborât”). Mof: Memfis."]},{"v":22,"t":"Aceștia sunt fiii Rahelei, care i s-au născut lui Iacov; toate sufletele: paisprezece."},{"v":23,"t":"Și fiii lui Dan, iuți și negustori, și nu era număr al numărului lor.","notes":["Rosen: „Și fiii lui Dan: Hușim.” Targumul tâlcuiește numele Hușim („iuți”)."]},{"v":24,"t":"Și fiii lui Neftali: Iahțeel și Guni și Ițer și Șilem."},{"v":25,"t":"Aceștia sunt fiii Bilhei, pe care o dăduse Laban Rahelei, fiica lui; și ea i-a născut pe aceștia lui Iacov; toate sufletele: șapte."},{"v":26,"t":"Toate sufletele care au intrat cu Iacov în Egipt („Mițrayim”), ieșite din coapsa lui, afară de soțiile fiilor lui Iacov: toate sufletele, șaizeci și șase."},{"v":27,"t":"Și fiii lui Iosif, care i s-au născut în Egipt („Mițrayim”), două suflete; și Iosif, care era în Egipt, și Iochebed, fiica lui Levi, care s-a născut la intrarea lor în Egipt, între munți: numărul tuturor sufletelor casei lui Iacov care au intrat în Egipt, șaptezeci."},{"v":28,"t":"Și pe Iuda l-a trimis înaintea lui la Iosif, ca să arate drumul înaintea lui și să supună stâlpii pământului și să-i pregătească înainte un loc de popas în Goșna; și au venit în țara Goșen.","notes":["„să supună stâlpii pământului”: sensul exact al expresiei este nesigur; redat literal. Sursa are aici „Goșna” și apoi „țara Goșen”."]},{"v":29,"t":"Și Iosif și-a înhămat carul și s-a suit în întâmpinarea lui Israel, tatăl lui, la Goșen; și înainte ca tatăl lui să-l recunoască, s-a plecat înaintea lui, și s-a făcut vinovat ca anii lui să fie scurtați. Și s-a mirat și i s-a arătat, și s-a aplecat pe grumazul lui și a plâns încă pe grumazul lui, pentru că se plecase înaintea lui.","notes":["În sursă, subiectul lui „s-a plecat” nu este numit; înțelesul probabil este că tatăl lui, Iacov, s-a plecat înaintea lui Iosif, iar Iosif s-a făcut vinovat de scurtarea anilor lui."]},{"v":30,"t":"Și Israel i-a zis lui Iosif: „Dacă aș muri de data aceasta, sunt mângâiat, căci cu moartea cu care mor drepții mor eu, după ce am văzut fața ta, că încă trăiești.”"},{"v":31,"t":"Și Iosif le-a zis fraților lui și casei tatălui lui: „Mă voi sui și îi voi spune lui Faraon și îi voi zice: «Frații mei și casa tatălui meu, care erau în țara Canaanului, au venit la mine."},{"v":32,"t":"Și oamenii sunt păstori de oi, căci au fost oameni stăpâni de vite; și oile lor și vitele lor și tot ce este al lor au adus.»"},{"v":33,"t":"Și va fi, când vă va chema Faraon și va zice: «Spuneți-mi care sunt îndeletnicirile voastre»,"},{"v":34,"t":"să ziceți: «Stăpâni de vite au fost slujitorii tăi din tinerețea noastră și până acum», ca să locuiți în țara Goșen; căci egiptenii îi țin departe pe toți păstorii de oi.”","notes":["Rosen: „căci orice păstor de turme este o oroare pentru egipteni.”"]}]},{"num":47,"title":"Capitolul 47","verses":[{"v":1,"t":"Și Iosif a venit și i-a spus lui Faraon și a zis: „Tatăl meu și frații mei, și oile lor și vitele lor și tot ce este al lor au venit din țara Canaanului, și iată, ei sunt în țara Goșen.”"},{"v":2,"t":"Și dintre frații lui a luat cinci bărbați: Zabulon, Dan și Neftali, Gad și Așer, și i-a pus înaintea lui Faraon.","notes":["Rosen: „Și dintre cei mai firavi frați ai lui a luat cinci oameni”; Targumul îi numește."]},{"v":3,"t":"Și Faraon le-a zis fraților lui Iosif: „Care sunt îndeletnicirile voastre?” Și i-au zis lui Faraon: „Păstori de oi au fost slujitorii tăi, și noi, și părinții noștri.”"},{"v":4,"t":"Și i-au zis lui Faraon: „Am venit să locuim ca străini în țară, căci nu este loc de pășune pentru oile slujitorilor tăi, căci foametea este grea în țara Canaanului; și acum, să locuiască, te rugăm, slujitorii tăi în țara Goșen.”"},{"v":5,"t":"Și Faraon i-a zis lui Iosif, spunând: „Tatăl tău și frații tăi au venit la tine."},{"v":6,"t":"Țara Egiptului („Mițrayim”) este înaintea ta: în locul cel mai bun al țării așază-i pe tatăl tău și pe frații tăi; să locuiască în țara Goșen; și dacă știi că sunt între ei oameni destoinici, să-i numești mai-mari peste vitele care sunt ale mele.”"},{"v":7,"t":"Și Iosif l-a adus pe Iacov, tatăl lui, și l-a pus înaintea lui Faraon; și Iacov l-a binecuvântat pe Faraon și a zis: „Fie voia ca apele Nilului să se umple și să treacă foametea din lume în zilele tale.”","notes":["Rosen: „iar Iacov l-a binecuvântat pe Faraon.” Targumul redă conținutul binecuvântării."]},{"v":8,"t":"Și Faraon i-a zis lui Iacov: „Câte sunt zilele anilor vieții tale?”"},{"v":9,"t":"Și Iacov i-a zis lui Faraon: „Zilele anilor pribegiei mele sunt o sută treizeci de ani; puține și rele au fost zilele anilor vieții mele, căci din tinerețea mea am fugit dinaintea lui Esau, fratele meu, și am locuit ca străin într-o țară care nu era a mea; și acum, la vremea bătrâneții mele, am coborât să locuiesc ca străin aici; și zilele mele n-au ajuns zilele anilor vieții părinților mei, în zilele pribegiei lor.”"},{"v":10,"t":"Și Iacov l-a binecuvântat pe Faraon și a ieșit dinaintea lui Faraon."},{"v":11,"t":"Și Iosif i-a așezat pe tatăl lui și pe frații lui și le-a dat moștenire în țara Egiptului („Mițrayim”), în locul cel mai bun al țării, în țara Pelusiumului, cum poruncise Faraon.","notes":["Rosen: „în ținutul Raamses”; Targumul: Pelusium."]},{"v":12,"t":"Și Iosif i-a hrănit pe tatăl lui și pe frații lui și toată casa tatălui lui cu pâine, după cât era nevoie pentru prunci."},{"v":13,"t":"Și pâine nu era în toată țara, căci foametea era foarte grea; și locuitorii țării Egiptului („Mițrayim”) și locuitorii țării Canaanului au slăbit din pricina foametei."},{"v":14,"t":"Și Iosif a strâns tot argintul care se găsea în țara Egiptului („Mițrayim”) și în țara Canaanului, pentru grânele pe care le cumpărau; și Iosif a adus argintul în casa vistieriei lui Faraon."},{"v":15,"t":"Și s-a sfârșit argintul din țara Egiptului („Mițrayim”) și din țara Canaanului; și egiptenii au venit la Iosif, zicând: „Dă-ne pâine; de ce să murim înaintea ta? Căci s-a sfârșit argintul.”"},{"v":16,"t":"Și Iosif a zis: „Dați-vă vitele, și vă voi da hrană pentru vitele voastre, dacă s-a isprăvit argintul.”"},{"v":17,"t":"Și și-au adus vitele la Iosif, și Iosif le-a dat pâine pentru cai și pentru turmele de oi și pentru cirezile de boi și pentru măgari; și i-a hrănit cu pâine pentru toate vitele lor în anul acela."},{"v":18,"t":"Și s-a sfârșit anul acela, și toți egiptenii au venit la el în anul al doilea și i-au zis: „Nu vom ascunde de stăpânul meu că, dacă s-a sfârșit argintul și turmele de vite sunt ale stăpânului meu, nu ne-a mai rămas înaintea stăpânului meu decât trupurile noastre și pământurile noastre."},{"v":19,"t":"De ce să murim sub ochii tăi, și noi, și pământul nostru? Cumpără-ne pe noi și pământul nostru pentru pâine, și vom fi, noi și pământul nostru, robi lui Faraon; și dă-ne sămânță, ca să trăim și să nu murim, iar pământul să nu rămână pustiu.”"},{"v":20,"t":"Și Iosif a cumpărat tot pământul egiptenilor pentru Faraon, căci egiptenii și-au vândut fiecare câmpul, căci foametea se întărise asupra lor; și pământul a ajuns al lui Faraon pentru totdeauna."},{"v":21,"t":"Și pe poporul din provincie l-a mutat în cetăți, iar poporul din cetăți l-a mutat în provincie, de dragul fraților lui Iosif, ca să nu fie numiți pribegi; de aceea i-a mutat de la un capăt al hotarului Egiptului („Mițrayim”) până la celălalt capăt.","notes":["Rosen: „Iar poporul l-a mutat în orașe, de la un capăt al hotarului Egiptului la celălalt capăt.”"]},{"v":22,"t":"Numai pământul preoților nu l-a cumpărat, pentru că îl socotiseră nevinovat în vremea când stăpânul lui voise să-l ucidă și l-au izbăvit de osânda morții; și, mai mult, pentru că poruncise să li se dea o parte de la Faraon, și mâncau partea lor pe care le-o dăduse Faraon; de aceea nu și-au vândut pământul.","notes":["În sursă, „l-au izbăvit” se referă la Iosif (vezi 39:20). Rosen: „căci preoții aveau o rație de la Faraon”."]},{"v":23,"t":"Și Iosif a zis poporului: „Iată, v-am cumpărat astăzi, pe voi și pământul vostru, pentru Faraon; iată, aveți sămânță, și semănați pământul."},{"v":24,"t":"Și va fi, la vremea strângerii roadelor, să dați o cincime lui Faraon, iar patru părți să fie ale voastre, pentru sămânța pământului și pentru mâncarea voastră și pentru hrana caselor voastre și ca să mănânce pruncii voștri.”"},{"v":25,"t":"Și au zis: „Ne-ai ținut în viață; să găsim îndurare în ochii stăpânului meu, și vom fi robi lui Faraon.”"},{"v":26,"t":"Și Iosif a pus-o ca hotărâre până în ziua aceasta asupra țării Egiptului („Mițrayim”): să i se dea lui Faraon o cincime din roade; numai pământul preoților, numai al lor, nu era al lui Faraon."},{"v":27,"t":"Și Israel a locuit în țara Egiptului („Mițrayim”); și și-au zidit case de studiu și palate în țara Goșen și au moștenit în ea moșteniri de câmpuri și vii, și au rodit și s-au înmulțit foarte mult."},{"v":28,"t":"A trăit: și Iacov a trăit în țara Egiptului („Mițrayim”) șaptesprezece ani; și zilele lui Iacov, numărul zilelor vieții lui, au fost o sută patruzeci și șapte de ani.","notes":["Ediția sursă începe versetul cu cuvântul ebraic al Torei („A trăit”), urmat de textul aramaic."]},{"v":29,"t":"Și s-au apropiat zilele lui Israel să moară, și l-a chemat pe fiul lui, pe Iosif, și i-a zis: „Dacă am găsit, te rog, îndurare înaintea ta, pune-ți, te rog, mâna sub tăietura circumciziei mele și fă-mi, te rog, bunătate și adevăr: să nu mă îngropi, te rog, în Egipt („Mițrayim”)."},{"v":30,"t":"Și mă voi culca cu părinții mei, și să mă duci din Egipt („Mițrayim”) și să mă îngropi în mormântul lor.” Și, pentru că era fiul lui, nu și-a pus mâna, ci a zis: „Eu voi face după cuvântul tău.”","notes":["Rosen: „Și Iosif a spus: „Eu voi face după cuvântul tău.””"]},{"v":31,"t":"Și a zis: „Jură-mi!” Și i-a jurat. Și îndată i s-a descoperit slava Șechinei Domnului, și Israel s-a plecat la capul patului."}]},{"num":48,"title":"Capitolul 48","verses":[{"v":1,"t":"Și a fost, după aceste lucruri, i s-a spus lui Iosif: „Tatăl tău zace bolnav.” Și i-a luat pe cei doi fii ai lui cu el, pe Manase și pe Efraim."},{"v":2,"t":"Și i-au dat de știre lui Iacov, zicând: „Iată, fiul tău Iosif vine la tine.” Și Israel s-a întărit și a șezut pe pat."},{"v":3,"t":"Și Iacov i-a zis lui Iosif: „Dumnezeul Atotputernic mi S-a descoperit la Luz, în țara Canaanului, și m-a binecuvântat."},{"v":4,"t":"Și mi-a zis: «Iată, te voi face roditor și te voi înmulți, și te voi face o adunare de seminții, și voi da țara aceasta fiului tău după tine, moștenire veșnică.»","notes":["Rosen: „și voi da această țară urmașilor tăi după tine”; sursa are „fiului tău”."]},{"v":5,"t":"Și acum, cei doi fii ai tăi, care ți s-au născut în țara Egiptului („Mițrayim”) până să vin eu la tine în Egipt, ai mei sunt; Efraim și Manase vor fi socotiți ai mei ca Ruben și Simeon."},{"v":6,"t":"Iar fiii pe care îi vei naște după ei vor fi ai tăi; după numele fraților lor vor fi chemați în moștenirea lor."},{"v":7,"t":"Iar eu, care îți cer să mă îngropi cu părinții mei: Rahela a murit lângă mine fără veste, în țara Canaanului, pe drum, când mai era încă o bucată de pământ până să intrăm în Efrata; și n-am putut s-o duc s-o îngrop în peștera cea dublă, și am îngropat-o acolo, pe drumul Efratului, care este Betleem.”","notes":["Rosen: „Cât despre mine, când am venit din Padan, Rahela a murit în țara Canaanului”. „peștera cea dublă”: peștera Macpela (vezi 23:9)."]},{"v":8,"t":"Și Israel i-a văzut pe fiii lui Iosif și a zis: „Din cine ți s-au născut aceștia?”"},{"v":9,"t":"Și Iosif i-a zis tatălui lui: „Ei sunt fiii mei, pe care mi i-a dat Cuvântul Domnului, după scrisul acesta pe temeiul căruia am luat-o de soție pe Asenat, fiica Dinei, fiica ta.” Și a zis: „Apropie-i, te rog, de mine, și îi voi binecuvânta.”","notes":["Rosen: „pe care mi i-a dat Dumnezeu aici.” Targumul înțelege cuvântul „aici” (ba-zeh) ca „scrisul acesta”; sensul exact al aluziei este nesigur."]},{"v":10,"t":"Și ochii lui Israel erau grei de bătrânețe, nu putea să vadă; și i-a apropiat de el, și i-a sărutat și i-a îmbrățișat."},{"v":11,"t":"Și Israel i-a zis lui Iosif: „Să-ți văd fața nu gândeam, și iată, Domnul m-a făcut să-i văd și pe fiii tăi.”"},{"v":12,"t":"Și Iosif i-a scos de lângă genunchii lui și s-a plecat cu fața la pământ."},{"v":13,"t":"Și Iosif i-a luat pe amândoi: pe Efraim de-a dreapta lui, care este stânga lui Israel, și pe Manase de-a stânga lui, care este dreapta lui Israel, și i-a apropiat de el."},{"v":14,"t":"Și Israel și-a întins dreapta și a pus-o pe capul lui Efraim, deși el era cel mic, și stânga pe capul lui Manase; și-a schimbat mâinile, căci Manase era întâiul-născut."},{"v":15,"t":"Și l-a binecuvântat pe Iosif și a zis: „Domnul, înaintea Căruia au slujit părinții mei, Avraam și Isaac, Domnul care m-a hrănit de când sunt până în ziua aceasta,"},{"v":16,"t":"fie voia înaintea Ta ca îngerul pe care l-ai rânduit pentru mine ca să mă răscumpere din tot răul să-i binecuvânteze pe băieți; și să fie chemat în ei numele meu și numele părinților mei, Avraam și Isaac; și precum peștii mării se înmulțesc mult în ape, așa fiii lui Iosif să se întărească spre înmulțire în mijlocul țării.”","notes":["Rosen: „și ei să se înmulțească mult în mijlocul țării!” Targumul leagă verbul (we-yidgu) de „pește” (dag)."]},{"v":17,"t":"Și Iosif a văzut că tatăl lui pune mâna dreaptă pe capul lui Efraim, și i-a fost rău înaintea lui; și a sprijinit mâna tatălui lui, ca s-o mute de pe capul lui Efraim, ca s-o pună pe capul lui Manase."},{"v":18,"t":"Și Iosif i-a zis tatălui lui: „Nu așa, tată, căci acesta este întâiul-născut; pune-ți dreapta pe capul lui.”"},{"v":19,"t":"Dar tatăl lui a refuzat și a zis: „Știu, fiul meu, știu că el este întâiul-născut; știu și că și el va ajunge un popor mare, și el se va înmulți; dar fratele lui cel mic se va înmulți mai mult decât el, și fiii lui vor fi mulți printre popoare.”"},{"v":20,"t":"Și i-a binecuvântat în ziua aceea, zicând: „Prin tine, Iosif, fiul meu, va binecuvânta casa lui Israel pruncul în ziua circumciziei, zicând: «Să te facă Domnul ca Efraim și ca Manase.»” Și la numărarea semințiilor, mai-marele lui Efraim va fi numărat înaintea mai-marelui lui Manase; și l-a pus pe Efraim să fie înaintea lui Manase."},{"v":21,"t":"Și Israel i-a zis lui Iosif: „Iată, eu: a sosit sfârșitul meu ca să mor; și Cuvântul Domnului va fi în ajutorul vostru și vă va întoarce în țara părinților voștri."},{"v":22,"t":"Iar eu, iată, ți-am dat cetatea Sihem, o parte în dar, peste ce au frații tăi, pe care am luat-o din mâinile amoriților în vremea când ați intrat în ea; și m-am ridicat și v-am ajutat cu sabia mea și cu arcul meu.”","notes":["Rosen: „Iar eu ți-am dat Sihem, în plus față de frații tăi, pe care l-am luat din mâna amoritului cu sabia mea și cu arcul meu.”"]}]},{"num":49,"title":"Capitolul 49","verses":[{"v":1,"t":"Și Iacov i-a chemat pe fiii lui și le-a zis: „Curățiți-vă de necurăție, și vă voi vesti tainele ascunse, sorocurile tăinuite, darea plății drepților și pedeapsa celor răi și ce este umbra Edenului.” Cele douăsprezece seminții ale lui Israel s-au adunat împreună, înconjurând patul de aur pe care stătea culcat. Îndată ce i s-a descoperit slava Șechinei Domnului, sorocul la care avea să vină Regele Mesia i-a fost ascuns; și atunci a zis: „Veniți, și vă voi vesti ce vi se va întâmpla la sfârșitul zilelor.”","notes":["Rosen: „Adunați-vă și vă voi vesti ceea ce vi se va întâmpla la Sfârșitul Zilelor.” „umbra Edenului” (ṭelanita de-ʿEden): sensul exact este nesigur; redat literal."]},{"v":2,"t":"„Adunați-vă și ascultați, fiii lui Iacov, și primiți învățătură de la Israel, tatăl vostru."},{"v":3,"t":"Ruben, tu ești întâiul meu născut, începutul puterii slujirii mele și începutul ivirii gândului meu; ți s-ar fi cuvenit întâietatea și mărirea preoției și a domniei; dar, pentru că ai păcătuit, fiul meu, întâietatea a fost dată lui Iosif, domnia lui Iuda și preoția lui Levi.","notes":["„slujirii mele”: împreunarea conjugală; „ivirea gândului meu”: sensul exact este nesigur; redat literal. Rosen: „puterea mea și începutul vigorii mele, întâiul în semeție și întâiul în putere.”"]},{"v":4,"t":"Te asemăn cu o grădină mică, în care intră râuri iuți, ce se întețesc, și n-a putut să le îndure și a fost răsturnată; așa te-ai frânt, Ruben, fiul meu, căci ai păcătuit. Nu mai adăuga, și ce ai păcătuit îți va fi iertat; căci ți s-a socotit ca și cum ai fi intrat la femeia cu care se împreunase tatăl tău, în vremea când ai tulburat patul meu, pe care te-ai suit.","notes":["„așa te-ai frânt” (itraʿt): sensul exact este nesigur; poate fi înțeles și „căiește-te”. Rosen: „Năvalnic precum apa, nu vei mai avea întâietatea, căci ai urcat în patul tatălui tău”."]},{"v":5,"t":"Simeon și Levi sunt frați gemeni; unelte de război ascuțite spre jaf, prin aceasta sunt ei cunoscuți.","notes":["Rosen: „Simeon și Levi sunt frați, armele lor sunt unelte furate.” „prin aceasta sunt ei cunoscuți”: sensul exact este nesigur; redat literal."]},{"v":6,"t":"În sfatul lor sufletul meu n-a avut plăcere, și la adunarea lor la Sihem, ca s-o pustiască, slava mea nu s-a unit; căci în mânia lor au ucis pe rege și pe dregătorul lui, și în voia lor au dărâmat zidul vrăjmașilor lor.","notes":["Rosen: „Căci în furia lor au omorât un bărbat și în dorința lor au schilodit un taur.” Targumul citește cuvântul šor („taur”) ca šur („zid”)."]},{"v":7,"t":"A zis Iacov: «Blestemată a fost cetatea Sihem când au intrat în ea ca s-o pustiască, în mânia lor cea aprigă, și mânia lor împotriva lui Iosif, căci era aspră.» A zis Iacov: «Dacă vor locui amândoi laolaltă, nu este rege sau dregător care să stea înaintea lor. Voi împărți moștenirea fiilor lui Simeon în două părți: o parte îi va ieși din mijlocul moștenirii fiilor lui Iuda și o parte printre celelalte seminții ale lui Iacov; și voi risipi seminția lui Levi printre toate semințiile lui Israel.»"},{"v":8,"t":"Iuda, tu ai mărturisit fapta cu Tamar; de aceea pe tine te vor lăuda frații tăi și se vor numi iudei după numele tău. Mâinile tale își vor face dreptate de la vrăjmașii tăi, ca să arunci săgeți în ei când își vor întoarce ceafa dinaintea ta; și fiii tatălui tău vor fi cei dintâi care să te întrebe de pace.","notes":["Targumul leagă numele Iuda de „a mărturisi” (hodaʾa) și de „a lăuda” (yoduka). Rosen: „Iuda – frații tăi te vor lăuda”."]},{"v":9,"t":"Te asemăn, Iuda, fiul meu, cu un pui, fiu de lei; de la uciderea lui Iosif, fiul meu, ți-ai ridicat sufletul, și de la judecata Tamarei vei fi izbăvit. Se odihnește și locuiește cu putere ca un leu și ca o leoaică; când se odihnește, cine îl va ridica?","notes":["„ți-ai ridicat sufletul”: redat literal; înțelesul probabil este „te-ai ferit”. Rosen: „de pe pradă, fiule, te-ai ridicat.”"]},{"v":10,"t":"Nu vor înceta regi și stăpânitori din casa lui Iuda, nici cărturari care învață Tora din sămânța lui, până la vremea când va veni Regele Mesia, cel mai mic dintre fiii lui, și din pricina lui se vor topi popoarele.","notes":["Rosen: „până când va veni Silo și lui i se vor supune popoarele.” „se vor topi”: redat literal."]},{"v":11,"t":"Cât de frumos este Regele Mesia, care va să se ridice din casa lui Iuda! Și-a încins coapsele și coboară și rânduiește rânduri de război împotriva vrăjmașilor lui și ucide regi împreună cu dregătorii lor, și nu este rege sau dregător care să stea înaintea lui; înroșește munții cu sângele celor uciși de el; hainele lui sunt tăvălite în sânge, asemenea celui care calcă strugurii."},{"v":12,"t":"Cât de frumoși sunt ochii Regelui Mesia, ca vinul curat, ca să nu vadă descoperirea goliciunii și vărsarea sângelui nevinovat; și dinții lui sunt mai curați decât laptele, ca să nu mănânce ce este răpit și luat cu sila; și astfel se vor înroși munții lui și teascurile lui de vin, și dealurile lui se vor albi de roade și de stânele de oi."},{"v":13,"t":"Zabulon va locui pe țărmurile mării și va stăpâni peste porturi și va supune ținuturile mării cu corăbii, și hotarul lui va ajunge până la Sidon."},{"v":14,"t":"Isahar este bogat în Tora, o seminție puternică, ce cunoaște rânduiala vremurilor, și el se odihnește între hotarele fraților lui.","notes":["Rosen: „Isahar este un măgar ciolănos, culcat în îngrădiri.” Targumul leagă ḥamor („măgar”) de ḥamir („bogat”)."]},{"v":15,"t":"Și a văzut odihna lumii ce va să vină, că este bună, și partea țării lui Israel, că este plăcută; de aceea și-a plecat umărul ca să se ostenească în Tora, și frații lui i-au adus daruri."},{"v":16,"t":"Din casa lui Dan va să se ridice un bărbat care va judeca pe poporul lui cu judecăți de adevăr; împreună îl vor asculta semințiile lui Israel."},{"v":17,"t":"Bărbatul care va fi ales și se va ridica din casa lui Dan va fi asemenea unui șarpe veninos care stă la răscruce de drumuri, și căpeteniei șerpilor, care pândește pe cărare, care mușcă calul de călcâi, iar călărețul lui, de frica lui, cade întins pe spate; tot așa va ucide Samson, fiul lui Manoah, pe toți vitejii filistenilor, pe călăreți și pe pedestrași, și le va tăia vinele cailor și îi va doborî pe spate pe vrăjmașii lor.","notes":["Rosen: „Dan va fi șarpe pe drum, o viperă pe cărare”."]},{"v":18,"t":"A zis Iacov, când i-a văzut pe Ghedeon, fiul lui Ioas, și pe Samson, fiul lui Manoah, care aveau să se ridice ca izbăvitori: «Nu la izbăvirea lui Ghedeon nădăjduiesc eu, și nu la izbăvirea lui Samson privesc eu, căci izbăvirea lor este izbăvire de un ceas; ci la izbăvirea Ta am nădăjduit și am privit, Doamne, căci izbăvirea Ta este izbăvire veșnică.»","notes":["Ghedeon: Judecătorii 6–8; Samson: Judecătorii 13–16. Rosen: „Către salvarea Ta nădăjduiesc, Doamne!”"]},{"v":19,"t":"Seminția lui Gad: vor trece înarmați, cu celelalte seminții, râurile Arnonului și vor supune înaintea lor stâlpii pământului; și se vor întoarce înarmați, la sfârșit, cu averi multe și vor locui în liniște dincolo de Iordan; căci așa au voit, și așa a fost pentru ei, și li s-a primit moștenirea.","notes":["Rosen: „Gad – o ceată îl va asalta, dar el se va întoarce pe urmele sale.” „stâlpii pământului”: vezi nota la 46:28."]},{"v":20,"t":"Bunătățile lui Așer sunt din grăsimi; roadele pământului lui cresc mirodenii și rădăcini aromate."},{"v":21,"t":"Neftali este un sol iute, asemenea unei căprioare care aleargă pe vârfurile munților, vestitor de vești bune; el a vestit că Iosif încă trăiește; și s-a grăbit și s-a dus în Egipt („Mițrayim”) și a adus actul câmpului Kafelta, în care Esau nu are parte; și când își deschidea gura în adunarea lui Israel ca să laude, era ales din toate limbile.","notes":["Rosen: „Neftali este o căprioară slobodă, care rostește vorbe frumoase.” „actul câmpului Kafelta”: actul de proprietate al câmpului Macpela."]},{"v":22,"t":"Fiul meu, care ai crescut, Iosif, fiul meu, care ai crescut și te-ai întărit! Și ți-a fost sortit să te întărești, căci ți-ai biruit pornirea în fapta cu stăpâna ta și în fapta cu frații tăi. Te asemăn cu o viță sădită lângă izvoare de ape, care și-a trimis rădăcinile și a sfărâmat colții stâncilor și cu ramurile ei a biruit toți copacii fără rod; așa i-ai biruit, Iosif, fiul meu, prin înțelepciunea ta și prin faptele tale bune, pe toți vrăjitorii egiptenilor. Și când aduceau laude înaintea ta, fiicele dregătorilor umblau pe înălțimi și aruncau înaintea ta brățări și lănțișoare de aur, ca să-ți ridici ochii spre ele; dar nu ți-ai ridicat ochii spre niciuna din ele, ca să te faci vinovat prin ele pentru ziua marii judecăți.","notes":["Rosen: „Lăstar roditor este Iosif, lăstar roditor lângă izvor; mlădițele sale se cațără pe ziduri.”"]},{"v":23,"t":"Și l-au amărât și s-au certat cu el toți vrăjitorii egiptenilor, și l-au și pârât înaintea lui Faraon, gândind să-l coboare din cinstea lui; au vorbit împotriva lui limbă a treia, care este aspră ca săgețile.","notes":["„limbă a treia”: clevetirea. Rosen: „L-au amărât, l-au săgetat, l-au hărțuit arcașii.”"]},{"v":24,"t":"Și s-a întors să-și așeze la starea dintâi puterea mădularului său, ca să nu se împreuneze cu stăpâna lui; și i s-au risipit mâinile de la gândul seminței, și și-a biruit pornirea prin învățătura puternică pe care o primise de la Iacov; și de acolo s-a învrednicit să fie hrănitor (sau „conducător”) și să fie unit în săpătura numelor pe pietrele lui Israel.","notes":["Rosen: „Dar arcul lui a rămas întins și brațele mâinilor lui întărite din mâinile Puternicului lui Iacov, de acolo, de la Păstorul pietrei lui Israel”. Targumul tâlcuiește versetul despre ispita din casa lui Potifar (cf. Talmud, Sota 36b)."]},{"v":25,"t":"Din Cuvântul Dumnezeului tatălui tău să fie ajutorul tău, și Cel care Se numește Atotputernic să te binecuvânteze cu binecuvântări care coboară din roua cerurilor de sus și din bunătatea binecuvântărilor izvoarelor adâncului, care urcă și acoperă vlăstarii de jos; binecuvântați să fie sânii care te-au alăptat și pântecele în care ai stat."},{"v":26,"t":"Binecuvântările tatălui tău să se adauge la binecuvântările cu care m-au binecuvântat părinții mei, Avraam și Isaac, pe care le-au râvnit mai-marii lumii: Ismael și Esau și toți fiii Cheturei; să se adune toate aceste binecuvântări și să se facă o cunună de mărire pe capul lui Iosif și pe creștetul bărbatului care a fost mare și stăpânitor în Egipt („Mițrayim”) și grijuliu cu cinstea fraților lui.","notes":["Rosen: „Binecuvântările tatălui tău au depășit binecuvântările părinților mei, până la marginea dealurilor lumii.”"]},{"v":27,"t":"Beniamin este o seminție puternică, ca lupul care sfâșie; în țara lui va locui Șechina Stăpânului lumii și în moștenirea lui va fi zidită Casa Sanctuarului; dimineața preoții vor aduce mielul cel neîncetat, până la patru ceasuri, și între cele două amurguri vor aduce mielul al doilea, iar seara vor împărți rămășițele celorlalte jertfe și vor mânca, fiecare partea lui.”","notes":["Rosen: „Beniamin este un lup care va sfâșia; dimineața va devora pradă, iar seara va împărți captură.”"]},{"v":28,"t":"Toate acestea sunt semințiile lui Israel, douăsprezece, toți drepți laolaltă; și aceasta este ce le-a vorbit tatăl lor, și i-a binecuvântat; pe fiecare după binecuvântarea lui i-a binecuvântat."},{"v":29,"t":"Și le-a poruncit și le-a zis: „Eu sunt adunat la poporul meu; îngropați-mă lângă părinții mei, în peștera care este în câmpul lui Efron hititul,"},{"v":30,"t":"în peștera care este în câmpul Kafelta, care este în fața lui Mamre, în țara Canaanului, pe care Avraam a cumpărat-o cu câmpul de la Efron hititul, ca moștenire pentru mormânt."},{"v":31,"t":"Acolo i-au îngropat pe Avraam și pe Sara, soția lui; acolo i-au îngropat pe Isaac și pe Rebeca, soția lui; și acolo am îngropat-o pe Lea."},{"v":32,"t":"Cumpărătura câmpului și a peșterii care este în el, de la fiii hititului.”","notes":["Rosen: „de la fiii lui Het.”"]},{"v":33,"t":"Și Iacov a sfârșit de poruncit fiilor lui și și-a strâns picioarele în pat și și-a dat sufletul și a fost adunat la poporul lui."}]},{"num":50,"title":"Capitolul 50","verses":[{"v":1,"t":"Și Iosif l-a culcat pe tatăl lui pe un pat de fildeș (šandfin), îmbrăcat cu aur bun, încrustat cu pietre scumpe și întărit cu funii de in subțire. Acolo turnau vinuri înfierbântate și acolo ardeau mirodenii alese; acolo stăteau bărbați din casa lui Esau și bărbați din casa lui Israel; acolo stătea leul Iuda, viteazul fraților lui. A răspuns și a zis fraților lui: „Veniți să zidim deasupra tatălui nostru un cedru înalt, al cărui vârf ajunge până la creștetul cerurilor, iar ramurile lui umbresc pe toți locuitorii pământului și rădăcinile lui ajung până în adâncul pământului: din el s-au ridicat douăsprezece seminții, din el vor să se ridice regi și stăpânitori, și preoții, în cetele lor, ca să aducă jertfe, și din el leviții, în rândurile lor, ca să cânte.” Și atunci Iosif s-a plecat pe fața tatălui lui și a plâns asupra lui și l-a sărutat.","notes":["šandfin: sensul cuvântului este nesigur (fildeș sau un lemn prețios). Rosen: „Iosif a căzut pe fața tatălui său și a plâns pe el și l-a sărutat.”"]},{"v":2,"t":"Și Iosif le-a poruncit slujitorilor lui, doctorilor, să-l îmbălsămeze pe tatăl lui; și doctorii l-au îmbălsămat pe Israel."},{"v":3,"t":"Și i s-au împlinit, de când a fost îmbălsămat, patruzeci de zile, căci așa se împlinesc zilele celor îmbălsămați; și egiptenii l-au plâns șaptezeci de zile, zicând unii către alții: „Veniți să-l plângem pe Iacov cel evlavios, pentru meritul căruia a trecut foametea din țara Egiptului („Mițrayim”); căci hotărârea fusese să fie foamete patruzeci și doi de ani, iar pentru meritul lui Iacov au fost opriți patruzeci de ani de la Egipt, și n-a fost foamete decât doi ani.”","notes":["Rosen: „și l-au jelit egiptenii șaptezeci de zile.”"]},{"v":4,"t":"Și au trecut zilele plânsului lui, și Iosif a vorbit cu mai-marii casei lui Faraon, zicând: „Dacă, rogu-vă, am găsit îndurare în ochii voștri, vorbiți, vă rog, în auzul lui Faraon, zicând:"},{"v":5,"t":"«Tatăl meu m-a pus să jur, zicând: ‘Iată, eu mor; în mormântul meu, pe care mi l-am săpat în țara Canaanului, acolo să mă îngropi.’ Și acum, să mă sui, te rog, să-l îngrop pe tatăl meu, și mă voi întoarce.»”"},{"v":6,"t":"Și Faraon a zis: „Suie-te și îngroapă-l pe tatăl tău, cum te-a pus să juri.”"},{"v":7,"t":"Și Iosif s-a suit să-l îngroape pe tatăl lui, și s-au suit cu el toți slujitorii lui Faraon, bătrânii casei lui, și toți bătrânii țării Egiptului („Mițrayim”),"},{"v":8,"t":"și toți oamenii casei lui Iosif, și frații lui, și casa tatălui lui; numai pruncii lor și oile lor și vitele lor le-au lăsat în țara Goșen."},{"v":9,"t":"Și s-au suit cu el și care, și călăreți, și tabăra era foarte mare."},{"v":10,"t":"Și au venit până la aria lui Atad, care este dincolo de Iordan, și au jelit acolo o jale mare și foarte grea; și i-a făcut tatălui lui un doliu de șapte zile.","notes":["Rosen: „Au ajuns la Goren-Atad”; Targumul traduce numele („aria lui Atad”)."]},{"v":11,"t":"Și locuitorii țării, canaaniții, au văzut doliul la aria lui Atad și și-au dezlegat legăturile brâurilor pentru cinstea lui Iacov, și arătau cu mâinile și ziceau: „Doliu greu este acesta pentru Egipt („Mițrayim”)!” De aceea a pus numele locului Abel-Mițraim, care este dincolo de Iordan."},{"v":12,"t":"Și fiii lui i-au făcut așa, cum le poruncise."},{"v":13,"t":"Și fiii lui l-au dus în țara Canaanului. Și vestea a fost auzită de Esau cel rău, și a pornit de la muntele Gavla cu legiuni multe și a venit la Hebron, și nu-l lăsa pe Iosif să-l îngroape pe tatăl lui în peștera Kafelta. Îndată s-a dus Neftali și a alergat și a coborât în Egipt („Mițrayim”) și a venit în aceeași zi și a adus actul pe care Esau îl scrisese lui Iacov, fratele lui, despre împărțirea peșterii Kafelta. Și îndată i-a făcut semn lui Hușim, fiul lui Dan, și acesta a luat sabia și a tăiat capul lui Esau cel rău; și capul lui Esau s-a rostogolit până a intrat în peșteră și s-a odihnit în sânul lui Isaac, tatăl lui; iar trupul lui l-au îngropat fiii lui Esau în câmpul Kafelta. Și după aceea fiii lui Iacov l-au îngropat în peștera câmpului Kafelta, câmpul pe care Avraam îl cumpărase ca moștenire pentru mormânt de la Efron hititul, în fața lui Mamre.","notes":["Rosen: „Fiii lui l-au dus în țara Canaanului și l-au îngropat în peștera din câmpul Macpela”; Kafelta = Macpela (vezi 23:9). „actul”: vezi 49:21."]},{"v":14,"t":"Și Iosif s-a întors în Egipt („Mițrayim”), el și frații lui și toți cei care se suiseră cu el să-l îngroape pe tatăl lui, după ce l-a îngropat pe tatăl lui."},{"v":15,"t":"Și frații lui Iosif au văzut că tatăl lor murise și că el nu mai ședea cu ei laolaltă la masă ca să mănânce; și au zis: „Poate că Iosif ne păstrează ură și ne va întoarce tot răul pe care i l-am făcut.”","notes":["Rosen: „Poate Iosif ne va urî și ne va întoarce într-adevăr tot răul pe care i l-am făcut.”"]},{"v":16,"t":"Și au trimis-o pe Bilha cu poruncă să-i spună lui Iosif: „Tatăl tău a poruncit înainte de moartea lui, zicând:"},{"v":17,"t":"«Așa să-i spuneți lui Iosif: ‘Rogu-te, iartă acum vinile fraților tăi și păcatele lor, căci rău ți-au făcut.’» Și acum, iartă, te rugăm, vinile slujitorilor Dumnezeului tatălui tău.” Și Iosif a plâns când i-au vorbit."},{"v":18,"t":"Și s-au dus și frații lui și s-au plecat înaintea lui și au zis: „Iată, suntem robii tăi.”"},{"v":19,"t":"Și Iosif le-a zis: „Nu vă temeți, căci nu vă vom răsplăti cu rău, ci cu bine; căci eu sunt temător și smerit înaintea Domnului.","notes":["Rosen: „Nu vă temeți, căci sunt eu oare în locul lui Dumnezeu?”"]},{"v":20,"t":"Și voi ați gândit asupra mea gânduri rele: că, dacă nu ședeam la masă cu voi ca să mănânc, era pentru că vă păstrez ură; dar Cuvântul Domnului a gândit asupra mea spre bine. Căci tatăl meu mă așeza în frunte, și din cinstea lui primeam; iar acum nu primesc, ca să mă învrednicesc să se facă pentru noi izbăvire, ca în ziua aceasta, ca să se țină în viață un popor mult din casa lui Iacov."},{"v":21,"t":"Și acum, nu vă temeți: eu vă voi hrăni pe voi și pe pruncii voștri.” Și i-a mângâiat și le-a vorbit cuvinte de mângâiere la inimă."},{"v":22,"t":"Și Iosif a locuit în Egipt („Mițrayim”), el și casa tatălui lui; și Iosif a trăit o sută zece ani.","notes":["Ediția sursă scrie aici „o sută și ʿasri” (formă neobișnuită; „douăzeci” ar fi ʿesrin); redat după 50:26 și Rosen: „o sută zece ani”."]},{"v":23,"t":"Și Iosif i-a văzut lui Efraim fii din a treia generație; și pe fiii lui Machir, fiul lui Manase, când s-au născut, i-a circumcis Iosif.","notes":["Rosen: „au crescut pe genunchii lui Iosif.”"]},{"v":24,"t":"Și Iosif le-a zis fraților lui: „Iată, eu mor; și Domnul își va aminti negreșit de voi și vă va sui din țara aceasta în țara pe care a jurat-o lui Avraam, lui Isaac și lui Iacov.”"},{"v":25,"t":"Și Iosif i-a pus pe fiii lui Israel să jure, zicând fiilor lor: „Iată, voi veți fi robiți în Egipt („Mițrayim”); și să nu cutezați să vă suiți din Egipt până la vremea când vor veni doi izbăvitori și vă vor zice: «Domnul își va aminti negreșit de voi»; și în vremea când vă veți sui, să-mi suiți oasele de aici.”","notes":["Rosen: „Dumnezeu își va aminti negreșit de voi; și atunci îmi veți ridica oasele de aici.” „doi izbăvitori”: după tradiție, Moise și Aaron."]},{"v":26,"t":"Și Iosif a murit în vârstă de o sută zece ani; și l-au îmbălsămat și l-au înmiresmat și l-au pus într-un sicriu și l-au scufundat în mijlocul Nilului Egiptului („Mițrayim”).","notes":["Rosen: „și a fost depus într-un sicriu în Egipt.”"]}]}]};
